import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.model.security.PermissionCollection;

/**
 * @author Nils Bühner
 */
public class PermissionCollectionPermissionEvaluator<E extends PermissionCollection> extends
    PersistentObjectPermissionEvaluator<E> {

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public PermissionCollectionPermissionEvaluator() {
        this((Class<E>) PermissionCollection.class);
    }

    /**
     * Constructor for subclasses
     *
     * @param entityClass
     */
    protected PermissionCollectionPermissionEvaluator(Class<E> entityClass) {
        super(entityClass);
    }

    /**
     * Always grants every permission on permission collections.
     */
    @Override
    public boolean hasPermission(User user, E permissionCollection, Permission permission) {

        // it is necessary to grant every permission.
        // otherwise permission collections could not be created or updated.
        return true;
    }

}
package de.terrestris.shoguncore.security.access.entity;

import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.security.Permission;

/**
 * @author Nils Bühner
 */
public class UserPermissionEvaluator<E extends User> extends
    PersistentObjectPermissionEvaluator<E> {

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public UserPermissionEvaluator() {
        this((Class<E>) User.class);
    }

    /**
     * Constructor for subclasses
     *
     * @param entityClass
     */
    protected UserPermissionEvaluator(Class<E> entityClass) {
        super(entityClass);
    }

    /**
     * Grants READ permission on the user object of the currently logged in
     * user. Uses default implementation otherwise.
     */
    @Override
    public boolean hasPermission(User user, E entity, Permission permission) {

        // always grant READ access to own user object (of the logged in user)
        if (user != null && user.equals(entity)
            && permission.equals(Permission.READ)) {
            logger.trace("Granting READ access on own user object");
            return true;
        }

        // call parent implementation
        return super.hasPermission(user, entity, permission);
    }

}
package de.terrestris.shoguncore.security.access.entity;

import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.UserGroup;
import de.terrestris.shoguncore.model.security.Permission;

/**
 * @author Nils Bühner
 */
public class UserGroupPermissionEvaluator<E extends UserGroup> extends
    PersistentObjectPermissionEvaluator<E> {

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public UserGroupPermissionEvaluator() {
        this((Class<E>) UserGroup.class);
    }

    /**
     * Constructor for subclasses
     *
     * @param entityClass
     */
    protected UserGroupPermissionEvaluator(Class<E> entityClass) {
        super(entityClass);
    }

    /**
     * Grants READ permission on groups where the user is a member.
     * Uses default implementation otherwise.
     */
    @Override
    public boolean hasPermission(User user, E userGroup, Permission permission) {

        // always grant READ access to groups in which the user itself is a member
        if (user != null && permission.equals(Permission.READ)
            && userGroup.getMembers().contains(user)) {
            logger.trace("Granting READ access on group where the user is member.");
            return true;
        }

        // call parent implementation
        return super.hasPermission(user, userGroup, permission);
    }

}
package de.terrestris.shoguncore.security.access.entity;

import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.security.Permission;

/**
 * @author Nils Bühner
 */
public class AlwaysAllowReadPermissionEvaluator<E extends PersistentObject> extends
    PersistentObjectPermissionEvaluator<E> {

    /**
     * Default constructor
     */
    @SuppressWarnings("unchecked")
    public AlwaysAllowReadPermissionEvaluator() {
        this((Class<E>) PersistentObject.class);
    }

    /**
     * Constructor for subclasses
     *
     * @param entityClass
     */
    protected AlwaysAllowReadPermissionEvaluator(Class<E> entityClass) {
        super(entityClass);
    }

    /**
     * Grants READ permission on the user object of the currently logged in
     * user. Uses default implementation otherwise.
     */
    @Override
    public boolean hasPermission(User user, E entity, Permission permission) {

        // always grant READ access ("unsecured" object)
        if (permission.equals(Permission.READ)) {
            logger.trace("Granting READ access on " + entity.getClass().getSimpleName() + " with ID " + entity.getId());
            return true;
        }

        // call parent implementation
        return super.hasPermission(user, entity, permission);
    }

}
