{"content": "// A small JSON value type with a Jackson-compatible writer (Java Double.toString
// formatting) and a lenient parser that preserves the raw literal text of numbers
// (Jackson uses the raw text when coercing numbers to strings).

#[derive(Clone, Debug)]
pub enum JVal {
    Null,
    Bool(bool),
    Int(i64, String),    // parsed value + raw literal
    Float(f64, String),  // parsed value + raw literal
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

impl PartialEq for JVal {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (JVal::Null, JVal::Null) => true,
            (JVal::Bool(a), JVal::Bool(b)) => a == b,
            (JVal::Int(a, _), JVal::Int(b, _)) => a == b,
            (JVal::Float(a, _), JVal::Float(b, _)) => a == b,
            (JVal::Str(a), JVal::Str(b)) => a == b,
            (JVal::Arr(a), JVal::Arr(b)) => a == b,
            (JVal::Obj(a), JVal::Obj(b)) => a == b,
            _ => false,
        }
    }
}

impl JVal {
    pub fn get<'a>(&'a self, key: &str) -> Option<&'a JVal> {
        match self {
            JVal::Obj(entries) => {
                // Jackson: later duplicate keys win
                let mut found = None;
                for (k, v) in entries {
                    if k == key {
                        found = Some(v);
                    }
                }
                found
            }
            _ => None,
        }
    }

    pub fn is_obj(&self) -> bool {
        matches!(self, JVal::Obj(_))
    }

    /// JsonNode.asInt() semantics
    pub fn as_int(&self) -> i64 {
        match self {
            JVal::Int(v, _) => *v,
            JVal::Float(v, _) => *v as i64,
            JVal::Bool(b) => {
                if *b {
                    1
                } else {
                    0
                }
            }
            JVal::Str(s) => s.trim().parse::<i64>().unwrap_or(0),
            _ => 0,
        }
    }
}

pub fn jstr(s: &str) -> JVal {
    JVal::Str(s.to_string())
}
pub fn jint(v: i64) -> JVal {
    JVal::Int(v, v.to_string())
}
pub fn jdouble(v: f64) -> JVal {
    JVal::Float(v, String::new())
}
pub fn jbool(v: bool) -> JVal {
    JVal::Bool(v)
}
pub fn jobj(entries: Vec<(String, JVal)>) -> JVal {
    JVal::Obj(entries)
}
pub fn jarr(items: Vec<JVal>) -> JVal {
    JVal::Arr(items)
}

// ---------------------------------------------------------------------------
// Java Double.toString compatible formatting
// ---------------------------------------------------------------------------

pub fn java_double(v: f64) -> String {
    if v.is_nan() {
        return "NaN".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 {
            "Infinity".to_string()
        } else {
            "-Infinity".to_string()
        };
    }
    // Rust's {:e} produces the shortest round-trip representation with one
    // digit before the decimal point, matching the digits Java produces.
    let s = format!("{:e}", v);
    let (mant, exp) = match s.split_once('e') {
        Some(p) => p,
        None => return s,
    };
    let exp: i32 = exp.parse().unwrap_or(0);
    let neg = mant.starts_with('-');
    let m = mant.trim_start_matches('-');
    let digits: String = m.chars().filter(|c| *c != '.').collect();
    let digits = if digits.is_empty() {
        "0".to_string()
    } else {
        digits
    };

    let mut out = String::new();
    if (-3..=6).contains(&exp) {
        // plain notation
        if neg {
            out.push('-');
        }
        if exp >= 0 {
            let int_len = exp as usize + 1;
            if digits.len() <= int_len {
                out.push_str(&digits);
                for _ in 0..(int_len - digits.len()) {
                    out.push('0');
                }
                out.push_str(".0");
            } else {
                out.push_str(&digits[..int_len]);
                out.push('.');
                out.push_str(&digits[int_len..]);
            }
        } else {
            out.push_str("0.");
            for _ in 0..((-exp) as usize - 1) {
                out.push('0');
            }
            out.push_str(&digits);
        }
        out
    } else {
        if neg {
            out.push('-');
        }
        out.push_str(&digits[..1]);
        out.push('.');
        if digits.len() > 1 {
            out.push_str(&digits[1..]);
        } else {
            out.push('0');
        }
        out.push('E');
        out.push_str(&exp.to_string());
        out
    }
}

// Java Integer/Long/Double toString for storing property values in the DB
pub fn java_to_string(v: &JVal) -> Option<String> {
    match v {
        JVal::Null => None,
        JVal::Bool(b) => Some(if *b { "true".into() } else { "false".into() }),
        JVal::Int(i, _) => Some(i.to_string()),
        JVal::Float(f, _) => Some(java_double(*f)),
        JVal::Str(s) => Some(s.clone()),
        JVal::Arr(items) => {
            // java.util.List.toString
            let parts: Vec<String> = items
                .iter()
                .map(|i| java_to_string(i).unwrap_or_else(|| "null".into()))
                .collect();
            Some(format!("[{}]", parts.join(", ")))
        }
        JVal::Obj(entries) => {
            // java.util.Map.toString
            let parts: Vec<String> = entries
                .iter()
                .map(|(k, v)| {
                    format!(
                        "{}={}",
                        k,
                        java_to_string(v).unwrap_or_else(|| "null".into())
                    )
                })
                .collect();
            Some(format!("{{{}}}", parts.join(", ")))
        }
    }
}

// ---------------------------------------------------------------------------
// Writer
// ---------------------------------------------------------------------------

pub fn write_json(v: &JVal, out: &mut String) {
    match v {
        JVal::Null => out.push_str("null"),
        JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JVal::Int(i, _) => out.push_str(&i.to_string()),
        JVal::Float(f, _) => {
            if f.is_nan() {
                out.push_str("\"NaN\"");
            } else if f.is_infinite() {
                if *f > 0.0 {
                    out.push_str("\"Infinity\"");
                } else {
                    out.push_str("\"-Infinity\"");
                }
            } else {
                out.push_str(&java_double(*f));
            }
        }
        JVal::Str(s) => write_json_string(s, out),
        JVal::Arr(items) => {
            out.push('[');
            let mut first = true;
            for it in items {
                if !first {
                    out.push(',');
                }
                first = false;
                write_json(it, out);
            }
            out.push(']');
        }
        JVal::Obj(entries) => {
            out.push('{');
            let mut first = true;
            for (k, val) in entries {
                if !first {
                    out.push(',');
                }
                first = false;
                write_json_string(k, out);
                out.push(':');
                write_json(val, out);
            }
            out.push('}');
        }
    }
}

pub fn write_json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

pub fn to_json_string(v: &JVal) -> String {
    let mut out = String::new();
    write_json(v, &mut out);
    out
}

// ---------------------------------------------------------------------------
// Parser (strict JSON, Jackson default features)
// ---------------------------------------------------------------------------

pub struct ParseError(pub String);

pub fn parse_json(input: &str) -> Result<JVal, ParseError> {
    let bytes: Vec<char> = input.chars().collect();
    let mut pos = 0usize;
    skip_ws(&bytes, &mut pos);
    let v = parse_value(&bytes, &mut pos)?;
    skip_ws(&bytes, &mut pos);
    if pos != bytes.len() {
        return Err(ParseError("trailing characters".into()));
    }
    Ok(v)
}

fn skip_ws(b: &[char], pos: &mut usize) {
    while *pos < b.len() && matches!(b[*pos], ' ' | '\t' | '\n' | '\r') {
        *pos += 1;
    }
}

fn parse_value(b: &[char], pos: &mut usize) -> Result<JVal, ParseError> {
    if *pos >= b.len() {
        return Err(ParseError("unexpected end of input".into()));
    }
    match b[*pos] {
        '{' => parse_obj(b, pos),
        '[' => parse_arr(b, pos),
        '"' => Ok(JVal::Str(parse_str(b, pos)?)),
        't' => {
            expect_lit(b, pos, "true")?;
            Ok(JVal::Bool(true))
        }
        'f' => {
            expect_lit(b, pos, "false")?;
            Ok(JVal::Bool(false))
        }
        'n' => {
            expect_lit(b, pos, "null")?;
            Ok(JVal::Null)
        }
        _ => parse_number(b, pos),
    }
}

fn expect_lit(b: &[char], pos: &mut usize, lit: &str) -> Result<(), ParseError> {
    for c in lit.chars() {
        if *pos >= b.len() || b[*pos] != c {
            return Err(ParseError(format!("expected {}", lit)));
        }
        *pos += 1;
    }
    Ok(())
}

fn parse_obj(b: &[char], pos: &mut usize) -> Result<JVal, ParseError> {
    *pos += 1; // {
    let mut entries: Vec<(String, JVal)> = Vec::new();
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == '}' {
        *pos += 1;
        return Ok(JVal::Obj(entries));
    }
    loop {
        skip_ws(b, pos);
        if *pos >= b.len() || b[*pos] != '"' {
            return Err(ParseError("expected property name".into()));
        }
        let key = parse_str(b, pos)?;
        skip_ws(b, pos);
        if *pos >= b.len() || b[*pos] != ':' {
            return Err(ParseError("expected ':'".into()));
        }
        *pos += 1;
        skip_ws(b, pos);
        let val = parse_value(b, pos)?;
        // later duplicate keys win (Jackson keeps last)
        if let Some(existing) = entries.iter_mut().find(|(k, _)| *k == key) {
            existing.1 = val;
        } else {
            entries.push((key, val));
        }
        skip_ws(b, pos);
        if *pos >= b.len() {
            return Err(ParseError("unexpected end in object".into()));
        }
        match b[*pos] {
            ',' => *pos += 1,
            '}' => {
                *pos += 1;
                return Ok(JVal::Obj(entries));
            }
            _ => return Err(ParseError("expected ',' or '}'".into())),
        }
    }
}

fn parse_arr(b: &[char], pos: &mut usize) -> Result<JVal, ParseError> {
    *pos += 1; // [
    let mut items: Vec<JVal> = Vec::new();
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == ']' {
        *pos += 1;
        return Ok(JVal::Arr(items));
    }
    loop {
        skip_ws(b, pos);
        let v = parse_value(b, pos)?;
        items.push(v);
        skip_ws(b, pos);
        if *pos >= b.len() {
            return Err(ParseError("unexpected end in array".into()));
        }
        match b[*pos] {
            ',' => *pos += 1,
            ']' => {
                *pos += 1;
                return Ok(JVal::Arr(items));
            }
            _ => return Err(ParseError("expected ',' or ']'".into())),
        }
    }
}

fn parse_str(b: &[char], pos: &mut usize) -> Result<String, ParseError> {
    *pos += 1; // opening quote
    let mut s = String::new();
    loop {
        if *pos >= b.len() {
            return Err(ParseError("unterminated string".into()));
        }
        let c = b[*pos];
        *pos += 1;
        match c {
            '"' => return Ok(s),
            '\\' => {
                if *pos >= b.len() {
                    return Err(ParseError("unterminated escape".into()));
                }
                let e = b[*pos];
                *pos += 1;
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{08}'),
                    't' => s.push('\t'),
                    'n' => s.push('\n'),
                    'f' => s.push('\u{0c}'),
                    'r' => s.push('\r'),
