// Entity model mirroring the Java classes of shogun-core, with
// Jackson-compatible serialisation and the EqualsBuilder/HashCode based
// set-deduplication semantics of PersistentObject (equals compares the
// class + created timestamp + the declared fields, NOT the id).

use crate::jval::*;

pub type PermMap = Vec<(i32, Vec<String>)>; // principal id -> permission names

pub fn now_ms() -> i64 {
    chrono::Utc::now().timestamp_millis()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Perm {
    Admin,
    Create,
    Delete,
    Update,
    Read,
}

impl Perm {
    pub fn from_str_opt(s: &str) -> Option<Perm> {
        match s.to_ascii_uppercase().as_str() {
            "ADMIN" => Some(Perm::Admin),
            "CREATE" => Some(Perm::Create),
            "DELETE" => Some(Perm::Delete),
            "UPDATE" => Some(Perm::Update),
            "READ" => Some(Perm::Read),
            _ => None,
        }
    }
    pub fn name(&self) -> &'static str {
        match self {
            Perm::Admin => "ADMIN",
            Perm::Create => "CREATE",
            Perm::Delete => "DELETE",
            Perm::Update => "UPDATE",
            Perm::Read => "READ",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl Role {
    pub fn new_parsed() -> Role {
        let n = now_ms();
        Role {
            id: None,
            name: None,
            description: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
    pub fn new_restricted() -> Role {
        Role::new_parsed()
    }
}

#[derive(Clone, Debug)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<String>, // "YYYY-MM-DD"
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<UserGroup>>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl User {
    pub fn new_parsed() -> User {
        let n = now_ms();
        User {
            id: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(vec![]),
            user_groups: Some(vec![]),
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

#[derive(Clone, Debug)]
pub struct UserGroup {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub owner: Option<Box<User>>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl UserGroup {
    pub fn new_parsed() -> UserGroup {
        let n = now_ms();
        UserGroup {
            id: None,
            name: None,
            owner: None,
            members: Some(vec![]),
            roles: Some(vec![]),
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
    pub fn new_stub(id: i32) -> UserGroup {
        let mut g = UserGroup::new_parsed();
        g.id = Some(id);
        g
    }
}

#[derive(Clone, Debug)]
pub struct LayerAppearance {
    pub id: Option<i32>,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Vec<(String, JVal)>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl LayerAppearance {
    pub fn new_parsed() -> LayerAppearance {
        let n = now_ms();
        LayerAppearance {
            id: None,
            attribution: None,
            hoverable: None,
            clickable: None,
            hover_template: None,
            properties: Some(vec![]),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

#[derive(Clone, Debug)]
pub struct Extent {
    pub id: Option<i32>,
    pub lower_left: Option<(f64, f64)>,
    pub upper_right: Option<(f64, f64)>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl Extent {
    pub fn new_parsed() -> Extent {
        let n = now_ms();
        Extent {
            id: None,
            lower_left: None,
            upper_right: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

#[derive(Clone, Debug)]
pub struct TileGrid {
    pub is_wmts: bool,
    pub id: Option<i32>,
    pub type_: Option<String>,
    pub origin: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>, // tileGridExtent (cascade SAVE_UPDATE)
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>, // tileGridResolutions (null default)
    pub matrix_ids: Option<Vec<String>>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl TileGrid {
    pub fn new_parsed(is_wmts: bool) -> TileGrid {
        let n = now_ms();
        TileGrid {
            is_wmts,
            id: None,
            type_: None,
            origin: None,
            extent: None,
            tile_size: Some(256), // constructor default
            resolutions: None,
            matrix_ids: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DsKind {
    ImageWms,
    TileWms,
    Wfs,
    Wmts,
    Xyz,
}

#[derive(Clone, Debug)]
pub struct DataSource {
    pub kind: DsKind,
    pub id: Option<i32>,
    pub name: Option<String>,
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    // ImageWms / TileWms
    pub width: i32,
    pub height: i32,
    pub version: Option<String>, // also used for WFS version
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
    // TileWms
    pub tile_grid: Option<Box<TileGrid>>,
    pub request_with_tiled: Option<bool>,
    // Wfs
    pub type_name: Option<String>,
    pub type_names: Option<String>,
    // Wmts
    pub urls: Option<Vec<String>>, // null default (no initializer)
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
    // Xyz
    pub center: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>, // OneToOne, no cascade
    pub resolutions: Option<Vec<(f64, f64)>>, // empty-list default
    pub tile_size: Option<i32>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl DataSource {
    pub fn new_parsed(kind: DsKind) -> DataSource {
        let n = now_ms();
        DataSource {
            kind,
            id: None,
            name: None,
            type_: None,
            url: None,
            format: None,
            width: 0,
            height: 0,
            version: None,
            layer_names: None,
            layer_styles: None,
            requestable_by_path: None,
            custom_request_path: None,
            tile_grid: None,
            // TileWmsLayerDataSource field initializer: Boolean.TRUE
            request_with_tiled: Some(true),
            type_name: None,
            type_names: None,
            urls: None,
            wmts_layer: None,
            wmts_style: None,
            projection: None,
            matrix_set: None,
            request_encoding: None,
            capabilities_url: None,
            center: None,
            extent: None,
            resolutions: Some(vec![]),
            tile_size: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

#[derive(Clone, Debug)]
pub struct Layer {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<Box<DataSource>>,
    pub appearance: Option<Box<LayerAppearance>>,
    pub created_ms: i64,
    pub modified_ms: i64,
    pub user_perms: PermMap,
    pub group_perms: PermMap,
}

impl Layer {
    pub fn new_parsed() -> Layer {
        let n = now_ms();
        Layer {
            id: None,
            name: None,
            description: None,
            source: None,
            appearance: None,
            created_ms: n,
            modified_ms: n,
            user_perms: vec![],
            group_perms: vec![],
        }
    }
}

// ---------------------------------------------------------------------------
// Java equals() simulation (used for HashSet deduplication of parsed objects)
// ---------------------------------------------------------------------------

pub fn user_equals(a: &User, b: &User) -> bool {
    a.created_ms == b.created_ms
        && a.first_name == b.first_name
        && a.last_name == b.last_name
        && a.email == b.email
        && a.birthday == b.birthday
        && a.language == b.language
        && a.account_name == b.account_name
        && a.password == b.password
        && a.active == b.active
}

pub fn role_equals(a: &Role, b: &Role) -> bool {
    a.created_ms == b.created_ms && a.name == b.name && a.description == b.description
}

pub fn group_equals(a: &UserGroup, b: &UserGroup) -> bool {
    if a.created_ms != b.created_ms || a.name != b.name {
        return false;
    }
    match (&a.owner, &b.owner) {
        (None, None) => {}
        (Some(x), Some(y)) => {
            if !user_equals(x, y) {
                return false;
            }
        }
        _ => return false,
    }
    set_eq(
        a.members.as_ref(),
        b.members.as_ref(),
        |x, y| user_equals(x, y),
    ) && set_eq(a.roles.as_ref(), b.roles.as_ref(), |x, y| {
        role_equals(x, y)
    })
}

fn set_eq<T, F: Fn(&T, &T) -> bool>(a: Option<&Vec<T>>, b: Option<&Vec<T>>, eq: F) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => {
            x.len() == y.len() && x.iter().all(|xe| y.iter().any(|ye| eq(xe, ye)))
        }
        _ => false,
    }
}

// HashSet.add: keep first, skip if an equal element exists
pub fn set_add_user(v: &mut Vec<User>, u: User) {
    if !v.iter().any(|e| user_equals(e, &u)) {
        v.push(u);
    }
}
pub fn set_add_role(v: &mut Vec<Role>, r: Role) {
    if !v.iter().any(|e| role_equals(e, &r)) {
        v.push(r);
    }
}
pub fn set_add_group(v: &mut Vec<UserGroup>, g: UserGroup) {
    if !v.iter().any(|e| group_equals(e, &g)) {
        v.push(g);
    }
}

// ---------------------------------------------------------------------------
// Serialisation (Jackson bean serialisation shape)
// ---------------------------------------------------------------------------

fn opt_str(v: &Option<String>) -> JVal {
    match v {
        Some(s) => jstr(s),
        None => JVal::Null,
    }
}
fn opt_i32(v: &Option<i32>) -> JVal {
    match v {
        Some(i) => jint(*i as i64),
        None => JVal::Null,
    }
}
fn opt_bool(v: &Option<bool>) -> JVal {
    match v {
        Some(b) => jbool(*b),
        None => JVal::Null,
    }
}
fn opt_f64(v: &Option<f64>) -> JVal {
    match v {
        Some(f) => jdouble(*f),
        None => JVal::Null,
    }
}
fn opt_point(v: &Option<(f64, f64)>) -> JVal {
    match v {
        Some((x, y)) => jobj(vec![
            ("x".to_string(), jdouble(*x)),
            ("y".to_string(), jdouble(*y)),
        ]),
        None => JVal::Null,
    }
}

pub fn role_json(r: &Role) -> JVal {
    jobj(vec![
        ("id".into(), opt_i32(&r.id)),
        ("name".into(), opt_str(&r.name)),
        ("description".into(), opt_str(&r.description)),
    ])
}

pub fn user_json(u: &User) -> JVal {
    let roles = match &u.roles {
        Some(rs) => jarr(rs.iter().map(role_json).collect()),
        None => JVal::Null,
    };
    // @JsonIdentityReference(alwaysAsId=true) -> array of group ids
    let groups = match &u.user_groups {
        Some(gs) => jarr(gs.iter().map(|g| opt_i32(&g.id)).collect()),
        None => JVal::Null,
    };
    jobj(vec![
        ("id".into(), opt_i32(&u.id)),
        ("firstName".into(), opt_str(&u.first_name)),
        ("lastName".into(), opt_str(&u.last_name)),
        ("email".into(), opt_str(&u.email)),
        (
            "birthday".into(),
            match &u.birthday {
                Some(b) => jstr(b),
                None => JVal::Null,
            },
        ),
        ("language".into(), opt_str(&u.language)),
        ("accountName".into(), opt_str(&u.account_name)),
        ("active".into(), jbool(u.active)),
        ("roles".into(), roles),
        ("userGroups".into(), groups),
    ])
}

pub fn group_json(g: &UserGroup) -> JVal {
    let owner = match &g.owner {
        Some(o) => user_json(o),
        None => JVal::Null,
    };
    let members = match &g.members {
        Some(ms) => jarr(ms.iter().map(user_json).collect()),
        None => JVal::Null,
    };
    let roles = match &g.roles {
        Some(rs) => jarr(rs.iter().map(role_json).collect()),
        None => JVal::Null,
    };
    jobj(vec![
        ("id".into(), opt_i32(&g.id)),
        ("name".into(), opt_str(&g.name)),
        ("owner".into(), owner),
        ("members".into(), members),
        ("roles".into(), roles),
    ])
}

pub fn extent_json(e: &Extent) -> JVal {
    jobj(vec![
        ("id".into(), opt_i32(&e.id)),
        ("lowerLeft".into(), opt_point(&e.lower_left)),
        ("upperRight".into(), opt_point(&e.upper_right)),
    ])
}

pub fn tilegrid_json(t: &TileGrid) -> JVal {
    let mut entries = vec![
        ("id".into(), opt_i32(&t.id)),
        ("type".into(), opt_str(&t.type_)),
        ("tileGridOrigin".into(), opt_point(&t.origin)),
        (
            "tileGridExtent".into(),
            match &t.extent {
                Some(e) => extent_json(e),
                None => JVal::Null,
            },
        ),
        ("tileSize".into(), opt_i32(&t.tile_size)),
        (
            "tileGridResolutions".into(),
            match &t.resolutions {
                Some(rs) => jarr(rs.iter().map(|r| jdouble(*r)).collect()),
                None => JVal::Null,
            },
        ),
    ];
    if t.is_wmts {
        entries.push((
            "matrixIds".into(),
            match &t.matrix_ids {
                Some(ms) => jarr(ms.iter().map(|m| jstr(m)).collect()),
                None => JVal::Null,
            },
        ));
    }
    jobj(entries)
}

pub fn appearance_json(a: &LayerAppearance) -> JVal {
    let props = match &a.properties {
        Some(ps) => jobj(ps.iter().map(|(k, v)| (k.clone(), v.clone())).collect()),
        None => JVal::Null,
    };
    jobj(vec![
        ("id".into(), opt_i32(&a.id)),
        ("attribution".into(), opt_str(&a.attribution)),
        ("hoverable".into(), opt_bool(&a.hoverable)),
        ("clickable".into(), opt_bool(&a.clickable)),
        ("hoverTemplate".into(), opt_str(&a.hover_template)),
        ("properties".into(), props),
        ("name".into(), opt_str(&a.name)),
        ("maxResolution".into(), opt_f64(&a.max_resolution)),
        ("minResolution".into(), opt_f64(&a.min_resolution)),
        ("opacity".into(), opt_f64(&a.opacity)),
        ("visible".into(), opt_bool(&a.visible)),
    ])
}

pub fn datasource_json(d: &DataSource) -> JVal {
    let mut e: Vec<(String, JVal)> = vec![
        ("id".into(), opt_i32(&d.id)),
        ("name".into(), opt_str(&d.name)),
        ("type".into(), opt_str(&d.type_)),
        ("url".into(), opt_str(&d.url)),
        ("format".into(), opt_str(&d.format)),
    ];
    match d.kind {
        DsKind::ImageWms => {
            e.push(("width".into(), jint(d.width as i64)));
            e.push(("height".into(), jint(d.height as i64)));
            e.push(("version".into(), opt_str(&d.version)));
            e.push(("layerNames".into(), opt_str(&d.layer_names)));
            e.push(("layerStyles".into(), opt_str(&d.layer_styles)));
            e.push(("requestableByPath".into(), opt_bool(&d.requestable_by_path)));
            e.push(("customRequestPath".into(), opt_str(&d.custom_request_path)));
        }
        DsKind::TileWms => {
            e.push(("width".into(), jint(d.width as i64)));
            e.push(("height".into(), jint(d.height as i64)));
            e.push(("version".into(), opt_str(&d.version)));
            e.push(("layerNames".into(), opt_str(&d.layer_names)));
            e.push(("layerStyles".into(), opt_str(&d.layer_styles)));
            e.push(("requestableByPath".into(), opt_bool(&d.requestable_by_path)));
            e.push(("customRequestPath".into(), opt_str(&d.custom_request_path)));
            e.push((
                "tileGrid".into(),
                match &d.tile_grid {
                    Some(t) => tilegrid_json(t),
                    None => JVal::Null,
                },
            ));
            e.push(("requestWithTiled".into(), opt_bool(&d.request_with_tiled)));
        }
        DsKind::Wfs => {
            e.push(("version".into(), opt_str(&d.version)));
            e.push(("typeName".into(), opt_str(&d.type_name)));
            e.push(("typeNames".into(), opt_str(&d.type_names)));
        }
        DsKind::Wmts => {
            e.push((
                "tileGrid".into(),
                match &d.tile_grid {
                    Some(t) => tilegrid_json(t),
                    None => JVal::Null,
                },
            ));
            e.push((
                "urls".into(),
                match &d.urls {
                    Some(us) => jarr(us.iter().map(|u| jstr(u)).collect()),
                    None => JVal::Null,
                },
            ));
            e.push(("wmtsLayer".into(), opt_str(&d.wmts_layer)));
            e.push(("wmtsStyle".into(), opt_str(&d.wmts_style)));
            e.push(("projection".into(), opt_str(&d.projection)));
            e.push(("matrixSet".into(), opt_str(&d.matrix_set)));
            e.push(("requestEncoding".into(), opt_str(&d.request_encoding)));
            e.push(("capabilitiesUrl".into(), opt_str(&d.capabilities_url)));
        }
        DsKind::Xyz => {
            e.push(("center".into(), opt_point(&d.center)));
            e.push((
                "extent".into(),
                match &d.extent {
                    Some(x) => extent_json(x),
                    None => JVal::Null,
                },
            ));
            e.push((
                "resolutions".into(),
                match &d.resolutions {
                    Some(rs) => jarr(
                        rs.iter()
                            .map(|(x, y)| {
                                jobj(vec![
                                    ("x".into(), jdouble(*x)),
                                    ("y".into(), jdouble(*y)),
                                ])
                            })
                            .collect(),
                    ),
                    None => JVal::Null,
                },
            ));
            e.push(("tileSize".into(), opt_i32(&d.tile_size)));
        }
    }
    jobj(e)
}

pub fn layer_json(l: &Layer) -> JVal {
    jobj(vec![
        ("id".into(), opt_i32(&l.id)),
        ("name".into(), opt_str(&l.name)),
        ("description".into(), opt_str(&l.description)),
        (
            "source".into(),
            match &l.source {
                Some(s) => datasource_json(s),
                None => JVal::Null,
            },
        ),
        (
            "appearance".into(),
            match &l.appearance {
                Some(a) => appearance_json(a),
                None => JVal::Null,
            },
        ),
    ])
}

// ---------------------------------------------------------------------------
// restrictable/filterable fields per entity class (EntityUtil)
// ---------------------------------------------------------------------------

pub const USER_FIELDS: &[(&str, FieldType)] = &[
    ("accountName", FieldType::Str),
    ("password", FieldType::Str),
    ("active", FieldType::BoolPrim),
    ("firstName", FieldType::Str),
    ("lastName", FieldType::Str),
    ("email", FieldType::Str),
    ("id", FieldType::IntWrap),
];

pub const GROUP_FIELDS: &[(&str, FieldType)] =
    &[("name", FieldType::Str), ("id", FieldType::IntWrap)];

pub const ROLE_FIELDS: &[(&str, FieldType)] = &[
    ("name", FieldType::Str),
    ("description", FieldType::Str),
    ("id", FieldType::IntWrap),
];

pub const LAYER_FIELDS: &[(&str, FieldType)] = &[
    ("name", FieldType::Str),
    ("description", FieldType::Str),
    ("id", FieldType::IntWrap),
];

pub const DS_FIELDS: &[(&str, FieldType)] = &[
    ("name", FieldType::Str),
    ("type", FieldType::Str),
    ("url", FieldType::Str),
    ("format", FieldType::Str),
    ("id", FieldType::IntWrap),
];

pub const APPEARANCE_FIELDS: &[(&str, FieldType)] = &[
    ("attribution", FieldType::Str),
    ("hoverable", FieldType::BoolWrap),
    ("clickable", FieldType::BoolWrap),
    ("hoverTemplate", FieldType::Str),
    ("name", FieldType::Str),
    ("maxResolution", FieldType::DblWrap),
    ("minResolution", FieldType::DblWrap),
    ("opacity", FieldType::DblWrap),
    ("visible", FieldType::BoolWrap),
    ("id", FieldType::IntWrap),
];

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum FieldType {
    Str,
    BoolPrim,
    BoolWrap,
    IntWrap,
    DblWrap,
}

