use deadpool_postgres::{Manager, Pool, Runtime};
use tokio_postgres::{Client, NoTls, Row};

pub type DbPool = Pool;

pub fn create_pool(database_url: &str) -> Result<DbPool, String> {
    let cfg: tokio_postgres::Config = database_url
        .parse()
        .map_err(|e| format!("invalid DATABASE_URL: {}", e))?;
    let mgr = Manager::from(cfg, NoTls);
    Pool::builder(mgr)
        .max_size(16)
        .runtime(Runtime::Tokio1)
        .build()
        .map_err(|e| format!("pool error: {}", e))
}

pub async fn get_client(pool: &DbPool) -> Result<deadpool_postgres::Client, String> {
    pool.get().await.map_err(|e| format!("db pool: {}", e))
}

/// Allocate the next id exactly like Hibernate's table generator does here:
/// new id = next_val + 1, then next_val = new id. The statement runs on its
/// own connection (autocommit), so - like the original - the id is consumed
/// even if the surrounding transaction later fails.
pub async fn next_id(pool: &DbPool) -> Result<i32, String> {
    let c = get_client(pool).await?;
    let row = c
        .query_one(
            "UPDATE hibernate_sequences SET next_val = next_val + 1 \
             WHERE sequence_name = 'default' RETURNING next_val",
