// HTTP Basic authentication (ShogunCoreAuthenticationProvider) and the entity
// permission evaluators (de.terrestris.shoguncore.security.access).

use crate::db::DbPool;
use crate::model::*;
use base64::Engine;
use std::collections::HashMap;
use tokio_postgres::Client;

pub const SUPER_ADMIN_ROLE: &str = "ROLE_ADMIN";
pub const DEFAULT_USER_ROLE: &str = "ROLE_USER";

#[derive(Clone, Debug)]
pub struct AuthUser {
    pub id: i32,
    pub account_name: String,
    pub active: bool,
    pub role_names: Vec<String>,
    pub group_ids: Vec<i32>,
    pub is_admin: bool,
    pub url_ok: bool, // hasRole(ROLE_USER) incl. hierarchy ROLE_ADMIN > ROLE_USER
    // full row data for equals() comparisons
    pub created_ms: i64,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<String>,
    pub language: Option<String>,
    pub password: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum AuthError {
    Unauthorized, // 401
    Forbidden,    // 403
}

pub async fn authenticate(pool: &DbPool, header: Option<&str>) -> Result<AuthUser, AuthError> {
    let header = match header {
        Some(h) => h,
        None => return Err(AuthError::Unauthorized),
    };
    let rest = match header.split_once(' ') {
        Some((scheme, rest)) if scheme.eq_ignore_ascii_case("Basic") => rest.trim(),
        _ => return Err(AuthError::Unauthorized),
    };
    let decoded = base64::engine::general_purpose::STANDARD
        .decode(rest)
        .map_err(|_| AuthError::Unauthorized)?;
    let decoded = String::from_utf8(decoded).map_err(|_| AuthError::Unauthorized)?;
    let (account, password) = match decoded.split_once(':') {
        Some(p) => p,
        None => return Err(AuthError::Unauthorized),
    };

    let c = pool.get().await.map_err(|_| AuthError::Unauthorized)?;
    let row = c
        .query_opt(
            "SELECT u.id, u.accountname, u.active, u.password, p.created, p.firstname, p.lastname,
                    p.email, p.birthday, p.language
               FROM users u JOIN persons p ON p.id = u.id
              WHERE u.accountname = $1",
            &[&account],
        )
        .await
        .map_err(|_| AuthError::Unauthorized)?;
    let row = match row {
        Some(r) => r,
        None => return Err(AuthError::Unauthorized), // UsernameNotFoundException
    };
    let active: Option<bool> = row.get(2);
    if !active.unwrap_or(false) {
        return Err(AuthError::Unauthorized); // DisabledException
    }
    let hash: Option<String> = row.get(3);
    let hash = match hash {
        Some(h) => h,
        None => return Err(AuthError::Unauthorized),
    };
    let ok = bcrypt::verify(password, &hash).unwrap_or(false);
    if !ok {
        return Err(AuthError::Unauthorized); // BadCredentialsException
    }

    let id: i32 = row.get(0);
    // explicit user roles + roles of the groups the user is a member of
    let mut role_names: Vec<String> = Vec::new();
    let rs = c
        .query(
            "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1",
            &[&id],
        )
        .await
        .map_err(|_| AuthError::Unauthorized)?;
    for r in rs {
        let n: String = r.get(0);
        if !role_names.contains(&n) {
            role_names.push(n);
        }
    }
    let mut group_ids: Vec<i32> = Vec::new();
    let gs = c
        .query(
            "SELECT g.usergroup_id, r.name FROM user_usergroup g
               LEFT JOIN usergroups_roles gr ON gr.usergroup_id = g.usergroup_id
               LEFT JOIN roles r ON r.id = gr.role_id
              WHERE g.user_id = $1",
            &[&id],
        )
        .await
        .map_err(|_| AuthError::Unauthorized)?;
    for r in gs {
        let gid: i32 = r.get(0);
        if !group_ids.contains(&gid) {
            group_ids.push(gid);
        }
        let n: Option<String> = r.get(1);
        if let Some(n) = n {
            if !role_names.contains(&n) {
                role_names.push(n);
            }
        }
    }

    if role_names.is_empty() {
        // token without authorities -> isAuthenticated() == false -> 401
        return Err(AuthError::Unauthorized);
    }

    let is_admin = role_names.iter().any(|r| r == SUPER_ADMIN_ROLE);
    let url_ok = is_admin || role_names.iter().any(|r| r == DEFAULT_USER_ROLE);

    let created: Option<chrono::NaiveDateTime> = row.get(4);
    let birthday: Option<chrono::NaiveDate> = row.get(8);
    Ok(AuthUser {
        id,
        account_name: row.get::<_, Option<String>>(1).unwrap_or_default(),
        active: true,
        role_names,
        group_ids,
        is_admin,
        url_ok,
        created_ms: crate::db::ts_to_ms(created),
        first_name: row.get(5),
        last_name: row.get(6),
        email: row.get(7),
        birthday: birthday.map(|b| b.format("%Y-%m-%d").to_string()),
        language: row.get(9),
        password: row.get(3),
    })
}

// ---------------------------------------------------------------------------
// permission evaluators
// ---------------------------------------------------------------------------

fn default_has_perm(auth: &AuthUser, up: &PermMap, gp: &PermMap, p: Perm) -> bool {
    if auth.is_admin {
        return true;
    }
    if let Some((_, perms)) = up.iter().find(|(uid, _)| *uid == auth.id) {
        if perms.iter().any(|x| x == p.name() || x == "ADMIN") {
            return true;
        }
    }
    for (gid, perms) in gp.iter() {
        if auth.group_ids.contains(gid)
            && perms.iter().any(|x| x == p.name() || x == "ADMIN")
        {
            return true;
        }
    }
    false
}

fn user_matches_auth(auth: &AuthUser, u: &User) -> bool {
    // User.equals: class + created + person fields + accountName/password/active
    match u.id {
        Some(id) if id == auth.id => {}
        _ => return false,
    }
    u.created_ms == auth.created_ms
        && u.first_name == auth.first_name
        && u.last_name == auth.last_name
        && u.email == auth.email
        && u.birthday == auth.birthday
        && u.language == auth.language
        && u.account_name == Some(auth.account_name.clone())
        && u.password == auth.password
        && u.active == auth.active
}

/// UserPermissionEvaluator: READ on the own user object is always granted.
pub fn eval_user(auth: &AuthUser, u: &User, p: Perm) -> bool {
    if auth.is_admin {
        return true;
    }
    if p == Perm::Read && user_matches_auth(auth, u) {
        return true;
    }
    default_has_perm(auth, &u.user_perms, &u.group_perms, p)
}

/// UserGroupPermissionEvaluator: READ on groups the user is a member of.
pub fn eval_group(auth: &AuthUser, g: &UserGroup, p: Perm) -> bool {
    if auth.is_admin {
        return true;
    }
    if p == Perm::Read {
        if let Some(members) = &g.members {
            if members.iter().any(|m| m.id == Some(auth.id)) {
                return true;
            }
        }
    }
    default_has_perm(auth, &g.user_perms, &g.group_perms, p)
}

/// AlwaysAllowReadPermissionEvaluator: Role, LayerDataSource, LayerAppearance,
/// Extent, TileGrid (+WmtsTileGrid), PermissionCollection.
pub fn eval_always_read(auth: &AuthUser, up: &PermMap, gp: &PermMap, p: Perm) -> bool {
    if auth.is_admin {
        return true;
    }
    if p == Perm::Read {
        return true;
    }
    default_has_perm(auth, up, gp, p)
}

/// PersistentObjectPermissionEvaluator: Layer (and everything not listed).
pub fn eval_default(auth: &AuthUser, up: &PermMap, gp: &PermMap, p: Perm) -> bool {
    default_has_perm(auth, up, gp, p)
}

// ---------------------------------------------------------------------------
// permission collection loading
// ---------------------------------------------------------------------------

pub async fn load_perms(c: &Client, entity_id: i32) -> Result<(PermMap, PermMap), String> {
    let up = load_perm_map(
        c,
        "SELECT up.userpermissions_key, p.permissions FROM userpermissions up \
         JOIN permissioncollections_permissions p ON p.permissioncollections_id = up.userpermissions_id \
         WHERE up.entity_id = $1",
        entity_id,
    )
    .await?;
    let gp = load_perm_map(
        c,
        "SELECT gp.grouppermissions_key, p.permissions FROM grouppermissions gp \
         JOIN permissioncollections_permissions p ON p.permissioncollections_id = gp.grouppermissions_id \
         WHERE gp.entity_id = $1",
        entity_id,
    )
    .await?;
    Ok((up, gp))
}

async fn load_perm_map(c: &Client, sql: &str, entity_id: i32) -> Result<PermMap, String> {
    let rows = c.query(sql, &[&entity_id]).await.map_err(|e| e.to_string())?;
    let mut map: HashMap<i32, Vec<String>> = HashMap::new();
    for r in rows {
        let key: i32 = r.get(0);
        let perm: Option<String> = r.get(1);
        if let Some(perm) = perm {
            map.entry(key).or_default().push(perm);
        }
    }
    Ok(map.into_iter().collect())
}

pub async fn load_perms_batch(
    c: &Client,
    ids: &[i32],
) -> Result<(HashMap<i32, PermMap>, HashMap<i32, PermMap>), String> {
    let mut um = HashMap::new();
    let mut gm = HashMap::new();
    if ids.is_empty() {
        return Ok((um, gm));
    }
    let rows = c
        .query(
            "SELECT up.entity_id, up.userpermissions_key, p.permissions FROM userpermissions up \
             JOIN permissioncollections_permissions p ON p.permissioncollections_id = up.userpermissions_id \
             WHERE up.entity_id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let eid: i32 = r.get(0);
        let key: i32 = r.get(1);
        let perm: Option<String> = r.get(2);
        if let Some(perm) = perm {
            um.entry(eid).or_insert_with(Vec::new).entry_push(key, perm);
        }
    }
    let rows = c
        .query(
            "SELECT gp.entity_id, gp.grouppermissions_key, p.permissions FROM grouppermissions gp \
             JOIN permissioncollections_permissions p ON p.permissioncollections_id = gp.grouppermissions_id \
             WHERE gp.entity_id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let eid: i32 = r.get(0);
        let key: i32 = r.get(1);
        let perm: Option<String> = r.get(2);
        if let Some(perm) = perm {
            gm.entry(eid).or_insert_with(Vec::new).entry_push(key, perm);
        }
    }
    Ok((um, gm))
}

trait EntryPush {
    fn entry_push(&mut self, key: i32, perm: String);
}
impl EntryPush for Vec<(i32, Vec<String>)> {
    fn entry_push(&mut self, key: i32, perm: String) {
        if let Some((_, v)) = self.iter_mut().find(|(k, _)| *k == key) {
            v.push(perm);
        } else {
            self.push((key, vec![perm]));
        }
    }
}

