            map.entry(key).or_default().push(perm);
        }
    }
    Ok(map.into_iter().collect())
}

pub async fn load_perms_batch(
    c: &Client,
    ids: &[i32],
) -> Result<(HashMap<i32, PermMap>, HashMap<i32, PermMap>), String> {
    let mut um = HashMap::new();
    let mut gm = HashMap::new();
    if ids.is_empty() {
        return Ok((um, gm));
    }
    let rows = c
        .query(
            "SELECT up.entity_id, up.userpermissions_key, p.permissions FROM userpermissions up \
             JOIN permissioncollections_permissions p ON p.permissioncollections_id = up.userpermissions_id \
             WHERE up.entity_id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let eid: i32 = r.get(0);
        let key: i32 = r.get(1);
        let perm: Option<String> = r.get(2);
        if let Some(perm) = perm {
            um.entry(eid).or_insert_with(Vec::new).entry_push(key, perm);
        }
    }
    let rows = c
        .query(
            "SELECT gp.entity_id, gp.grouppermissions_key, p.permissions FROM grouppermissions gp \
             JOIN permissioncollections_permissions p ON p.permissioncollections_id = gp.grouppermissions_id \
             WHERE gp.entity_id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let eid: i32 = r.get(0);
        let key: i32 = r.get(1);
        let perm: Option<String> = r.get(2);
        if let Some(perm) = perm {
            gm.entry(eid).or_insert_with(Vec::new).entry_push(key, perm);
        }
    }
    Ok((um, gm))
}

trait EntryPush {
    fn entry_push(&mut self, key: i32, perm: String);
}
impl EntryPush for Vec<(i32, Vec<String>)> {
    fn entry_push(&mut self, key: i32, perm: String) {
        if let Some((_, v)) = self.iter_mut().find(|(k, _)| *k == key) {
            v.push(perm);
        } else {
            self.push((key, vec![perm]));
        }
    }
}
