// Loading entities from the database, mirroring Hibernate's eager fetch
// behaviour (FetchMode.JOIN etc.) and the aliasToBean-restricted projections.

use crate::db::*;
use crate::model::*;
use crate::perms::load_perms_batch;
use std::collections::{HashMap, HashSet};
use tokio_postgres::Client;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum SKind {
    User,
    UserGroup,
    Role,
    Layer,
    Appearance,
    Extent,
    TileGrid,
    WmtsTileGrid,
    DsImageWms,
    DsTileWms,
    DsWfs,
    DsWmts,
    DsXyz,
}

/// Mirrors the Hibernate session identity map: used to reproduce
/// NonUniqueObjectException ("A different object with the same identifier
/// value was already associated with the session").
#[derive(Default)]
pub struct Session {
    pub seen: HashSet<(SKind, i32)>,
}

impl Session {
    pub fn mark(&mut self, k: SKind, id: i32) {
        self.seen.insert((k, id));
    }
    pub fn contains(&self, k: SKind, id: i32) -> bool {
        self.seen.contains(&(k, id))
    }
}

pub fn ds_skind(kind: DsKind) -> SKind {
    match kind {
        DsKind::ImageWms => SKind::DsImageWms,
        DsKind::TileWms => SKind::DsTileWms,
        DsKind::Wfs => SKind::DsWfs,
        DsKind::Wmts => SKind::DsWmts,
        DsKind::Xyz => SKind::DsXyz,
    }
}

// ---------------------------------------------------------------------------
// single entity loaders (full graphs)
// ---------------------------------------------------------------------------

pub async fn load_user(c: &Client, id: i32, sess: &mut Session) -> Result<Option<User>, String> {
    let row = match c
        .query_opt(
            "SELECT u.id, p.firstname, p.lastname, p.email, p.birthday, p.language,
                    u.accountname, u.password, u.active, p.created, p.modified
               FROM users u JOIN persons p ON p.id = u.id WHERE u.id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::User, id);
    let mut u = user_from_row(&row);
    u.roles = Some(load_roles_of_users(c, &[id]).await?.remove(&id).unwrap_or_default());
    u.user_groups = Some(load_group_ids_of_users(c, &[id]).await?.remove(&id).unwrap_or_default());
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    u.user_perms = up.get(&id).cloned().unwrap_or_default();
    u.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(u))
}

fn user_from_row(row: &tokio_postgres::Row) -> User {
    let birthday: Option<chrono::NaiveDate> = row.get(4);
    User {
        id: Some(row.get(0)),
        first_name: row.get(1),
        last_name: row.get(2),
        email: row.get(3),
        birthday: birthday.map(|b| b.format("%Y-%m-%d").to_string()),
        language: row.get(5),
        account_name: row.get(6),
        password: row.get(7),
        active: row.get::<_, Option<bool>>(8).unwrap_or(false),
        roles: Some(vec![]),
        user_groups: Some(vec![]),
        created_ms: ts_to_ms(row.get(9)),
        modified_ms: ts_to_ms(row.get(10)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_role(c: &Client, id: i32, sess: &mut Session) -> Result<Option<Role>, String> {
    let row = match c
        .query_opt(
            "SELECT id, name, description, created, modified FROM roles WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::Role, id);
    Ok(Some(role_from_row(&row)))
}

fn role_from_row(row: &tokio_postgres::Row) -> Role {
    Role {
        id: Some(row.get(0)),
        name: row.get(1),
        description: row.get(2),
        created_ms: ts_to_ms(row.get(3)),
        modified_ms: ts_to_ms(row.get(4)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_roles_by_ids(c: &Client, ids: &[i32]) -> Result<HashMap<i32, Role>, String> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT id, name, description, created, modified FROM roles WHERE id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let role = role_from_row(&r);
        out.insert(role.id.unwrap(), role);
    }
    Ok(out)
}

pub async fn load_group(c: &Client, id: i32, sess: &mut Session) -> Result<Option<UserGroup>, String> {
    let row = match c
        .query_opt(
            "SELECT id, name, owner_id, created, modified FROM usergroups WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::UserGroup, id);
    let owner_id: Option<i32> = row.get(2);
    let mut g = UserGroup {
        id: Some(id),
        name: row.get(1),
        owner: None,
        members: Some(vec![]),
        roles: Some(vec![]),
        created_ms: ts_to_ms(row.get(3)),
        modified_ms: ts_to_ms(row.get(4)),
        user_perms: vec![],
        group_perms: vec![],
    };
    if let Some(oid) = owner_id {
        g.owner = load_user(c, oid, sess).await?.map(Box::new);
    }
    let member_rows = c
        .query(
            "SELECT user_id FROM user_usergroup WHERE usergroup_id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut members = Vec::new();
    for r in member_rows {
        let uid: i32 = r.get(0);
        if let Some(u) = load_user(c, uid, sess).await? {
            members.push(u);
        }
    }
    g.members = Some(members);
    let role_rows = c
        .query(
            "SELECT role_id FROM usergroups_roles WHERE usergroup_id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut roles = Vec::new();
    for r in role_rows {
        let rid: i32 = r.get(0);
        if let Some(role) = load_role(c, rid, sess).await? {
            roles.push(role);
        }
    }
    g.roles = Some(roles);
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    g.user_perms = up.get(&id).cloned().unwrap_or_default();
    g.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(g))
}

pub async fn load_appearance(
    c: &Client,
    id: i32,
    sess: &mut Session,
) -> Result<Option<LayerAppearance>, String> {
    let row = match c
        .query_opt(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution,
                    minresolution, name, opacity, visible, created, modified
               FROM layerappearances WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::Appearance, id);
    let mut a = appearance_from_row(&row);
    a.properties = Some(load_properties(c, &[id]).await?.remove(&id).unwrap_or_default());
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    a.user_perms = up.get(&id).cloned().unwrap_or_default();
    a.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(a))
}

fn appearance_from_row(row: &tokio_postgres::Row) -> LayerAppearance {
    LayerAppearance {
        id: Some(row.get(0)),
        attribution: row.get(1),
        clickable: row.get(2),
        hover_template: row.get(3),
        hoverable: row.get(4),
        max_resolution: row.get(5),
        min_resolution: row.get(6),
        name: row.get(7),
        opacity: row.get(8),
        visible: row.get(9),
        properties: Some(vec![]),
        created_ms: ts_to_ms(row.get(10)),
        modified_ms: ts_to_ms(row.get(11)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_properties(
    c: &Client,
    ids: &[i32],
) -> Result<HashMap<i32, Vec<(String, JVal)>>, String> {
    use crate::jval::JVal;
    let mut out: HashMap<i32, Vec<(String, JVal)>> = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT appearance_id, property, value FROM layerappearances_properties \
             WHERE appearance_id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let aid: i32 = r.get(0);
        let prop: String = r.get(1);
        let val: Option<String> = r.get(2);
        let jv = match val {
            None => JVal::Null,
            Some(s) => property_value_from_db(&s),
        };
        out.entry(aid).or_default().push((prop, jv));
    }
    Ok(out)
}

/// PropertyValueConverter.convertToEntityAttribute
pub fn property_value_from_db(s: &str) -> crate::jval::JVal {
    use crate::jval::JVal;
    if s.eq_ignore_ascii_case("true") {
        return JVal::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return JVal::Bool(false);
    }
    if is_parsable_number(s) {
        let body = s.strip_prefix('-').unwrap_or(s);
        if body.chars().all(|ch| ch.is_ascii_digit()) && !body.is_empty() {
            if let Ok(v) = s.parse::<i64>() {
                return JVal::Int(v, s.to_string());
            }
        }
        if let Ok(v) = s.parse::<f64>() {
            return JVal::Float(v, s.to_string());
        }
    }
    JVal::Str(s.to_string())
}

/// commons-lang3 NumberUtils.isParsable (approximation)
pub fn is_parsable_number(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let bytes = s.as_bytes();
    let mut i = 0;
    if bytes[0] == b'-' {
        i = 1;
    }
    if i >= bytes.len() {
        return false;
    }
    let mut digits = 0;
    let mut dots = 0;
    while i < bytes.len() && (bytes[i].is_ascii_digit() || bytes[i] == b'.') {
        if bytes[i] == b'.' {
            dots += 1;
        } else {
            digits += 1;
        }
        i += 1;
    }
    if digits == 0 || dots > 1 {
        return false;
    }
    if s.ends_with('.') {
        return false;
    }
    if i == bytes.len() {
        return true;
    }
    // exponent part
    if bytes[i] == b'e' || bytes[i] == b'E' {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        let start = i;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
        return i > start && i == bytes.len();
    }
    false
}

pub async fn load_extent(c: &Client, id: i32, sess: &mut Session) -> Result<Option<Extent>, String> {
    let row = match c
        .query_opt(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y, created, modified
               FROM extents WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::Extent, id);
    Ok(Some(extent_from_row(&row)))
}

fn extent_from_row(row: &tokio_postgres::Row) -> Extent {
    let lx: Option<f64> = row.get(1);
    let ly: Option<f64> = row.get(2);
    let ux: Option<f64> = row.get(3);
    let uy: Option<f64> = row.get(4);
    Extent {
        id: Some(row.get(0)),
        lower_left: match (lx, ly) {
            (None, None) => None,
            (x, y) => Some((x.unwrap_or(0.0), y.unwrap_or(0.0))),
        },
        upper_right: match (ux, uy) {
            (None, None) => None,
            (x, y) => Some((x.unwrap_or(0.0), y.unwrap_or(0.0))),
        },
        created_ms: ts_to_ms(row.get(5)),
        modified_ms: ts_to_ms(row.get(6)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_tilegrid(
    c: &Client,
    id: i32,
    sess: &mut Session,
) -> Result<Option<TileGrid>, String> {
    let row = match c
        .query_opt(
            "SELECT t.id, t.type, t.tilegridorigin_x, t.tilegridorigin_y, t.tilesize,
                    t.tilegridextent_id, t.created, t.modified,
                    (SELECT count(*) FROM wmtstilegrids w WHERE w.id = t.id) > 0 AS is_wmts
               FROM tilegrids t WHERE t.id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    let is_wmts: bool = row.get(8);
    sess.mark(if is_wmts { SKind::WmtsTileGrid } else { SKind::TileGrid }, id);
    let mut t = TileGrid {
        is_wmts,
        id: Some(id),
        type_: row.get(1),
        origin: match (row.get::<_, Option<f64>>(2), row.get::<_, Option<f64>>(3)) {
            (None, None) => None,
            (x, y) => Some((x.unwrap_or(0.0), y.unwrap_or(0.0))),
        },
        extent: None,
        tile_size: row.get(4),
        resolutions: None,
        matrix_ids: None,
        created_ms: ts_to_ms(row.get(6)),
        modified_ms: ts_to_ms(row.get(7)),
        user_perms: vec![],
        group_perms: vec![],
    };
    let ext_id: Option<i32> = row.get(5);
    if let Some(eid) = ext_id {
        t.extent = load_extent(c, eid, sess).await?.map(Box::new);
    }
    let rrows = c
        .query(
            "SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id = $1 ORDER BY idx",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    if !rrows.is_empty() {
        let mut v = Vec::new();
        for r in rrows {
            let d: Option<f64> = r.get(0);
            v.push(d.unwrap_or(0.0));
        }
        t.resolutions = Some(v);
    } else {
        // empty collection comes back as an initialized (but empty) list
        t.resolutions = Some(vec![]);
    }
    if is_wmts {
        let mrows = c
            .query(
                "SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1",
                &[&id],
            )
            .await
            .map_err(|e| e.to_string())?;
        let mut v = Vec::new();
        for r in mrows {
            let s: Option<String> = r.get(0);
            v.push(s.unwrap_or_default());
        }
        t.matrix_ids = Some(v);
    }
    Ok(Some(t))
}

pub async fn load_ds(c: &Client, id: i32, sess: &mut Session) -> Result<Option<DataSource>, String> {
    let row = match c
        .query_opt(&ds_select_sql("WHERE d.id = $1"), &[&id])
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    let mut d = ds_from_row(c, &row, sess).await?;
    let id = d.id.unwrap();
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    d.user_perms = up.get(&id).cloned().unwrap_or_default();
    d.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(d))
}

pub fn ds_select_sql(where_clause: &str) -> String {
    format!(
        "SELECT d.id, d.name, d.type, d.url, d.format, d.created, d.modified,
                iw.width, iw.height, iw.version, iw.layernames, iw.layerstyles,
                iw.requestablebypath, iw.customrequestpath, iw.id IS NOT NULL AS has_iw,
                tw.tilegrid_id AS tw_tilegrid, tw.request_with_tiled, tw.id IS NOT NULL AS has_tw,
                wf.version AS wf_version, wf.typename, wf.typenames, wf.id IS NOT NULL AS has_wf,
                wm.tilegrid_id AS wm_tilegrid, wm.wmtslayer, wm.wmtsstyle, wm.projection,
                wm.matrixset, wm.requestencoding, wm.capabilitiesurl, wm.id IS NOT NULL AS has_wm,
                xy.center_x, xy.center_y, xy.tilesize, xy.extent_id, xy.id IS NOT NULL AS has_xy
           FROM layerdatasources d
           LEFT JOIN imagewmslayerdatasources iw ON iw.id = d.id
           LEFT JOIN tilewmslayerdatasources tw ON tw.id = d.id
           LEFT JOIN wfslayerdatasources wf ON wf.id = d.id
           LEFT JOIN wmtslayerdatasources wm ON wm.id = d.id
           LEFT JOIN xyzlayerdatasources xy ON xy.id = d.id
           {}",
        where_clause
    )
}

async fn ds_from_row(
    c: &Client,
    row: &tokio_postgres::Row,
    sess: &mut Session,
) -> Result<DataSource, String> {
    let has_tw: bool = row.get(18);
    let has_iw: bool = row.get(14);
    let has_wf: bool = row.get(22);
    let has_wm: bool = row.get(30);
    let has_xy: bool = row.get(36);
    let kind = if has_tw {
        DsKind::TileWms
    } else if has_iw {
        DsKind::ImageWms
    } else if has_wf {
        DsKind::Wfs
    } else if has_wm {
        DsKind::Wmts
    } else if has_xy {
        DsKind::Xyz
    } else {
        // a base row without any subtype row cannot be instantiated
        return Err(format!("no subtype for datasource {}", row.get::<_, i32>(0)));
    };
    let id: i32 = row.get(0);
    sess.mark(ds_skind(kind), id);
    let mut d = DataSource {
        kind,
        id: Some(id),
        name: row.get(1),
        type_: row.get(2),
        url: row.get(3),
        format: row.get(4),
        width: 0,
        height: 0,
        version: None,
        layer_names: None,
        layer_styles: None,
        requestable_by_path: None,
        custom_request_path: None,
        tile_grid: None,
        request_with_tiled: Some(true),
        type_name: None,
        type_names: None,
        urls: None,
        wmts_layer: None,
        wmts_style: None,
        projection: None,
        matrix_set: None,
        request_encoding: None,
        capabilities_url: None,
        center: None,
        extent: None,
        resolutions: Some(vec![]),
        tile_size: None,
        created_ms: ts_to_ms(row.get(5)),
        modified_ms: ts_to_ms(row.get(6)),
        user_perms: vec![],
        group_perms: vec![],
    };
    match kind {
        DsKind::ImageWms | DsKind::TileWms => {
            d.width = row.get::<_, Option<i32>>(7).unwrap_or(0);
            d.height = row.get::<_, Option<i32>>(8).unwrap_or(0);
            d.version = row.get(9);
            d.layer_names = row.get(10);
            d.layer_styles = row.get(11);
            d.requestable_by_path = row.get(12);
            d.custom_request_path = row.get(13);
            if kind == DsKind::TileWms {
                d.request_with_tiled = row.get(17);
                let tg: Option<i32> = row.get(15);
                if let Some(tgid) = tg {
                    d.tile_grid = load_tilegrid(c, tgid, sess).await?.map(Box::new);
                }
            }
        }
        DsKind::Wfs => {
            d.version = row.get(19);
            d.type_name = row.get(20);
            d.type_names = row.get(21);
        }
        DsKind::Wmts => {
            let tg: Option<i32> = row.get(23);
            if let Some(tgid) = tg {
                d.tile_grid = load_tilegrid(c, tgid, sess).await?.map(Box::new);
            }
            d.wmts_layer = row.get(24);
            d.wmts_style = row.get(25);
            d.projection = row.get(26);
            d.matrix_set = row.get(27);
            d.request_encoding = row.get(28);
            d.capabilities_url = row.get(29);
            let urows = c
                .query(
                    "SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
                    &[&id],
                )
                .await
                .map_err(|e| e.to_string())?;
            let mut urls = Vec::new();
            for r in urows {
                let s: Option<String> = r.get(0);
                urls.push(s.unwrap_or_default());
            }
            d.urls = Some(urls);
        }
        DsKind::Xyz => {
            d.center = match (row.get::<_, Option<f64>>(31), row.get::<_, Option<f64>>(32)) {
                (None, None) => None,
                (x, y) => Some((x.unwrap_or(0.0), y.unwrap_or(0.0))),
            };
            d.tile_size = row.get(33);
            let ext: Option<i32> = row.get(34);
            if let Some(eid) = ext {
                d.extent = load_extent(c, eid, sess).await?.map(Box::new);
            }
            let rrows = c
                .query(
                    "SELECT resolution FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
                    &[&id],
                )
                .await
                .map_err(|e| e.to_string())?;
            let mut v = Vec::new();
            for r in rrows {
                let b: Option<Vec<u8>> = r.get(0);
                if let Some(bytes) = b {
                    if let Some(pt) = parse_serialized_point(&bytes) {
                        v.push(pt);
                    }
                }
            }
            d.resolutions = Some(v);
        }
    }
    Ok(d)
}

/// Best-effort deserialization of the Java-serialized java.awt.geom.Point2D$Double
/// elements stored in xyzlayerdatasrc_resolution (not part of the checked contract).
pub fn parse_serialized_point(bytes: &[u8]) -> Option<(f64, f64)> {
    if bytes.len() < 20 || bytes[0] != 0xAC || bytes[1] != 0xED {
        return None;
    }
    let marker = b"java.awt.geom.Point2D$Double";
    let found = bytes
        .windows(marker.len())
        .any(|w| w == marker);
    if !found {
        return None;
    }
    let n = bytes.len();
    let x = f64::from_bits(u64::from_be_bytes(bytes[n - 16..n - 8].try_into().ok()?));
    let y = f64::from_bits(u64::from_be_bytes(bytes[n - 8..].try_into().ok()?));
    Some((x, y))
}

pub async fn load_layer(c: &Client, id: i32, sess: &mut Session) -> Result<Option<Layer>, String> {
    let row = match c
        .query_opt(
            "SELECT id, name, description, source_id, appearance_id, created, modified
               FROM layers WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::Layer, id);
    let source_id: Option<i32> = row.get(3);
    let appearance_id: Option<i32> = row.get(4);
    let mut l = Layer {
        id: Some(id),
        name: row.get(1),
        description: row.get(2),
        source: None,
        appearance: None,
        created_ms: ts_to_ms(row.get(5)),
        modified_ms: ts_to_ms(row.get(6)),
        user_perms: vec![],
        group_perms: vec![],
    };
    if let Some(sid) = source_id {
        l.source = load_ds(c, sid, sess).await?.map(Box::new);
    }
    if let Some(aid) = appearance_id {
        l.appearance = load_appearance(c, aid, sess).await?.map(Box::new);
    }
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    l.user_perms = up.get(&id).cloned().unwrap_or_default();
    l.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(l))
}

// ---------------------------------------------------------------------------
// batch helpers for lists
// ---------------------------------------------------------------------------

pub async fn load_roles_of_users(
    c: &Client,
    user_ids: &[i32],
) -> Result<HashMap<i32, Vec<Role>>, String> {
    let mut out: HashMap<i32, Vec<Role>> = HashMap::new();
    if user_ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT ur.user_id, r.id, r.name, r.description, r.created, r.modified
               FROM users_roles ur JOIN roles r ON r.id = ur.role_id
              WHERE ur.user_id = ANY($1)",
            &[&user_ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let uid: i32 = r.get(0);
        out.entry(uid).or_default().push(role_from_row_shifted(&r, 1));
    }
    Ok(out)
}

fn role_from_row_shifted(row: &tokio_postgres::Row, off: usize) -> Role {
    Role {
        id: Some(row.get(off)),
        name: row.get(off + 1),
        description: row.get(off + 2),
        created_ms: ts_to_ms(row.get(off + 3)),
        modified_ms: ts_to_ms(row.get(off + 4)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_group_ids_of_users(
    c: &Client,
    user_ids: &[i32],
) -> Result<HashMap<i32, Vec<UserGroup>>, String> {
    let mut out: HashMap<i32, Vec<UserGroup>> = HashMap::new();
    if user_ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1)",
            &[&user_ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let uid: i32 = r.get(0);
        let gid: i32 = r.get(1);
        out.entry(uid).or_default().push(UserGroup::new_stub(gid));
    }
    Ok(out)
}

pub async fn load_users_by_ids(c: &Client, ids: &[i32]) -> Result<HashMap<i32, User>, String> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT u.id, p.firstname, p.lastname, p.email, p.birthday, p.language,
                    u.accountname, u.password, u.active, p.created, p.modified
               FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut users: Vec<User> = rows.iter().map(user_from_row).collect();
    let roles = load_roles_of_users(c, ids).await?;
    let groups = load_group_ids_of_users(c, ids).await?;
    let (up, gp) = load_perms_batch(c, ids).await?;
    for u in users.iter_mut() {
        let id = u.id.unwrap();
        u.roles = Some(roles.get(&id).cloned().unwrap_or_default());
        u.user_groups = Some(groups.get(&id).cloned().unwrap_or_default());
        u.user_perms = up.get(&id).cloned().unwrap_or_default();
        u.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    for u in users.drain(..) {
        out.insert(u.id.unwrap(), u);
    }
    Ok(out)
}

