pub async fn load_group(c: &Client, id: i32, sess: &mut Session) -> Result<Option<UserGroup>, String> {
    let row = match c
        .query_opt(
            "SELECT id, name, owner_id, created, modified FROM usergroups WHERE id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?
    {
        Some(r) => r,
        None => return Ok(None),
    };
    sess.mark(SKind::UserGroup, id);
    let owner_id: Option<i32> = row.get(2);
    let mut g = UserGroup {
        id: Some(id),
        name: row.get(1),
        owner: None,
        members: Some(vec![]),
        roles: Some(vec![]),
        created_ms: ts_to_ms(row.get(3)),
        modified_ms: ts_to_ms(row.get(4)),
        user_perms: vec![],
        group_perms: vec![],
    };
    if let Some(oid) = owner_id {
        g.owner = load_user(c, oid, sess).await?.map(Box::new);
    }
    let member_rows = c
        .query(
            "SELECT user_id FROM user_usergroup WHERE usergroup_id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut members = Vec::new();
    for r in member_rows {
        let uid: i32 = r.get(0);
        if let Some(u) = load_user(c, uid, sess).await? {
            members.push(u);
        }
    }
    g.members = Some(members);
    let role_rows = c
        .query(
            "SELECT role_id FROM usergroups_roles WHERE usergroup_id = $1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut roles = Vec::new();
    for r in role_rows {
        let rid: i32 = r.get(0);
        if let Some(role) = load_role(c, rid, sess).await? {
            roles.push(role);
        }
    }
    g.roles = Some(roles);
    let (up, gp) = load_perms_batch(c, &[id]).await?;
    g.user_perms = up.get(&id).cloned().unwrap_or_default();
    g.group_perms = gp.get(&id).cloned().unwrap_or_default();
    Ok(Some(g))
}

pub async fn load_appearance(
    c: &Client,
    id: i32,
    sess: &mut Session,
) -> Result<Option<LayerAppearance>, String> {
    let row = match c
        .query_opt(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution,
                    minresolution, name, opacity, visible, created, modified
               FROM layerappearances WHERE id = $1",
