// batch helpers for lists
// ---------------------------------------------------------------------------

pub async fn load_roles_of_users(
    c: &Client,
    user_ids: &[i32],
) -> Result<HashMap<i32, Vec<Role>>, String> {
    let mut out: HashMap<i32, Vec<Role>> = HashMap::new();
    if user_ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT ur.user_id, r.id, r.name, r.description, r.created, r.modified
               FROM users_roles ur JOIN roles r ON r.id = ur.role_id
              WHERE ur.user_id = ANY($1)",
            &[&user_ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let uid: i32 = r.get(0);
        out.entry(uid).or_default().push(role_from_row_shifted(&r, 1));
    }
    Ok(out)
}

fn role_from_row_shifted(row: &tokio_postgres::Row, off: usize) -> Role {
    Role {
        id: Some(row.get(off)),
        name: row.get(off + 1),
        description: row.get(off + 2),
        created_ms: ts_to_ms(row.get(off + 3)),
        modified_ms: ts_to_ms(row.get(off + 4)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub async fn load_group_ids_of_users(
    c: &Client,
    user_ids: &[i32],
) -> Result<HashMap<i32, Vec<UserGroup>>, String> {
    let mut out: HashMap<i32, Vec<UserGroup>> = HashMap::new();
    if user_ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1)",
            &[&user_ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    for r in rows {
        let uid: i32 = r.get(0);
        let gid: i32 = r.get(1);
        out.entry(uid).or_default().push(UserGroup::new_stub(gid));
    }
    Ok(out)
}

pub async fn load_users_by_ids(c: &Client, ids: &[i32]) -> Result<HashMap<i32, User>, String> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT u.id, p.firstname, p.lastname, p.email, p.birthday, p.language,
                    u.accountname, u.password, u.active, p.created, p.modified
               FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut users: Vec<User> = rows.iter().map(user_from_row).collect();
    let roles = load_roles_of_users(c, ids).await?;
    let groups = load_group_ids_of_users(c, ids).await?;
    let (up, gp) = load_perms_batch(c, ids).await?;
    for u in users.iter_mut() {
        let id = u.id.unwrap();
        u.roles = Some(roles.get(&id).cloned().unwrap_or_default());
        u.user_groups = Some(groups.get(&id).cloned().unwrap_or_default());
        u.user_perms = up.get(&id).cloned().unwrap_or_default();
        u.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    for u in users.drain(..) {
        out.insert(u.id.unwrap(), u);
    }
    Ok(out)
}
