pub async fn list_users(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<User>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        // projection query (aliasToBean semantics)
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = user_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY u.id",
            sel.join(", "),
            where_sql
        );
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut u = User::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => u.id = r.get::<_, Option<i32>>(i),
                    "firstName" => u.first_name = r.get(i),
                    "lastName" => u.last_name = r.get(i),
                    "email" => u.email = r.get(i),
                    "accountName" => u.account_name = r.get(i),
                    "password" => u.password = r.get(i),
                    "active" => u.active = r.get::<_, Option<bool>>(i).unwrap_or(false),
                    _ => {}
                }
            }
            out.push(u);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT u.id, p.firstname, p.lastname, p.email, p.birthday, p.language,
                u.accountname, u.password, u.active, p.created, p.modified
           FROM users u JOIN persons p ON p.id = u.id {} ORDER BY u.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut users: Vec<User> = Vec::new();
    for r in &rows {
        users.push(user_from_row_pub(r));
    }
    finish_users(c, &mut users).await?;
    Ok(users)
}

fn user_from_row_pub(row: &tokio_postgres::Row) -> User {
    let birthday: Option<chrono::NaiveDate> = row.get(4);
    User {
        id: Some(row.get(0)),
        first_name: row.get(1),
        last_name: row.get(2),
        email: row.get(3),
        birthday: birthday.map(|b| b.format("%Y-%m-%d").to_string()),
        language: row.get(5),
        account_name: row.get(6),
        password: row.get(7),
        active: row.get::<_, Option<bool>>(8).unwrap_or(false),
        roles: Some(vec![]),
        user_groups: Some(vec![]),
        created_ms: ts_to_ms(row.get(9)),
        modified_ms: ts_to_ms(row.get(10)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

async fn finish_users(c: &Client, users: &mut [User]) -> Result<(), String> {
    let ids: Vec<i32> = users.iter().filter_map(|u| u.id).collect();
    let roles = load_roles_of_users(c, &ids).await?;
    let groups = load_group_ids_of_users(c, &ids).await?;
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for u in users.iter_mut() {
        let id = u.id.unwrap();
        u.roles = Some(roles.get(&id).cloned().unwrap_or_default());
        u.user_groups = Some(groups.get(&id).cloned().unwrap_or_default());
        u.user_perms = up.get(&id).cloned().unwrap_or_default();
        u.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(())
}

pub fn user_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("u.id"),
        "firstName" => Some("p.firstname"),
        "lastName" => Some("p.lastname"),
        "email" => Some("p.email"),
        "accountName" => Some("u.accountname"),
        "password" => Some("u.password"),
        "active" => Some("u.active"),
        _ => None,
    }
}

