pub async fn list_layers(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<Layer>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = layer_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!("SELECT {} FROM layers l {} ORDER BY l.id", sel.join(", "), where_sql);
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut l = Layer::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => l.id = r.get::<_, Option<i32>>(i),
                    "name" => l.name = r.get(i),
                    "description" => l.description = r.get(i),
                    _ => {}
                }
            }
            out.push(l);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT l.id, l.name, l.description, l.source_id, l.appearance_id, l.created, l.modified
           FROM layers l {} ORDER BY l.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut layers: Vec<Layer> = Vec::new();
    let mut src_ids: Vec<i32> = Vec::new();
    let mut app_ids: Vec<i32> = Vec::new();
    for r in &rows {
        let sid: Option<i32> = r.get(3);
        let aid: Option<i32> = r.get(4);
        if let Some(s) = sid {
            src_ids.push(s);
        }
        if let Some(a) = aid {
            app_ids.push(a);
        }
        layers.push(Layer {
            id: Some(r.get(0)),
            name: r.get(1),
            description: r.get(2),
            source: None,
            appearance: None,
            created_ms: ts_to_ms(r.get(5)),
            modified_ms: ts_to_ms(r.get(6)),
            user_perms: vec![],
            group_perms: vec![],
        });
    }
    src_ids.sort();
    src_ids.dedup();
    app_ids.sort();
    app_ids.dedup();
    let sources = list_ds_by_ids(c, &src_ids).await?;
    let appearances = list_appearances_by_ids(c, &app_ids).await?;
    let ids: Vec<i32> = layers.iter().filter_map(|l| l.id).collect();
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for l in layers.iter_mut() {
        let id = l.id.unwrap();
        l.source = rows
            .iter()
            .find(|r| r.get::<_, i32>(0) == id)
            .and_then(|r| r.get::<_, Option<i32>>(3))
            .and_then(|sid| sources.get(&sid).cloned())
            .map(Box::new);
        l.appearance = rows
            .iter()
            .find(|r| r.get::<_, i32>(0) == id)
            .and_then(|r| r.get::<_, Option<i32>>(4))
            .and_then(|aid| appearances.get(&aid).cloned())
            .map(Box::new);
        l.user_perms = up.get(&id).cloned().unwrap_or_default();
        l.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(layers)
}

pub fn layer_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("l.id"),
        "name" => Some("l.name"),
        "description" => Some("l.description"),
        _ => None,
    }
}

