{"content": "// List queries: full entity loading, equality filters (findBySimpleFilter)
// and restricted projections (output:only / findByCriteriaRestricted).

use crate::db::*;
use crate::jval::JVal;
use crate::load::*;
use crate::model::*;
use crate::perms::load_perms_batch;
use std::collections::HashMap;
use tokio_postgres::types::ToSql;
use tokio_postgres::Client;

#[derive(Clone, Debug)]
pub enum FVal {
    Str(String),
    Bool(bool),
    Int(i32),
    Dbl(f64),
}

impl FVal {
    pub fn as_sql(&self) -> &(dyn ToSql + Sync) {
        match self {
            FVal::Str(v) => v,
            FVal::Bool(v) => v,
            FVal::Int(v) => v,
            FVal::Dbl(v) => v,
        }
    }
}

/// A filter on one field: OR over its values.
pub struct FieldFilter {
    pub column: &'static str,
    pub values: Vec<FVal>,
}

pub fn build_where(filters: &[FieldFilter]) -> (String, Vec<FVal>) {
    if filters.is_empty() {
        return (String::new(), vec![]);
    }
    let mut clauses = Vec::new();
    let mut params: Vec<FVal> = Vec::new();
    for f in filters {
        let mut ors = Vec::new();
        for v in &f.values {
            params.push(v.clone());
            ors.push(format!("{} = ${}", f.column, params.len()));
        }
        clauses.push(format!("({})", ors.join(" OR ")));
    }
    (format!("WHERE {}", clauses.join(" AND ")), params)
}

fn bind(params: &[FVal]) -> Vec<&(dyn ToSql + Sync)> {
    params.iter().map(|p| p.as_sql()).collect()
}

// ---------------------------------------------------------------------------
// users
// ---------------------------------------------------------------------------

pub async fn list_users(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<User>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        // projection query (aliasToBean semantics)
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = user_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY u.id",
            sel.join(", "),
            where_sql
        );
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut u = User::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => u.id = r.get::<_, Option<i32>>(i),
                    "firstName" => u.first_name = r.get(i),
                    "lastName" => u.last_name = r.get(i),
                    "email" => u.email = r.get(i),
                    "accountName" => u.account_name = r.get(i),
                    "password" => u.password = r.get(i),
                    "active" => u.active = r.get::<_, Option<bool>>(i).unwrap_or(false),
                    _ => {}
                }
            }
            out.push(u);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT u.id, p.firstname, p.lastname, p.email, p.birthday, p.language,
                u.accountname, u.password, u.active, p.created, p.modified
           FROM users u JOIN persons p ON p.id = u.id {} ORDER BY u.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut users: Vec<User> = Vec::new();
    for r in &rows {
        users.push(user_from_row_pub(r));
    }
    finish_users(c, &mut users).await?;
    Ok(users)
}

fn user_from_row_pub(row: &tokio_postgres::Row) -> User {
    let birthday: Option<chrono::NaiveDate> = row.get(4);
    User {
        id: Some(row.get(0)),
        first_name: row.get(1),
        last_name: row.get(2),
        email: row.get(3),
        birthday: birthday.map(|b| b.format("%Y-%m-%d").to_string()),
        language: row.get(5),
        account_name: row.get(6),
        password: row.get(7),
        active: row.get::<_, Option<bool>>(8).unwrap_or(false),
        roles: Some(vec![]),
        user_groups: Some(vec![]),
        created_ms: ts_to_ms(row.get(9)),
        modified_ms: ts_to_ms(row.get(10)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

async fn finish_users(c: &Client, users: &mut [User]) -> Result<(), String> {
    let ids: Vec<i32> = users.iter().filter_map(|u| u.id).collect();
    let roles = load_roles_of_users(c, &ids).await?;
    let groups = load_group_ids_of_users(c, &ids).await?;
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for u in users.iter_mut() {
        let id = u.id.unwrap();
        u.roles = Some(roles.get(&id).cloned().unwrap_or_default());
        u.user_groups = Some(groups.get(&id).cloned().unwrap_or_default());
        u.user_perms = up.get(&id).cloned().unwrap_or_default();
        u.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(())
}

pub fn user_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("u.id"),
        "firstName" => Some("p.firstname"),
        "lastName" => Some("p.lastname"),
        "email" => Some("p.email"),
        "accountName" => Some("u.accountname"),
        "password" => Some("u.password"),
        "active" => Some("u.active"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// groups
// ---------------------------------------------------------------------------

pub async fn list_groups(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<UserGroup>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = group_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!("SELECT {} FROM usergroups g {} ORDER BY g.id", sel.join(", "), where_sql);
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut g = UserGroup::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => g.id = r.get::<_, Option<i32>>(i),
                    "name" => g.name = r.get(i),
                    _ => {}
                }
            }
            out.push(g);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT g.id, g.name, g.owner_id, g.created, g.modified FROM usergroups g {} ORDER BY g.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut groups: Vec<UserGroup> = Vec::new();
    let mut owner_ids: Vec<i32> = Vec::new();
    for r in &rows {
        let owner_id: Option<i32> = r.get(2);
        groups.push(UserGroup {
            id: Some(r.get(0)),
            name: r.get(1),
            owner: None,
            members: Some(vec![]),
            roles: Some(vec![]),
            created_ms: ts_to_ms(r.get(3)),
            modified_ms: ts_to_ms(r.get(4)),
            user_perms: vec![],
            group_perms: vec![],
        });
        if let Some(oid) = owner_id {
            owner_ids.push(oid);
        }
    }
    let gids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    // members
    let mrows = c
        .query(
            "SELECT usergroup_id, user_id FROM user_usergroup WHERE usergroup_id = ANY($1)",
            &[&gids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut member_ids: HashMap<i32, Vec<i32>> = HashMap::new();
    let mut all_user_ids = owner_ids.clone();
    for r in mrows {
        let gid: i32 = r.get(0);
        let uid: i32 = r.get(1);
        member_ids.entry(gid).or_default().push(uid);
        all_user_ids.push(uid);
    }
    // roles
    let rrows = c
        .query(
            "SELECT usergroup_id, role_id FROM usergroups_roles WHERE usergroup_id = ANY($1)",
            &[&gids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut role_ids: HashMap<i32, Vec<i32>> = HashMap::new();
    let mut all_role_ids: Vec<i32> = Vec::new();
    for r in rrows {
        let gid: i32 = r.get(0);
        let rid: i32 = r.get(1);
        role_ids.entry(gid).or_default().push(rid);
        all_role_ids.push(rid);
    }
    all_user_ids.sort();
    all_user_ids.dedup();
    all_role_ids.sort();
    all_role_ids.dedup();
    let users = load_users_by_ids(c, &all_user_ids).await?;
    let roles = load_roles_by_ids(c, &all_role_ids).await?;
    let (up, gp) = load_perms_batch(c, &gids).await?;
    for g in groups.iter_mut() {
        let id = g.id.unwrap();
        if let Some(oid) = owner_ids_of(&rows, id) {
            g.owner = users.get(&oid).cloned().map(Box::new);
        }
        g.members = Some(
            member_ids
                .get(&id)
                .map(|v| v.iter().filter_map(|uid| users.get(uid).cloned()).collect())
                .unwrap_or_default(),
        );
        g.roles = Some(
            role_ids
                .get(&id)
                .map(|v| v.iter().filter_map(|rid| roles.get(rid).cloned()).collect())
                .unwrap_or_default(),
        );
        g.user_perms = up.get(&id).cloned().unwrap_or_default();
        g.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(groups)
}

fn owner_ids_of(rows: &[tokio_postgres::Row], gid: i32) -> Option<i32> {
    for r in rows {
        if r.get::<_, i32>(0) == gid {
            return r.get::<_, Option<i32>>(2);
        }
    }
    None
}

pub fn group_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("g.id"),
        "name" => Some("g.name"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// roles
// ---------------------------------------------------------------------------

pub async fn list_roles(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<Role>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = role_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!("SELECT {} FROM roles r {} ORDER BY r.id", sel.join(", "), where_sql);
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut e = Role::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => e.id = r.get::<_, Option<i32>>(i),
                    "name" => e.name = r.get(i),
                    "description" => e.description = r.get(i),
                    _ => {}
                }
            }
            out.push(e);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT r.id, r.name, r.description, r.created, r.modified FROM roles r {} ORDER BY r.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut out: Vec<Role> = Vec::new();
    let mut ids = Vec::new();
    for r in &rows {
        let mut role = role_from_row_pub(r);
        ids.push(role.id.unwrap());
        out.push(role);
    }
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for role in out.iter_mut() {
        let id = role.id.unwrap();
        role.user_perms = up.get(&id).cloned().unwrap_or_default();
        role.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(out)
}

fn role_from_row_pub(row: &tokio_postgres::Row) -> Role {
    Role {
        id: Some(row.get(0)),
        name: row.get(1),
        description: row.get(2),
        created_ms: ts_to_ms(row.get(3)),
        modified_ms: ts_to_ms(row.get(4)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub fn role_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("r.id"),
        "name" => Some("r.name"),
        "description" => Some("r.description"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// layers
// ---------------------------------------------------------------------------

pub async fn list_layers(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<Layer>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = layer_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!("SELECT {} FROM layers l {} ORDER BY l.id", sel.join(", "), where_sql);
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut l = Layer::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => l.id = r.get::<_, Option<i32>>(i),
                    "name" => l.name = r.get(i),
                    "description" => l.description = r.get(i),
                    _ => {}
                }
            }
            out.push(l);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT l.id, l.name, l.description, l.source_id, l.appearance_id, l.created, l.modified
           FROM layers l {} ORDER BY l.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut layers: Vec<Layer> = Vec::new();
    let mut src_ids: Vec<i32> = Vec::new();
    let mut app_ids: Vec<i32> = Vec::new();
    for r in &rows {
        let sid: Option<i32> = r.get(3);
        let aid: Option<i32> = r.get(4);
        if let Some(s) = sid {
            src_ids.push(s);
        }
        if let Some(a) = aid {
            app_ids.push(a);
        }
        layers.push(Layer {
            id: Some(r.get(0)),
            name: r.get(1),
            description: r.get(2),
            source: None,
            appearance: None,
            created_ms: ts_to_ms(r.get(5)),
            modified_ms: ts_to_ms(r.get(6)),
            user_perms: vec![],
            group_perms: vec![],
        });
    }
    src_ids.sort();
    src_ids.dedup();
    app_ids.sort();
    app_ids.dedup();
    let sources = list_ds_by_ids(c, &src_ids).await?;
    let appearances = list_appearances_by_ids(c, &app_ids).await?;
    let ids: Vec<i32> = layers.iter().filter_map(|l| l.id).collect();
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for l in layers.iter_mut() {
        let id = l.id.unwrap();
        l.source = rows
            .iter()
            .find(|r| r.get::<_, i32>(0) == id)
            .and_then(|r| r.get::<_, Option<i32>>(3))
            .and_then(|sid| sources.get(&sid).cloned())
            .map(Box::new);
        l.appearance = rows
            .iter()
            .find(|r| r.get::<_, i32>(0) == id)
            .and_then(|r| r.get::<_, Option<i32>>(4))
            .and_then(|aid| appearances.get(&aid).cloned())
            .map(Box::new);
        l.user_perms = up.get(&id).cloned().unwrap_or_default();
        l.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(layers)
}

pub fn layer_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("l.id"),
        "name" => Some("l.name"),
        "description" => Some("l.description"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// layer datasources
// ---------------------------------------------------------------------------

pub async fn list_ds(
    c: &Client,
    filters: &[FieldFilter],
) -> Result<Vec<DataSource>, String> {
    let (where_sql, params) = build_where(filters);
    let sql = ds_select_sql(&format!("{} ORDER BY d.id", where_sql));
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut sess = Session::default();
    let mut out = Vec::new();
    let mut ids = Vec::new();
    for r in &rows {
        let mut d = ds_from_row_pub(c, r, &mut sess).await?;
        ids.push(d.id.unwrap());
        out.push(d);
    }
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for d in out.iter_mut() {
        let id = d.id.unwrap();
        d.user_perms = up.get(&id).cloned().unwrap_or_default();
        d.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(out)
}

pub async fn list_ds_by_ids(c: &Client, ids: &[i32]) -> Result<HashMap<i32, DataSource>, String> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let sql = ds_select_sql("WHERE d.id = ANY($1) ORDER BY d.id");
    let rows = c.query(&sql, &[&ids]).await.map_err(|e| e.to_string())?;
    let mut sess = Session::default();
    for r in &rows {
        let d = ds_from_row_pub(c, r, &mut sess).await?;
        out.insert(d.id.unwrap(), d);
    }
    Ok(out)
}

async fn ds_from_row_pub(
    c: &Client,
    row: &tokio_postgres::Row,
    sess: &mut Session,
) -> Result<DataSource, String> {
    // reuse the loader (without perms) by wrapping into a temporary session flow
    let id: i32 = row.get(0);
    // ds_from_row is private to load.rs; replicate via load_ds would re-query.
    // Instead call the shared implementation:
    crate::load::ds_from_row_pub(c, row, sess).await.map(|mut d| {
        d.id = Some(id);
        d
    })
}

pub fn ds_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("d.id"),
        "name" => Some("d.name"),
        "type" => Some("d.type"),
        "url" => Some("d.url"),
        "format" => Some("d.format"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// layer appearances
// ---------------------------------------------------------------------------

pub async fn list_appearances(
    c: &Client,
    filters: &[FieldFilter],
    restrict: Option<&[String]>,
) -> Result<Vec<LayerAppearance>, String> {
    let (where_sql, params) = build_where(filters);
    if let Some(fields) = restrict {
        let mut sel = Vec::new();
        let mut cols: Vec<&str> = Vec::new();
        for f in fields {
            let col = appearance_column(f).ok_or("bad field")?;
            sel.push(format!("{} AS {}", col, f));
            cols.push(f.as_str());
        }
        let sql = format!(
            "SELECT {} FROM layerappearances a {} ORDER BY a.id",
            sel.join(", "),
            where_sql
        );
        let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        for r in rows {
            let mut a = LayerAppearance::new_parsed();
            for (i, name) in cols.iter().enumerate() {
                match *name {
                    "id" => a.id = r.get::<_, Option<i32>>(i),
                    "attribution" => a.attribution = r.get(i),
                    "hoverable" => a.hoverable = r.get(i),
                    "clickable" => a.clickable = r.get(i),
                    "hoverTemplate" => a.hover_template = r.get(i),
                    "name" => a.name = r.get(i),
                    "maxResolution" => a.max_resolution = r.get(i),
                    "minResolution" => a.min_resolution = r.get(i),
                    "opacity" => a.opacity = r.get(i),
                    "visible" => a.visible = r.get(i),
                    _ => {}
                }
            }
            out.push(a);
        }
        return Ok(out);
    }
    let sql = format!(
        "SELECT a.id, a.attribution, a.clickable, a.hovertemplate, a.hoverable, a.maxresolution,
                a.minresolution, a.name, a.opacity, a.visible, a.created, a.modified
           FROM layerappearances a {} ORDER BY a.id",
        where_sql
    );
    let rows = c.query(&sql, &bind(&params)).await.map_err(|e| e.to_string())?;
    let mut out: Vec<LayerAppearance> = Vec::new();
    let mut ids = Vec::new();
    for r in &rows {
        out.push(appearance_from_row_pub(r));
        ids.push(out.last().unwrap().id.unwrap());
    }
    let props = load_properties(c, &ids).await?;
    let (up, gp) = load_perms_batch(c, &ids).await?;
    for a in out.iter_mut() {
        let id = a.id.unwrap();
        a.properties = Some(props.get(&id).cloned().unwrap_or_default());
        a.user_perms = up.get(&id).cloned().unwrap_or_default();
        a.group_perms = gp.get(&id).cloned().unwrap_or_default();
    }
    Ok(out)
}

pub async fn list_appearances_by_ids(
    c: &Client,
    ids: &[i32],
) -> Result<HashMap<i32, LayerAppearance>, String> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = c
        .query(
            "SELECT a.id, a.attribution, a.clickable, a.hovertemplate, a.hoverable, a.maxresolution,
                    a.minresolution, a.name, a.opacity, a.visible, a.created, a.modified
               FROM layerappearances a WHERE a.id = ANY($1)",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let props = load_properties(c, ids).await?;
    for r in &rows {
        let mut a = appearance_from_row_pub(r);
        let id = a.id.unwrap();
        a.properties = Some(props.get(&id).cloned().unwrap_or_default());
        out.insert(id, a);
    }
    Ok(out)
}

fn appearance_from_row_pub(row: &tokio_postgres::Row) -> LayerAppearance {
    LayerAppearance {
        id: Some(row.get(0)),
        attribution: row.get(1),
        clickable: row.get(2),
        hover_template: row.get(3),
        hoverable: row.get(4),
        max_resolution: row.get(5),
        min_resolution: row.get(6),
        name: row.get(7),
        opacity: row.get(8),
        visible: row.get(9),
        properties: Some(vec![]),
        created_ms: ts_to_ms(row.get(10)),
        modified_ms: ts_to_ms(row.get(11)),
        user_perms: vec![],
        group_perms: vec![],
    }
}

pub fn appearance_column(field: &str) -> Option<&'static str> {
    match field {
        "id" => Some("a.id"),
        "attribution" => Some("a.attribution"),
        "hoverable" => Some("a.hoverable"),
        "clickable" => Some("a.clickable"),
        "hoverTemplate" => Some("a.hovertemplate"),
        "name" => Some("a.name"),
        "maxResolution" => Some("a.maxresolution"),
        "minResolution" => Some("a.minresolution"),
        "opacity" => Some("a.opacity"),
        "visible" => Some("a.visible"),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// query parameter handling (EntityUtil)
// ---------------------------------------------------------------------------

pub const RESTRICT_FIELDS_PARAM: &str = "output:only";

/// EntityUtil.determineRestrictFields
pub fn determine_restrict_fields(
    params: &[(String, String)],
    all_fields: &[(&str, FieldType)],
) -> Option<Vec<String>> {
    let mut requested: Option<Vec<String>> = None;
    for (k, v) in params {
        if k.eq_ignore_ascii_case(RESTRICT_FIELDS_PARAM) {
            requested = Some(list_from_comma_separated(v));
        }
    }
    let requested = match requested {
        // note: Java's listFromCommaSeparatedStringList returns null for empty
        Some(v) if !v.is_empty() => v,
        _ => return None,
    };
    let mut out: Vec<String> = Vec::new();
    for (name, _) in all_fields {
        for want in &requested {
            if name.eq_ignore_ascii_case(want) {
                out.push(name.to_string());
            }
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn list_from_comma_separated(v: &str) -> Vec<String> {
    v.split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty() || true)
        .map(|s| s.to_string())
        .collect()
}

/// EntityUtil.validFieldNamesWithCastedValues + ConvertUtils casting.
/// Returns field filters keyed by original field name.
pub fn valid_field_filters(
    params: &[(String, String)],
    all_fields: &[(&str, FieldType)],
) -> Vec<FieldFilterValue> {
    let mut out: Vec<FieldFilterValue> = Vec::new();
    for (key, val) in params {
        if key == RESTRICT_FIELDS_PARAM {
            continue; // removed via MultiValueMap.remove (case sensitive)
        }
        for (name, ty) in all_fields {
            if name.eq_ignore_ascii_case(key) {
                out.push(FieldFilterValue {
                    field: name.to_string(),
                    ty: *ty,
                    value: cast_value(val, *ty),
                });
                break;
            }
        }
    }
    out
}

pub struct FieldFilterValue {
    pub field: String,
    pub ty: FieldType,
    pub value: FVal,
}

/// ConvertUtils.convert semantics: failures fall back to the type default.
fn cast_value(s: &str, ty: FieldType) -> FVal {
    let t = s.trim();
    match ty {
        FieldType::Str => FVal::Str(s.clone()),
        FieldType::BoolPrim | FieldType::BoolWrap => match t.to_ascii_lowercase().as_str() {
            "true" | "yes" | "on" | "1" => FVal::Bool(true),
            "false" | "no" | "off" | "0" => FVal::Bool(false),
            _ => FVal::Bool(false), // converter default FALSE
        },
        FieldType::IntWrap => match t.parse::<i64>() {
            Ok(v) if v >= i32::MIN as i64 && v <= i32::MAX as i64 => FVal::Int(v as i32),
            _ => FVal::Int(0), // converter default 0
        },
        FieldType::DblWrap => match t.parse::<f64>() {
            Ok(v) => FVal::Dbl(v),
            _ => FVal::Dbl(0.0),
        },
    }
}

pub fn to_field_filters(
    values: Vec<FieldFilterValue>,
    column_of: fn(&str) -> Option<&'static str>,
) -> Vec<FieldFilter> {
    let mut out: Vec<FieldFilter> = Vec::new();
    for v in values {
        let col = match column_of(&v.field) {
            Some(c) => c,
            None => continue,
        };
        if let Some(existing) = out.iter_mut().find(|f| f.column == col) {
            existing.values.push(v.value);
        } else {
            out.push(FieldFilter {
                column: col,
                values: vec![v.value],
            });
        }
    }
    out
}

#[allow(dead_code)]
pub fn jval_unused() -> JVal {
    JVal::Null
}
