                        }
                        _ => return Err(DError("matrixIds must be array".into())),
                    }
                }
            }
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_datasource(d: &mut DataSource, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        let handled = match k.as_str() {
            "id" => {
                d.id = to_id(v)?;
                true
            }
            "name" => {
                d.name = to_str(v)?;
                true
            }
            "type" => {
                d.type_ = to_str(v)?;
                true
            }
            "url" => {
                d.url = to_str(v)?;
                true
            }
            "format" => {
                d.format = to_str(v)?;
                true
            }
            _ => false,
        };
        if handled {
            continue;
        }
        match d.kind {
            DsKind::ImageWms | DsKind::TileWms => match k.as_str() {
                "width" => d.width = to_i32(v)?,
                "height" => d.height = to_i32(v)?,
                "version" => d.version = to_str(v)?,
                "layerNames" => d.layer_names = to_str(v)?,
                "layerStyles" => d.layer_styles = to_str(v)?,
                "requestableByPath" => d.requestable_by_path = to_bool_wrap(v)?,
                "customRequestPath" => d.custom_request_path = to_str(v)?,
                "tileGrid" if d.kind == DsKind::TileWms => {
                    if v.is_null() {
                        d.tile_grid = None;
                    } else {
                        let mut t = TileGrid::new_parsed(d.kind == DsKind::TileWms && false);
                        // property type is plain TileGrid
                        let mut t = TileGrid::new_parsed(false);
                        apply_tilegrid(&mut t, v).await?;
                        d.tile_grid = Some(Box::new(t));
                    }
                }
                "requestWithTiled" if d.kind == DsKind::TileWms => {
                    d.request_with_tiled = to_bool_wrap(v)?
                }
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Wfs => match k.as_str() {
                "version" => d.version = to_str(v)?,
                "typeName" => d.type_name = to_str(v)?,
                "typeNames" => d.type_names = to_str(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Wmts => match k.as_str() {
                "tileGrid" => {
                    if v.is_null() {
                        d.tile_grid = None;
                    } else {
                        let mut t = TileGrid::new_parsed(true);
                        apply_tilegrid(&mut t, v).await?;
                        d.tile_grid = Some(Box::new(t));
                    }
                }
                "urls" => {
                    if v.is_null() {
                        d.urls = None;
                    } else {
                        match v {
                            JVal::Arr(items) => {
                                let mut out = Vec::new();
                                for it in items {
                                    match to_str(it)? {
                                        Some(s) => out.push(s),
                                        None => return Err(DError("null in urls".into())),
                                    }
                                }
                                d.urls = Some(out);
                            }
                            _ => return Err(DError("urls must be array".into())),
                        }
                    }
                }
                "wmtsLayer" => d.wmts_layer = to_str(v)?,
                "wmtsStyle" => d.wmts_style = to_str(v)?,
                "projection" => d.projection = to_str(v)?,
                "matrixSet" => d.matrix_set = to_str(v)?,
                "requestEncoding" => d.request_encoding = to_str(v)?,
                "capabilitiesUrl" => d.capabilities_url = to_str(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Xyz => match k.as_str() {
                "center" => d.center = to_point(v)?,
                "extent" => {
                    if v.is_null() {
                        d.extent = None;
                    } else {
                        let mut e = Extent::new_parsed();
                        apply_extent(&mut e, v).await?;
                        d.extent = Some(Box::new(e));
                    }
                }
                "resolutions" => {
                    if v.is_null() {
                        d.resolutions = None;
                    } else {
                        match v {
                            JVal::Arr(items) => {
                                let mut out = Vec::new();
                                for it in items {
                                    match to_point(it)? {
                                        Some(p) => out.push(p),
                                        None => out.push((0.0, 0.0)),
                                    }
                                }
                                d.resolutions = Some(out);
                            }
                            _ => return Err(DError("resolutions must be array".into())),
                        }
                    }
                }
                "tileSize" => d.tile_size = to_i32_wrap(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
        }
        let _ = ctx;
    }
    Ok(())
}

pub async fn apply_layer(l: &mut Layer, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => l.id = to_id(v)?,
            "name" => l.name = to_str(v)?,
            "description" => l.description = to_str(v)?,
            "source" => {
                if v.is_null() {
                    l.source = None;
                } else {
                    // LayerDataSource is abstract: Jackson cannot instantiate it
                    return Err(DError(
                        "Cannot construct instance of LayerDataSource (abstract type)".into(),
                    ));
                }
            }
            "appearance" => {
                if v.is_null() {
                    l.appearance = None;
                } else {
                    let mut a = LayerAppearance::new_parsed();
                    apply_appearance(&mut a, v).await?;
                    l.appearance = Some(Box::new(a));
                }
            }
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

/// Jackson's JsonNode.asInt() for the PUT id comparison
