{"content": "// Jackson-compatible deserialisation: strict unknown-property handling,
// type coercions, @JsonIgnore'd properties, write-only password,
// JsonIdentityInfo userGroups resolution, and the abstract LayerDataSource
// instantiation failure.

use crate::jval::*;
use crate::load::*;
use crate::model::*;
use crate::perms::{eval_group, AuthUser};
use tokio_postgres::Client;

pub struct DError(pub String);

pub struct Ctx<'a> {
    pub client: &'a Client,
    pub auth: &'a AuthUser,
    pub sess: &'a mut Session,
}

// ---------------------------------------------------------------------------
// scalar coercions (Jackson rules)
// ---------------------------------------------------------------------------

fn to_str(v: &JVal) -> Result<Option<String>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) => Ok(Some(s.clone())),
        JVal::Int(_, raw) => Ok(Some(raw.clone())),
        JVal::Float(_, raw) => Ok(Some(raw.clone())),
        JVal::Bool(b) => Ok(Some(if *b { "true".into() } else { "false".into() })),
        _ => Err(DError("cannot coerce to String".into())),
    }
}

fn to_bool(v: &JVal) -> Result<bool, DError> {
    match v {
        JVal::Null => Ok(false),
        JVal::Bool(b) => Ok(*b),
        JVal::Int(i, _) => Ok(*i != 0),
        JVal::Float(f, _) => Ok(*f != 0.0),
        JVal::Str(s) => {
            let t = s.trim();
            if t.eq_ignore_ascii_case("true") {
                Ok(true)
            } else if t.eq_ignore_ascii_case("false") || t.is_empty() {
                Ok(false)
            } else {
                Err(DError("cannot coerce to boolean".into()))
            }
        }
        _ => Err(DError("cannot coerce to boolean".into())),
    }
}

fn to_bool_wrap(v: &JVal) -> Result<Option<bool>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) if s.trim().is_empty() => Ok(None),
        other => to_bool(other).map(Some),
    }
}

fn to_i32(v: &JVal) -> Result<i32, DError> {
    match v {
        JVal::Null => Ok(0),
        JVal::Bool(_) => Err(DError("cannot coerce boolean to int".into())),
        JVal::Int(i, _) => {
            if *i >= i32::MIN as i64 && *i <= i32::MAX as i64 {
                Ok(*i as i32)
            } else {
                Err(DError("numeric overflow".into()))
            }
        }
        JVal::Float(f, _) => Ok(*f as i32),
        JVal::Str(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(0)
            } else {
                // Jackson: integer strings only
                match t.parse::<i64>() {
                    Ok(i) if i >= i32::MIN as i64 && i <= i32::MAX as i64 => Ok(i as i32),
                    _ => Err(DError("cannot coerce to int".into())),
                }
            }
        }
        _ => Err(DError("cannot coerce to int".into())),
    }
}

fn to_i32_wrap(v: &JVal) -> Result<Option<i32>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) if s.trim().is_empty() => Ok(None),
        other => to_i32(other).map(Some),
    }
}

fn to_f64_wrap(v: &JVal) -> Result<Option<f64>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Bool(_) => Err(DError("cannot coerce boolean to double".into())),
        JVal::Int(i, _) => Ok(Some(*i as f64)),
        JVal::Float(f, _) => Ok(Some(*f)),
        JVal::Str(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                t.parse::<f64>()
                    .map(Some)
                    .map_err(|_| DError("cannot coerce to double".into()))
            }
        }
        _ => Err(DError("cannot coerce to double".into())),
    }
}

fn to_id(v: &JVal) -> Result<Option<i32>, DError> {
    // Jackson can set the private final id field; same coercions as int
    match v {
        JVal::Null => Ok(None),
        other => to_i32_wrap(other),
    }
}

fn to_point(v: &JVal) -> Result<Option<(f64, f64)>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Obj(entries) => {
            let mut x = 0.0f64;
            let mut y = 0.0f64;
            for (k, val) in entries {
                match k.as_str() {
                    "x" => x = to_f64_wrap(val)?.unwrap_or(0.0),
                    "y" => y = to_f64_wrap(val)?.unwrap_or(0.0),
                    _ => return Err(DError(format!("Unrecognized field {}", k))),
                }
            }
            Ok(Some((x, y)))
        }
        _ => Err(DError("cannot construct Point2D".into())),
    }
}

fn to_date(v: &JVal) -> Result<Option<String>, DError> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) => {
            // joda LocalDate ISO parser: yyyy-MM-dd
            match chrono::NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d") {
                Ok(d) => Ok(Some(d.format("%Y-%m-%d").to_string())),
                Err(_) => Err(DError("invalid date".into())),
            }
        }
        JVal::Arr(items) if items.len() == 3 => {
            let y = to_i32(&items[0])?;
            let m = to_i32(&items[1])?;
            let d = to_i32(&items[2])?;
            match chrono::NaiveDate::from_ymd_opt(y, m as u32, d as u32) {
                Some(dt) => Ok(Some(dt.format("%Y-%m-%d").to_string())),
                None => Err(DError("invalid date".into())),
            }
        }
        _ => Err(DError("invalid date".into())),
    }
}

// ---------------------------------------------------------------------------
// entity parsing / merging
// ---------------------------------------------------------------------------

const IGNORED: &[&str] = &["created", "modified", "userPermissions", "groupPermissions"];

fn unknown(key: &str) -> DError {
    DError(format!("Unrecognized field \"{}\"", key))
}

pub async fn apply_role(r: &mut Role, obj: &JVal) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => r.id = to_id(v)?,
            "name" => r.name = to_str(v)?,
            "description" => r.description = to_str(v)?,
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_user(u: &mut User, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => u.id = to_id(v)?,
            "firstName" => u.first_name = to_str(v)?,
            "lastName" => u.last_name = to_str(v)?,
            "email" => u.email = to_str(v)?,
            "birthday" => u.birthday = to_date(v)?,
            "language" => u.language = to_str(v)?,
            "accountName" => u.account_name = to_str(v)?,
            "password" => u.password = to_str(v)?,
            "active" => u.active = to_bool(v)?,
            "roles" => {
                u.roles = Some(parse_set_roles(v).await?);
            }
            "userGroups" => {
                u.user_groups = Some(parse_user_groups(v, ctx).await?);
            }
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

async fn parse_set_roles(v: &JVal) -> Result<Vec<Role>, DError> {
    match v {
        JVal::Null => Ok(vec![]), // caller decides null-vs-empty via wrapper below
        JVal::Arr(items) => {
            let mut out: Vec<Role> = Vec::new();
            for it in items {
                match it {
                    JVal::Obj(_) => {
                        let mut r = Role::new_parsed();
                        apply_role(&mut r, it).await?;
                        set_add_role(&mut out, r);
                    }
                    _ => return Err(DError("null/invalid element in roles".into())),
                }
            }
            Ok(out)
        }
        _ => Err(DError("roles must be array".into())),
    }
}

/// Returns None when the JSON value was null (property cleared).
async fn parse_roles_opt(v: &JVal) -> Result<Option<Vec<Role>>, DError> {
    if v.is_null() {
        Ok(None)
    } else {
        Ok(Some(parse_set_roles(v).await?))
    }
}

async fn parse_user_groups(v: &JVal, ctx: &mut Ctx<'_>) -> Result<Vec<UserGroup>, DError> {
    match v {
        JVal::Null => Ok(vec![]),
        JVal::Arr(items) => {
            let mut out: Vec<UserGroup> = Vec::new();
            for it in items {
                match it {
                    JVal::Int(_, _) | JVal::Float(_, _) | JVal::Str(_) => {
                        let id = to_i32(it)?;
                        let g = resolve_group(ctx, id).await?;
                        push_group_dedup(&mut out, g);
                    }
                    JVal::Obj(entries) => {
                        let idv = entries.iter().find(|(k, _)| k == "id").map(|(_, x)| x);
                        match idv {
                            Some(idv) if !idv.is_null() => {
                                let id = to_i32(idv)?;
                                let g = resolve_group(ctx, id).await?;
                                push_group_dedup(&mut out, g);
                            }
                            _ => {
                                // full object without id -> transient (flush fails later,
                                // like the original's "unsaved transient instance")
                                let mut g = UserGroup::new_parsed();
                                apply_group(&mut g, it, ctx).await?;
                                set_add_group(&mut out, g);
                            }
                        }
                    }
                    _ => return Err(DError("invalid element in userGroups".into())),
                }
            }
            Ok(out)
        }
        _ => Err(DError("userGroups must be array".into())),
    }
}

fn push_group_dedup(v: &mut Vec<UserGroup>, g: UserGroup) {
    // managed instances: identity dedup by id
    if let Some(id) = g.id {
        if v.iter().any(|e| e.id == Some(id)) {
            return;
        }
    }
    v.push(g);
}

/// UserGroupIdResolver.resolveId -> userGroupService.loadById (with READ check)
async fn resolve_group(ctx: &mut Ctx<'_>, id: i32) -> Result<UserGroup, DError> {
    let exists = ctx
        .client
        .query_opt("SELECT id FROM usergroups WHERE id = $1", &[&id])
        .await
        .map_err(|e| DError(e.to_string()))?
        .is_some();
    if !exists {
        // ObjectNotFoundException is thrown during deserialisation
        return Err(DError(format!(
            "No row with the given identifier exists: [UserGroup#{}]",
            id
        )));
    }
    let g = load_group(ctx.client, id, ctx.sess)
        .await
        .map_err(|e| DError(e))?;
    match g {
        Some(g) => {
            if !ctx.auth.is_admin && !eval_group(ctx.auth, &g, Perm::Read) {
                // resolver swallows AccessDeniedException and returns null;
                // a null element fails at flush time. Model that with a
                // "poisoned" group without id.
                return Ok(UserGroup::new_parsed());
            }
            Ok(g)
        }
        None => Err(DError("group vanished".into())),
    }
}

async fn parse_members(v: &JVal, ctx: &mut Ctx<'_>) -> Result<Option<Vec<User>>, DError> {
    if v.is_null() {
        return Ok(None);
    }
    match v {
        JVal::Arr(items) => {
            let mut out: Vec<User> = Vec::new();
            for it in items {
                match it {
                    JVal::Obj(_) => {
                        let mut u = User::new_parsed();
                        apply_user(&mut u, it, ctx).await?;
                        set_add_user(&mut out, u);
                    }
                    _ => return Err(DError("invalid element in members".into())),
                }
            }
            Ok(Some(out))
        }
        _ => Err(DError("members must be array".into())),
    }
}

pub async fn apply_group(g: &mut UserGroup, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => g.id = to_id(v)?,
            "name" => g.name = to_str(v)?,
            "owner" => {
                if v.is_null() {
                    g.owner = None;
                } else {
                    let mut u = User::new_parsed();
                    apply_user(&mut u, v, ctx).await?;
                    g.owner = Some(Box::new(u));
                }
            }
            "members" => g.members = parse_members(v, ctx).await?,
            "roles" => g.roles = parse_roles_opt(v).await?,
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_appearance(a: &mut LayerAppearance, obj: &JVal) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => a.id = to_id(v)?,
            "attribution" => a.attribution = to_str(v)?,
            "hoverable" => a.hoverable = to_bool_wrap(v)?,
            "clickable" => a.clickable = to_bool_wrap(v)?,
            "hoverTemplate" => a.hover_template = to_str(v)?,
            "properties" => {
                if v.is_null() {
                    a.properties = None;
                } else {
                    match v {
                        JVal::Obj(es) => {
                            a.properties = Some(es.iter().map(|(k2, v2)| (k2.clone(), v2.clone())).collect());
                        }
                        _ => return Err(DError("properties must be object".into())),
                    }
                }
            }
            "name" => a.name = to_str(v)?,
            "maxResolution" => a.max_resolution = to_f64_wrap(v)?,
            "minResolution" => a.min_resolution = to_f64_wrap(v)?,
            "opacity" => a.opacity = to_f64_wrap(v)?,
            "visible" => a.visible = to_bool_wrap(v)?,
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_extent(e: &mut Extent, obj: &JVal) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(x) => x,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => e.id = to_id(v)?,
            "lowerLeft" => e.lower_left = to_point(v)?,
            "upperRight" => e.upper_right = to_point(v)?,
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_tilegrid(t: &mut TileGrid, obj: &JVal) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => t.id = to_id(v)?,
            "type" => t.type_ = to_str(v)?,
            "tileGridOrigin" => t.origin = to_point(v)?,
            "tileGridExtent" => {
                if v.is_null() {
                    t.extent = None;
                } else {
                    let mut e = Extent::new_parsed();
                    apply_extent(&mut e, v).await?;
                    t.extent = Some(Box::new(e));
                }
            }
            "tileSize" => t.tile_size = to_i32_wrap(v)?,
            "tileGridResolutions" => {
                if v.is_null() {
                    t.resolutions = None;
                } else {
                    match v {
                        JVal::Arr(items) => {
                            let mut out = Vec::new();
                            for it in items {
                                out.push(to_f64_wrap(it)?.unwrap_or(0.0));
                            }
                            t.resolutions = Some(out);
                        }
                        _ => return Err(DError("resolutions must be array".into())),
                    }
                }
            }
            "matrixIds" => {
                if !t.is_wmts {
                    return Err(unknown(k));
                }
                if v.is_null() {
                    t.matrix_ids = None;
                } else {
                    match v {
                        JVal::Arr(items) => {
                            let mut out = Vec::new();
                            for it in items {
                                match to_str(it)? {
                                    Some(s) => out.push(s),
                                    None => return Err(DError("null in matrixIds".into())),
                                }
                            }
                            t.matrix_ids = Some(out);
                        }
                        _ => return Err(DError("matrixIds must be array".into())),
                    }
                }
            }
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

pub async fn apply_datasource(d: &mut DataSource, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        let handled = match k.as_str() {
            "id" => {
                d.id = to_id(v)?;
                true
            }
            "name" => {
                d.name = to_str(v)?;
                true
            }
            "type" => {
                d.type_ = to_str(v)?;
                true
            }
            "url" => {
                d.url = to_str(v)?;
                true
            }
            "format" => {
                d.format = to_str(v)?;
                true
            }
            _ => false,
        };
        if handled {
            continue;
        }
        match d.kind {
            DsKind::ImageWms | DsKind::TileWms => match k.as_str() {
                "width" => d.width = to_i32(v)?,
                "height" => d.height = to_i32(v)?,
                "version" => d.version = to_str(v)?,
                "layerNames" => d.layer_names = to_str(v)?,
                "layerStyles" => d.layer_styles = to_str(v)?,
                "requestableByPath" => d.requestable_by_path = to_bool_wrap(v)?,
                "customRequestPath" => d.custom_request_path = to_str(v)?,
                "tileGrid" if d.kind == DsKind::TileWms => {
                    if v.is_null() {
                        d.tile_grid = None;
                    } else {
                        let mut t = TileGrid::new_parsed(d.kind == DsKind::TileWms && false);
                        // property type is plain TileGrid
                        let mut t = TileGrid::new_parsed(false);
                        apply_tilegrid(&mut t, v).await?;
                        d.tile_grid = Some(Box::new(t));
                    }
                }
                "requestWithTiled" if d.kind == DsKind::TileWms => {
                    d.request_with_tiled = to_bool_wrap(v)?
                }
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Wfs => match k.as_str() {
                "version" => d.version = to_str(v)?,
                "typeName" => d.type_name = to_str(v)?,
                "typeNames" => d.type_names = to_str(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Wmts => match k.as_str() {
                "tileGrid" => {
                    if v.is_null() {
                        d.tile_grid = None;
                    } else {
                        let mut t = TileGrid::new_parsed(true);
                        apply_tilegrid(&mut t, v).await?;
                        d.tile_grid = Some(Box::new(t));
                    }
                }
                "urls" => {
                    if v.is_null() {
                        d.urls = None;
                    } else {
                        match v {
                            JVal::Arr(items) => {
                                let mut out = Vec::new();
                                for it in items {
                                    match to_str(it)? {
                                        Some(s) => out.push(s),
                                        None => return Err(DError("null in urls".into())),
                                    }
                                }
                                d.urls = Some(out);
                            }
                            _ => return Err(DError("urls must be array".into())),
                        }
                    }
                }
                "wmtsLayer" => d.wmts_layer = to_str(v)?,
                "wmtsStyle" => d.wmts_style = to_str(v)?,
                "projection" => d.projection = to_str(v)?,
                "matrixSet" => d.matrix_set = to_str(v)?,
                "requestEncoding" => d.request_encoding = to_str(v)?,
                "capabilitiesUrl" => d.capabilities_url = to_str(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
            DsKind::Xyz => match k.as_str() {
                "center" => d.center = to_point(v)?,
                "extent" => {
                    if v.is_null() {
                        d.extent = None;
                    } else {
                        let mut e = Extent::new_parsed();
                        apply_extent(&mut e, v).await?;
                        d.extent = Some(Box::new(e));
                    }
                }
                "resolutions" => {
                    if v.is_null() {
                        d.resolutions = None;
                    } else {
                        match v {
                            JVal::Arr(items) => {
                                let mut out = Vec::new();
                                for it in items {
                                    match to_point(it)? {
                                        Some(p) => out.push(p),
                                        None => out.push((0.0, 0.0)),
                                    }
                                }
                                d.resolutions = Some(out);
                            }
                            _ => return Err(DError("resolutions must be array".into())),
                        }
                    }
                }
                "tileSize" => d.tile_size = to_i32_wrap(v)?,
                k if IGNORED.contains(&k) => {}
                _ => return Err(unknown(k)),
            },
        }
        let _ = ctx;
    }
    Ok(())
}

pub async fn apply_layer(l: &mut Layer, obj: &JVal, ctx: &mut Ctx<'_>) -> Result<(), DError> {
    let entries = match obj {
        JVal::Obj(e) => e,
        _ => return Err(DError("not an object".into())),
    };
    for (k, v) in entries {
        match k.as_str() {
            "id" => l.id = to_id(v)?,
            "name" => l.name = to_str(v)?,
            "description" => l.description = to_str(v)?,
            "source" => {
                if v.is_null() {
                    l.source = None;
                } else {
                    // LayerDataSource is abstract: Jackson cannot instantiate it
                    return Err(DError(
                        "Cannot construct instance of LayerDataSource (abstract type)".into(),
                    ));
                }
            }
            "appearance" => {
                if v.is_null() {
                    l.appearance = None;
                } else {
                    let mut a = LayerAppearance::new_parsed();
                    apply_appearance(&mut a, v).await?;
                    l.appearance = Some(Box::new(a));
                }
            }
            k if IGNORED.contains(&k) => {}
            _ => return Err(unknown(k)),
        }
    }
    Ok(())
}

