fn require_ids_roles(roles: &Option<Vec<Role>>) -> WResult<Vec<i32>> {
    let mut out = Vec::new();
    if let Some(rs) = roles {
        for r in rs {
            match r.id {
                Some(id) => {
                    if !out.contains(&id) {
                        out.push(id);
                    }
                }
                None => {
                    return Err(
                        "object references an unsaved transient instance - save the transient instance before flushing"
                            .into(),
                    )
                }
            }
        }
    }
    Ok(out)
}

fn require_ids_users(users: &Option<Vec<User>>) -> WResult<Vec<i32>> {
    let mut out = Vec::new();
    if let Some(us) = users {
