    wctx: &WCtx<'_>,
    l: &mut Layer,
) -> WResult<()> {
    let id = alloc(pool).await?;
    l.id = Some(id);
    let appearance_id = apply_appearance_cascade(c, pool, wctx.sess, &l.appearance).await?;
    if let (Some(a), Some(aid)) = (&mut l.appearance, appearance_id) {
        a.id = Some(aid);
    }
    let t = now();
    c.execute(
        "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7)",
        &[
