}

pub async fn update_datasource(
    c: &Client,
    pool: &DbPool,
    wctx: &WCtx<'_>,
    d: &mut DataSource,
    flags: &DsFlags,
) -> WResult<()> {
    let id = d.id.unwrap();
    let t = now();
    c.execute(
        "UPDATE layerdatasources SET format=$2, name=$3, type=$4, url=$5, modified=$6 WHERE id=$1",
        &[&id, &d.format, &d.name, &d.type_, &d.url, &t],
    )
    .await
    .map_err(|e| e.to_string())?;
    match d.kind {
        DsKind::ImageWms => {
            c.execute(
                "UPDATE imagewmslayerdatasources SET customrequestpath=$2, height=$3, layernames=$4,
                        layerstyles=$5, requestablebypath=$6, version=$7, width=$8 WHERE id=$1",
                &[
                    &id,
                    &d.custom_request_path,
                    &d.height,
                    &d.layer_names,
                    &d.layer_styles,
                    &d.requestable_by_path,
                    &d.version,
                    &d.width,
                ],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
        DsKind::TileWms => {
            c.execute(
                "UPDATE imagewmslayerdatasources SET customrequestpath=$2, height=$3, layernames=$4,
                        layerstyles=$5, requestablebypath=$6, version=$7, width=$8 WHERE id=$1",
                &[
                    &id,
                    &d.custom_request_path,
                    &d.height,
                    &d.layer_names,
                    &d.layer_styles,
                    &d.requestable_by_path,
                    &d.version,
                    &d.width,
                ],
            )
            .await
            .map_err(|e| e.to_string())?;
            let mut tilegrid_id = match &d.tile_grid {
                Some(tg) => tg.id,
                None => None,
            };
            if flags.tile_grid {
                tilegrid_id = apply_tilegrid_cascade(
                    c,
                    pool,
                    wctx.sess,
                    &d.tile_grid,
                    SKind::TileGrid,
                    SKind::WmtsTileGrid,
                )
                .await?;
                if let (Some(tg), Some(tid)) = (&mut d.tile_grid, tilegrid_id) {
                    tg.id = Some(tid);
                }
            }
            c.execute(
                "UPDATE tilewmslayerdatasources SET request_with_tiled=$2, tilegrid_id=$3 WHERE id=$1",
                &[&id, &d.request_with_tiled, &tilegrid_id],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
        DsKind::Wfs => {
            c.execute(
                "UPDATE wfslayerdatasources SET typename=$2, typenames=$3, version=$4 WHERE id=$1",
                &[&id, &d.type_name, &d.type_names, &d.version],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
        DsKind::Wmts => {
            let mut tilegrid_id = match &d.tile_grid {
                Some(tg) => tg.id,
                None => None,
            };
            if flags.tile_grid {
                tilegrid_id = apply_tilegrid_cascade(
                    c,
                    pool,
                    wctx.sess,
                    &d.tile_grid,
                    SKind::TileGrid,
                    SKind::WmtsTileGrid,
                )
                .await?;
                if let (Some(tg), Some(tid)) = (&mut d.tile_grid, tilegrid_id) {
                    tg.id = Some(tid);
                }
            }
            c.execute(
                "UPDATE wmtslayerdatasources SET capabilitiesurl=$2, matrixset=$3, projection=$4,
                        requestencoding=$5, wmtslayer=$6, wmtsstyle=$7, tilegrid_id=$8 WHERE id=$1",
                &[
                    &id,
                    &d.capabilities_url,
                    &d.matrix_set,
                    &d.projection,
                    &d.request_encoding,
                    &d.wmts_layer,
                    &d.wmts_style,
                    &tilegrid_id,
                ],
            )
            .await
            .map_err(|e| e.to_string())?;
            c.execute(
                "DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id=$1",
                &[&id],
            )
            .await
            .map_err(|e| e.to_string())?;
            if let Some(urls) = &d.urls {
                for u in urls {
                    c.execute(
                        "INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1,$2)",
                        &[&id, &Some(u.clone())],
                    )
                    .await
                    .map_err(|e| e.to_string())?;
                }
            }
        }
        DsKind::Xyz => {
            let extent_id = match &d.extent {
                Some(e) => match e.id {
                    Some(eid) => Some(eid),
                    None => {
                        return Err(
                            "object references an unsaved transient instance - save the transient instance before flushing"
                                .into(),
                        )
                    }
                },
                None => None,
            };
            let (cx, cy) = match d.center {
                Some((x, y)) => (Some(x), Some(y)),
                None => (None, None),
            };
            c.execute(
                "UPDATE xyzlayerdatasources SET center_x=$2, center_y=$3, tilesize=$4, extent_id=$5 WHERE id=$1",
                &[&id, &cx, &cy, &d.tile_size, &extent_id],
            )
            .await
            .map_err(|e| e.to_string())?;
            c.execute(
                "DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id=$1",
                &[&id],
            )
            .await
            .map_err(|e| e.to_string())?;
            if let Some(rs) = &d.resolutions {
                for (i, (x, y)) in rs.iter().enumerate() {
                    let bytes = serialize_point(*x, *y);
                    c.execute(
                        "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) VALUES ($1,$2,$3)",
                        &[&id, &bytes, &(i as i32)],
                    )
                    .await
                    .map_err(|e| e.to_string())?;
                }
            }
        }
    }
    Ok(())
}

