metadata.rawInput:
{"content": "// Persistence: mirrors Hibernate's save/update/delete behaviour on the
// existing schema, including cascade SAVE_UPDATE semantics (create, wipe on
// re-attach, NonUniqueObject conflicts), join-table rewrites and the
// hibernate_sequences id allocation.

use crate::db::*;
use crate::jval::*;
use crate::load::{ds_skind, Session, SKind};
use crate::model::*;
use tokio_postgres::Client;

pub type WResult<T> = Result<T, String>;

pub struct WCtx<'a> {
    pub pool: &'a DbPool,
    pub sess: &'a Session,
}

fn now() -> chrono::NaiveDateTime {
    now_naive()
}

async fn alloc(pool: &DbPool) -> WResult<i32> {
    next_id(pool).await
}

fn props_to_rows(props: &Option<Vec<(String, JVal)>>) -> Vec<(String, Option<String>)> {
    let mut out = Vec::new();
    if let Some(ps) = props {
        for (k, v) in ps {
            if matches!(v, JVal::Null) {
                // Hibernate skips null-valued map entries
                continue;
            }
            out.push((k.clone(), java_to_string(v)));
        }
    }
    out
}

// ---------------------------------------------------------------------------
// extents / tile grids (cascade children)
// ---------------------------------------------------------------------------

async fn insert_extent(c: &Client, pool: &DbPool, e: &mut Extent) -> WResult<()> {
    let id = alloc(pool).await?;
    e.id = Some(id);
    let t = now();
    let (lx, ly) = match e.lower_left {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    let (ux, uy) = match e.upper_right {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    c.execute(
        "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y)
         VALUES ($1,$2,$3,$4,$5,$6,$7)",
        &[&id, &t, &t, &lx, &ly, &ux, &uy],
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(())
}

async fn wipe_extent(c: &Client, e: &Extent) -> WResult<()> {
    let id = e.id.unwrap();
    let (lx, ly) = match e.lower_left {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    let (ux, uy) = match e.upper_right {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    let n = c
        .execute(
            "UPDATE extents SET lowerleft_x=$2, lowerleft_y=$3, upperright_x=$4, upperright_y=$5, modified=$6
              WHERE id=$1",
            &[&id, &lx, &ly, &ux, &uy, &now()],
        )
        .await
        .map_err(|e| e.to_string())?;
    if n == 0 {
        return Err(format!("No row with the given identifier exists: [Extent#{}]", id));
    }
    Ok(())
}

/// cascade SAVE_UPDATE handling for TileGrid.tileGridExtent
async fn apply_extent_cascade(
    c: &Client,
    pool: &DbPool,
    sess: &Session,
    ext: &Option<Box<Extent>>,
) -> WResult<Option<i32>> {
    match ext {
        None => Ok(None),
        Some(e) => {
            if let Some(id) = e.id {
                if sess.contains(SKind::Extent, id) {
                    return Err(format!(
                        "A different object with the same identifier value was already associated with the session : [Extent#{}]",
                        id
                    ));
                }
                wipe_extent(c, e).await?;
                Ok(Some(id))
            } else {
                let mut e2 = (**e).clone();
                insert_extent(c, pool, &mut e2).await?;
                Ok(e2.id)
            }
        }
    }
}

/// java.io.ObjectOutputStream bytes for java.awt.geom.Point2D$Double
fn serialize_point(x: f64, y: f64) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(&[0xAC, 0xED, 0x00, 0x05]); // stream header
    out.extend_from_slice(&[0x73, 0x72]); // TC_OBJECT TC_CLASSDESC
    let name = b"java.awt.geom.Point2D$Double";
    out.extend_from_slice(&(name.len() as u16).to_be_bytes());
    out.extend_from_slice(name);
    out.extend_from_slice(&6475294246734157412i64.to_be_bytes()); // serialVersionUID
    out.push(0x02); // SC_SERIALIZABLE
    out.extend_from_slice(&2u16.to_be_bytes()); // field count
    out.push(b'D');
    out.extend_from_slice(&1u16.to_be_bytes());
    out.push(b'x');
    out.push(b'D');
    out.extend_from_slice(&1u16.to_be_bytes());
    out.push(b'y');
    out.push(0x78); // TC_ENDBLOCKDATA
    out.push(0x70); // TC_NULL (no superclass)
    out.extend_from_slice(&x.to_be_bytes());
    out.extend_from_slice(&y.to_be_bytes());
    out
}

async fn insert_tilegrid(c: &Client, pool: &DbPool, t: &mut TileGrid) -> WResult<()> {
    let id = alloc(pool).await?;
    t.id = Some(id);
    let extent_id = apply_extent_cascade(c, pool, &Session::default(), &t.extent).await?;
    let tm = now();
    let (ox, oy) = match t.origin {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    c.execute(
        "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
        &[&id, &tm, &tm, &ox, &oy, &t.tile_size, &t.type_, &extent_id],
    )
    .await
    .map_err(|e| e.to_string())?;
    if t.is_wmts {
        c.execute("INSERT INTO wmtstilegrids (id) VALUES ($1)", &[&id])
            .await
            .map_err(|e| e.to_string())?;
        if let Some(ms) = &t.matrix_ids {
            for m in ms {
                c.execute(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1,$2)",
                    &[&id, &Some(m.clone())],
                )
                .await
                .map_err(|e| e.to_string())?;
            }
        }
    }
    if let Some(rs) = &t.resolutions {
        for (i, r) in rs.iter().enumerate() {
            c.execute(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, &Some(*r), &(i as i32)],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

async fn wipe_tilegrid(c: &Client, pool: &DbPool, sess: &Session, t: &TileGrid) -> WResult<()> {
    let id = t.id.unwrap();
    // verify existence and concrete class match (WrongClassException otherwise)
    let row = c
        .query_opt(
            "SELECT (SELECT count(*) FROM wmtstilegrids w WHERE w.id = t.id) > 0 FROM tilegrids t WHERE t.id=$1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    match row {
        None => {
            return Err(format!(
                "No row with the given identifier exists: [TileGrid#{}]",
                id
            ))
        }
        Some(r) => {
            let is_wmts: bool = r.get(0);
            if is_wmts != t.is_wmts {
                return Err(format!(
                    "Object with id {} is of a different class",
                    id
                ));
            }
        }
    }
    let extent_id = apply_extent_cascade(c, pool, sess, &t.extent).await?;
    let (ox, oy) = match t.origin {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    c.execute(
        "UPDATE tilegrids SET tilegridorigin_x=$2, tilegridorigin_y=$3, tilesize=$4, type=$5,
                tilegridextent_id=$6, modified=$7 WHERE id=$1",
        &[&id, &ox, &oy, &t.tile_size, &t.type_, &extent_id, &now()],
    )
    .await
    .map_err(|e| e.to_string())?;
    c.execute("DELETE FROM tilegrid_resolution WHERE tilegrid_id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    if let Some(rs) = &t.resolutions {
        for (i, r) in rs.iter().enumerate() {
            c.execute(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, &Some(*r), &(i as i32)],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
    }
    if t.is_wmts {
        c.execute(
            "DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id=$1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
        if let Some(ms) = &t.matrix_ids {
            for m in ms {
                c.execute(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1,$2)",
                    &[&id, &Some(m.clone())],
                )
                .await
                .map_err(|e| e.to_string())?;
            }
        }
    }
    Ok(())
}

async fn apply_tilegrid_cascade(
    c: &Client,
    pool: &DbPool,
    sess: &Session,
    tg: &Option<Box<TileGrid>>,
    skind_plain: SKind,
    skind_wmts: SKind,
) -> WResult<Option<i32>> {
    match tg {
        None => Ok(None),
        Some(t) => {
            if let Some(id) = t.id {
                let sk = if t.is_wmts { skind_wmts } else { skind_plain };
                if sess.contains(sk, id) {
                    return Err(format!(
                        "A different object with the same identifier value was already associated with the session"
                    ));
                }
                wipe_tilegrid(c, pool, sess, t).await?;
                Ok(Some(id))
            } else {
                let mut t2 = (**t).clone();
                insert_tilegrid(c, pool, &mut t2).await?;
                Ok(t2.id)
            }
        }
    }
}

