fn birthday_to_date(b: &Option<String>) -> Option<chrono::NaiveDate> {
    b.as_ref()
        .and_then(|s| chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d").ok())
}

pub async fn insert_user(c: &Client, pool: &DbPool, u: &mut User) -> WResult<()> {
    let id = alloc(pool).await?;
    u.id = Some(id);
    let t = now();
    c.execute(
        "INSERT INTO persons (id, created, modified, birthday, email, firstname, language, lastname)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
        &[
            &id,
            &t,
            &t,
            &birthday_to_date(&u.birthday),
            &u.email,
            &u.first_name,
            &u.language,
            &u.last_name,
        ],
    )
    .await
    .map_err(|e| e.to_string())?;
    c.execute(
        "INSERT INTO users (id, accountname, active, password) VALUES ($1,$2,$3,$4)",
        &[&id, &u.account_name, &u.active, &u.password],
    )
    .await
    .map_err(|e| e.to_string())?;
    for rid in require_ids_roles(&u.roles)? {
        c.execute(
            "INSERT INTO users_roles (user_id, role_id) VALUES ($1,$2)",
            &[&id, &rid],
        )
        .await
        .map_err(|e| e.to_string())?;
    }
    for gid in require_ids_groups(&u.user_groups)? {
        c.execute(
            "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1,$2)",
            &[&gid, &id],
        )
        .await
        .map_err(|e| e.to_string())?;
    }
    Ok(())
}

pub async fn update_user(c: &Client, u: &User) -> WResult<()> {
    let id = u.id.unwrap();
