pub async fn insert_layer(
    c: &Client,
    pool: &DbPool,
    wctx: &WCtx<'_>,
    l: &mut Layer,
) -> WResult<()> {
    let id = alloc(pool).await?;
    l.id = Some(id);
    let appearance_id = apply_appearance_cascade(c, pool, wctx.sess, &l.appearance).await?;
    if let (Some(a), Some(aid)) = (&mut l.appearance, appearance_id) {
        a.id = Some(aid);
    }
    let t = now();
    c.execute(
        "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7)",
        &[
            &id,
            &t,
            &t,
            &l.description,
            &l.name,
            &appearance_id,
            &None::<i32>,
        ],
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(())
}

pub async fn update_layer(
    c: &Client,
    pool: &DbPool,
    wctx: &WCtx<'_>,
    l: &mut Layer,
    flags: &LayerFlags,
) -> WResult<()> {
    let id = l.id.unwrap();
    let mut appearance_id = match &l.appearance {
        Some(a) => a.id,
        None => None,
    };
    if flags.appearance {
        appearance_id = apply_appearance_cascade(c, pool, wctx.sess, &l.appearance).await?;
        if let (Some(a), Some(aid)) = (&mut l.appearance, appearance_id) {
            a.id = Some(aid);
        }
    }
    let source_id = match &l.source {
        Some(s) => s.id,
        None => None,
    };
    c.execute(
        "UPDATE layers SET description=$2, name=$3, appearance_id=$4, source_id=$5, modified=$6
          WHERE id=$1",
        &[
            &id,
            &l.description,
            &l.name,
            &appearance_id,
            &source_id,
            &now(),
        ],
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(())
}

