    c.execute("DELETE FROM overviewmaps_layers WHERE layer_id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    c.execute("DELETE FROM layers WHERE id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    Ok(())
