pub async fn delete_appearance(c: &Client, id: i32) -> WResult<()> {
    delete_perm_rows(c, id).await?;
    c.execute(
        "DELETE FROM layerappearances_properties WHERE appearance_id=$1",
        &[&id],
    )
    .await
    .map_err(|e| e.to_string())?;
    c.execute("DELETE FROM layerappearances WHERE id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    Ok(())
}

pub async fn delete_datasource(c: &Client, id: i32, kind: DsKind) -> WResult<()> {
    delete_perm_rows(c, id).await?;
    match kind {
        DsKind::ImageWms => {
            c.execute("DELETE FROM imagewmslayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
        }
        DsKind::TileWms => {
            c.execute("DELETE FROM tilewmslayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
            c.execute("DELETE FROM imagewmslayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
        }
        DsKind::Wfs => {
            c.execute("DELETE FROM wfslayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
        }
        DsKind::Wmts => {
            c.execute(
                "DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id=$1",
                &[&id],
            )
            .await
            .map_err(|e| e.to_string())?;
            c.execute("DELETE FROM wmtslayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
        }
        DsKind::Xyz => {
            c.execute(
                "DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id=$1",
                &[&id],
            )
            .await
            .map_err(|e| e.to_string())?;
            c.execute("DELETE FROM xyzlayerdatasources WHERE id=$1", &[&id])
                .await
                .map_err(|e| e.to_string())?;
        }
    }
    c.execute("DELETE FROM layerdatasources WHERE id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    Ok(())
}

