// HTTP handlers reproducing AbstractRestController + the service layer
// (@PreAuthorize/@PostAuthorize/@PostFilter behaviour and status codes).

use crate::db::DbPool;
use crate::deser::*;
use crate::jval::*;
use crate::list::*;
use crate::load::*;
use crate::model::*;
use crate::perms::*;
use crate::write::*;
use axum::body::Body;
use axum::extract::{Path, Query, State};
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use std::sync::Arc;

#[derive(Clone)]
pub struct AppState {
    pub pool: DbPool,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    DataSources,
    Appearances,
}

impl Res {
    pub fn fields(self) -> &'static [(&'static str, FieldType)] {
        match self {
            Res::Users => USER_FIELDS,
            Res::Groups => GROUP_FIELDS,
            Res::Roles => ROLE_FIELDS,
            Res::Layers => LAYER_FIELDS,
            Res::DataSources => DS_FIELDS,
            Res::Appearances => APPEARANCE_FIELDS,
        }
    }
    pub fn column_of(self) -> fn(&str) -> Option<&'static str> {
        match self {
            Res::Users => user_column,
            Res::Groups => group_column,
            Res::Roles => role_column,
            Res::Layers => layer_column,
            Res::DataSources => ds_column,
            Res::Appearances => appearance_column,
        }
    }
}

// ---------------------------------------------------------------------------
// response helpers (mirror the original's ResponseEntity / Jetty responses)
// ---------------------------------------------------------------------------

pub fn json_response(status: StatusCode, jv: &JVal) -> Response {
    let body = to_json_string(jv);
    (
        status,
        [(header::CONTENT_TYPE, "application/json;charset=utf-8")],
        body,
    )
        .into_response()
}

pub fn empty(status: StatusCode) -> Response {
    (status, [(header::CONTENT_LENGTH, "0")], Vec::<u8>::new()).into_response()
}

fn html_error(status: StatusCode, reason: &str, extra_headers: Vec<(&'static str, &'static str)>) -> Response {
    let body = format!(
        "<html>\n<head>\n<meta http-equiv=\"Content-Type\" content=\"text/html;charset=utf-8\"/>\n<title>Error {} {}</title>\n</head>\n<body><h2>HTTP ERROR {} {}</h2></body>\n</html>\n",
        status.as_u16(),
        reason,
        status.as_u16(),
        reason
    );
    let mut headers = HeaderMap::new();
    headers.insert(
        header::CONTENT_TYPE,
        "text/html;charset=iso-8859-1".parse().unwrap(),
    );
    for (k, v) in extra_headers {
        headers.insert(header::HeaderName::from_static(k), v.parse().unwrap());
    }
    (status, headers, body).into_response()
}

pub fn unauthorized() -> Response {
    html_error(
        StatusCode::UNAUTHORIZED,
        "Unauthorized",
        vec![("www-authenticate", "Basic realm=\"SHOGun Realm\"")],
    )
}

pub fn forbidden() -> Response {
    html_error(StatusCode::FORBIDDEN, "Forbidden", vec![])
}

pub fn server_error() -> Response {
    html_error(
        StatusCode::INTERNAL_SERVER_ERROR,
        "Server Error",
        vec![],
    )
}

// ---------------------------------------------------------------------------
// authentication gate (URL level security of shogunref-context-security.xml)
// ---------------------------------------------------------------------------

pub async fn gate(state: &AppState, headers: &HeaderMap) -> Result<AuthUser, Response> {
    let h = headers
        .get(header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok());
    match authenticate(&state.pool, h).await {
        Err(AuthError::Unauthorized) => Err(unauthorized()),
        Err(AuthError::Forbidden) => Err(forbidden()),
        Ok(auth) => {
            if !auth.url_ok {
                Err(forbidden())
            } else {
                Ok(auth)
            }
        }
    }
}

fn parse_id(s: &str) -> Result<i32, Response> {
    let t = s.trim();
    // Java Integer conversion via Spring: strict integer syntax
    match t.parse::<i32>() {
        Ok(v) => Ok(v),
        Err(_) => Err(empty(StatusCode::BAD_REQUEST)),
    }
}

fn parse_query(raw: Option<&str>) -> Vec<(String, String)> {
    match raw {
        None => vec![],
        Some(q) => form_urlencoded::parse(q.as_bytes())
            .into_owned()
            .collect(),
    }
}

// ---------------------------------------------------------------------------
// permission evaluation dispatch
// ---------------------------------------------------------------------------

fn eval_read(res: Res, auth: &AuthUser, ej: &EntityJson) -> bool {
    match (res, ej) {
        (Res::Users, EntityJson::User(u)) => eval_user(auth, u, Perm::Read),
        (Res::Groups, EntityJson::Group(g)) => eval_group(auth, g, Perm::Read),
        (Res::Roles, EntityJson::Role(r)) => {
            eval_always_read(auth, &r.user_perms, &r.group_perms, Perm::Read)
        }
        (Res::Layers, EntityJson::Layer(l)) => {
            eval_default(auth, &l.user_perms, &l.group_perms, Perm::Read)
        }
        (Res::DataSources, EntityJson::Ds(d)) => {
            eval_always_read(auth, &d.user_perms, &d.group_perms, Perm::Read)
        }
        (Res::Appearances, EntityJson::Appearance(a)) => {
            eval_always_read(auth, &a.user_perms, &a.group_perms, Perm::Read)
        }
        _ => false,
    }
}

fn eval_perm(res: Res, auth: &AuthUser, ej: &EntityJson, p: Perm) -> bool {
    match (res, ej) {
        (Res::Users, EntityJson::User(u)) => eval_user(auth, u, p),
        (Res::Groups, EntityJson::Group(g)) => eval_group(auth, g, p),
        (Res::Roles, EntityJson::Role(r)) => {
            eval_always_read(auth, &r.user_perms, &r.group_perms, p)
        }
        (Res::Layers, EntityJson::Layer(l)) => {
            eval_default(auth, &l.user_perms, &l.group_perms, p)
        }
        (Res::DataSources, EntityJson::Ds(d)) => {
            eval_always_read(auth, &d.user_perms, &d.group_perms, p)
        }
        (Res::Appearances, EntityJson::Appearance(a)) => {
            eval_always_read(auth, &a.user_perms, &a.group_perms, p)
        }
        _ => false,
    }
}

pub enum EntityJson {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Ds(DataSource),
    Appearance(LayerAppearance),
}

impl EntityJson {
    pub fn to_json(&self) -> JVal {
        match self {
            EntityJson::User(u) => user_json(u),
            EntityJson::Group(g) => group_json(g),
            EntityJson::Role(r) => role_json(r),
            EntityJson::Layer(l) => layer_json(l),
            EntityJson::Ds(d) => datasource_json(d),
            EntityJson::Appearance(a) => appearance_json(a),
        }
    }
}

// ---------------------------------------------------------------------------
// GET list / filter
// ---------------------------------------------------------------------------

pub async fn handle_list_or_filter(
    state: State<Arc<AppState>>,
    res: Res,
    is_filter: bool,
    headers: HeaderMap,
    query: Option<String>,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let raw_query = query.unwrap_or_default();
    let params = parse_query(Some(&raw_query));

    let restrict = determine_restrict_fields(&params, res.fields());

    // The restricted projection query instantiates the entity class; the
    // abstract LayerDataSource cannot be instantiated -> 500 (as the original).
    if is_filter_or_list_with_restrict(res, &restrict) {
        return server_error();
    }

    let filters = if is_filter {
        let vals = valid_field_filters(&params, res.fields());
        to_field_filters(vals, res.column_of())
    } else {
        // findAll ignores all other query parameters
        vec![]
    };
    if is_filter && filters.is_empty() {
        // findBySimpleFilter with no valid fields returns an empty list
        return json_response(StatusCode::OK, &jarr(vec![]));
    }

    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };

    let restrict_slice: Option<Vec<String>> = restrict.clone();
    let result: Result<Vec<EntityJson>, String> = async {
        let rs = restrict_slice.as_deref();
        let out: Vec<EntityJson> = match res {
            Res::Users => list_users(&client, &filters, rs)
                .await?
                .into_iter()
                .map(EntityJson::User)
                .collect(),
            Res::Groups => list_groups(&client, &filters, rs)
                .await?
                .into_iter()
                .map(EntityJson::Group)
                .collect(),
            Res::Roles => list_roles(&client, &filters, rs)
                .await?
                .into_iter()
                .map(EntityJson::Role)
                .collect(),
            Res::Layers => list_layers(&client, &filters, rs)
                .await?
                .into_iter()
                .map(EntityJson::Layer)
                .collect(),
            Res::DataSources => list_ds(&client, &filters)
                .await?
                .into_iter()
                .map(EntityJson::Ds)
                .collect(),
            Res::Appearances => list_appearances(&client, &filters, rs)
                .await?
                .into_iter()
                .map(EntityJson::Appearance)
                .collect(),
        };
        Ok(out)
    }
    .await;

    let entities = match result {
        Ok(e) => e,
        Err(_) => return server_error(),
    };

    // @PostFilter READ
    let kept: Vec<JVal> = entities
        .iter()
        .filter(|e| eval_read(res, &auth, e))
        .map(|e| e.to_json())
        .collect();

    json_response(StatusCode::OK, &jarr(kept))
}

fn is_filter_or_list_with_restrict(res: Res, restrict: &Option<Vec<String>>) -> bool {
    res == Res::DataSources && restrict.is_some()
}

// ---------------------------------------------------------------------------
// GET /{id}
// ---------------------------------------------------------------------------

pub async fn handle_get_one(
    state: State<Arc<AppState>>,
    res: Res,
    headers: HeaderMap,
    id_str: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str) {
        Ok(i) => i,
        Err(r) => return r,
    };
    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    let mut sess = Session::default();
    let loaded = match load_entity(&client, res, id, &mut sess).await {
        Ok(Some(e)) => e,
        Ok(None) => return empty(StatusCode::NOT_FOUND),
        Err(_) => return empty(StatusCode::NOT_FOUND),
    };
    if !eval_read(res, &auth, &loaded) {
        return empty(StatusCode::NOT_FOUND);
    }
    json_response(StatusCode::OK, &loaded.to_json())
}

pub async fn load_entity(
    c: &tokio_postgres::Client,
    res: Res,
    id: i32,
    sess: &mut Session,
) -> Result<Option<EntityJson>, String> {
    match res {
        Res::Users => Ok(load_user(c, id, sess).await?.map(EntityJson::User)),
        Res::Groups => Ok(load_group(c, id, sess).await?.map(EntityJson::Group)),
        Res::Roles => Ok(load_role(c, id, sess).await?.map(EntityJson::Role)),
        Res::Layers => Ok(load_layer(c, id, sess).await?.map(EntityJson::Layer)),
        Res::DataSources => Ok(load_ds(c, id, sess).await?.map(EntityJson::Ds)),
        Res::Appearances => Ok(load_appearance(c, id, sess)
            .await?
            .map(EntityJson::Appearance)),
    }
}

// ---------------------------------------------------------------------------
// POST
// ---------------------------------------------------------------------------

pub async fn handle_post(
    state: State<Arc<AppState>>,
    res: Res,
    headers: HeaderMap,
    body: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };

    // the original cannot instantiate the abstract LayerDataSource from JSON
    if res == Res::DataSources {
        return empty(StatusCode::BAD_REQUEST);
    }

    let parsed = match parse_json(&body) {
        Ok(v) => v,
        Err(_) => return empty(StatusCode::BAD_REQUEST),
    };
    if !parsed.is_obj() {
        // readValue into an entity from a non-object -> error; "null" -> NPE
        return empty(StatusCode::BAD_REQUEST);
    }

    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    let mut sess = Session::default();

    let entity: EntityJson = {
        let mut ctx = Ctx {
            client: &client,
            auth: &auth,
            sess: &mut sess,
        };
        match build_entity(res, &parsed, &mut ctx).await {
            Ok(e) => e,
            Err(_) => return empty(StatusCode::BAD_REQUEST),
        }
    };

    // ID must be null for POST
    if entity_id(&entity).is_some() {
        return empty(StatusCode::BAD_REQUEST);
    }

    // @PreAuthorize CREATE on the (parsed, permission-less) entity
    if !eval_perm(res, &auth, &entity, Perm::Create) {
        return empty(StatusCode::BAD_REQUEST);
    }

    // save: allocate id(s) autonomously first (as Hibernate's table generator does)
    let mut entity = entity;
    let wctx = WCtx {
        pool: &state.pool,
        sess: &sess,
    };
    let write_result: WResult<()> = async {
        let tx = client.transaction().await.map_err(|e| e.to_string())?;
        match res {
            Res::Users => {
                if let EntityJson::User(u) = &mut entity {
                    insert_user(&tx, &state.pool, u).await?;
                }
            }
            Res::Groups => {
                if let EntityJson::Group(g) = &mut entity {
                    insert_group(&tx, &state.pool, g).await?;
                }
            }
            Res::Roles => {
                if let EntityJson::Role(r) = &mut entity {
                    insert_role(&tx, &state.pool, r).await?;
                }
            }
            Res::Layers => {
                if let EntityJson::Layer(l) = &mut entity {
                    insert_layer(&tx, &state.pool, &wctx, l).await?;
                }
            }
            Res::Appearances => {
                if let EntityJson::Appearance(a) = &mut entity {
                    insert_appearance(&tx, &state.pool, a).await?;
                }
            }
            Res::DataSources => unreachable!(),
        }
        tx.commit().await.map_err(|e| e.to_string())?;
        Ok(())
    }
    .await;

    if let Err(_) = write_result {
        return empty(StatusCode::BAD_REQUEST);
    }

    json_response(StatusCode::CREATED, &entity.to_json())
}

pub fn entity_id(e: &EntityJson) -> Option<i32> {
    match e {
        EntityJson::User(x) => x.id,
        EntityJson::Group(x) => x.id,
        EntityJson::Role(x) => x.id,
        EntityJson::Layer(x) => x.id,
        EntityJson::Ds(x) => x.id,
        EntityJson::Appearance(x) => x.id,
    }
}

async fn build_entity(res: Res, v: &JVal, ctx: &mut Ctx<'_>) -> Result<EntityJson, DError> {
    match res {
        Res::Users => {
            let mut u = User::new_parsed();
            apply_user(&mut u, v, ctx).await?;
            Ok(EntityJson::User(u))
        }
        Res::Groups => {
            let mut g = UserGroup::new_parsed();
            apply_group(&mut g, v, ctx).await?;
            Ok(EntityJson::Group(g))
        }
        Res::Roles => {
            let mut r = Role::new_parsed();
            apply_role(&mut r, v).await?;
            Ok(EntityJson::Role(r))
        }
        Res::Layers => {
            let mut l = Layer::new_parsed();
            apply_layer(&mut l, v, ctx).await?;
            Ok(EntityJson::Layer(l))
        }
        Res::DataSources => Err(DError("abstract LayerDataSource".into())),
        Res::Appearances => {
            let mut a = LayerAppearance::new_parsed();
            apply_appearance(&mut a, v).await?;
            Ok(EntityJson::Appearance(a))
        }
    }
}

// ---------------------------------------------------------------------------
// PUT /{id}
// ---------------------------------------------------------------------------

pub async fn handle_put(
    state: State<Arc<AppState>>,
    res: Res,
    headers: HeaderMap,
    id_str: String,
    body: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str) {
        Ok(i) => i,
        Err(r) => return r,
    };

    // readTree
    let parsed = match parse_json(&body) {
        Ok(v) => v,
        Err(_) => return empty(StatusCode::NOT_FOUND),
    };
    let id_node = parsed.get("id");
    match id_node {
        None => return empty(StatusCode::BAD_REQUEST),
        Some(n) => {
            if n.as_int() != id as i64 {
                return empty(StatusCode::BAD_REQUEST);
            }
        }
    }

    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    let mut sess = Session::default();

    // service.findById (@PostAuthorize READ)
    let mut entity = match load_entity(&client, res, id, &mut sess).await {
        Ok(Some(e)) => e,
        _ => return empty(StatusCode::NOT_FOUND),
    };
    if !eval_read(res, &auth, &entity) {
        return empty(StatusCode::NOT_FOUND);
    }
    // @PreAuthorize UPDATE
    if !eval_perm(res, &auth, &entity, Perm::Update) {
        return empty(StatusCode::NOT_FOUND);
    }

    // merge (objectMapper.readerForUpdating)
    let mut layer_flags = LayerFlags { appearance: false };
    let mut ds_flags = DsFlags { tile_grid: false };
    {
        let mut ctx = Ctx {
            client: &client,
            auth: &auth,
            sess: &mut sess,
        };
        let merge_result = match (&mut entity, res) {
            (EntityJson::User(u), _) => apply_user(u, &parsed, &mut ctx).await,
            (EntityJson::Group(g), _) => apply_group(g, &parsed, &mut ctx).await,
            (EntityJson::Role(r), _) => apply_role(r, &parsed).await,
            (EntityJson::Layer(l), _) => {
                layer_flags.appearance = parsed.get("appearance").is_some();
                apply_layer(l, &parsed, &mut ctx).await
            }
            (EntityJson::Ds(d), _) => {
                ds_flags.tile_grid = parsed.get("tileGrid").is_some();
                apply_datasource(d, &parsed, &mut ctx).await
            }
            (EntityJson::Appearance(a), _) => apply_appearance(a, &parsed).await,
        };
        if let Err(_) = merge_result {
            return empty(StatusCode::NOT_FOUND);
        }
    }

    // save (flush); the id in the body equals the entity id
    let wctx = WCtx {
        pool: &state.pool,
        sess: &sess,
    };
    let write_result: WResult<()> = async {
        let tx = client.transaction().await.map_err(|e| e.to_string())?;
        match (&mut entity, res) {
            (EntityJson::User(u), _) => update_user(&tx, u).await?,
            (EntityJson::Group(g), _) => update_group(&tx, g).await?,
            (EntityJson::Role(r), _) => update_role(&tx, r).await?,
            (EntityJson::Layer(l), _) => update_layer(&tx, &state.pool, &wctx, l, &layer_flags).await?,
            (EntityJson::Ds(d), _) => {
                update_datasource(&tx, &state.pool, &wctx, d, &ds_flags).await?
            }
            (EntityJson::Appearance(a), _) => update_appearance(&tx, a).await?,
        }
        tx.commit().await.map_err(|e| e.to_string())?;
        Ok(())
    }
    .await;

    if let Err(_) = write_result {
        return empty(StatusCode::NOT_FOUND);
    }

    json_response(StatusCode::OK, &entity.to_json())
}

// ---------------------------------------------------------------------------
// DELETE /{id}
// ---------------------------------------------------------------------------

pub async fn handle_delete(
    state: State<Arc<AppState>>,
    res: Res,
    headers: HeaderMap,
    id_str: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str) {
        Ok(i) => i,
        Err(r) => return r,
    };
    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    let mut sess = Session::default();
    let entity = match load_entity(&client, res, id, &mut sess).await {
        Ok(Some(e)) => e,
        _ => return empty(StatusCode::NOT_FOUND),
    };
    // findById @PostAuthorize READ, then delete @PreAuthorize DELETE
    if !eval_read(res, &auth, &entity) {
        return empty(StatusCode::NOT_FOUND);
    }
    if !eval_perm(res, &auth, &entity, Perm::Delete) {
        return empty(StatusCode::NOT_FOUND);
    }
    let kind = match &entity {
        EntityJson::Ds(d) => Some(d.kind),
        _ => None,
    };
    let result: WResult<()> = async {
        let tx = client.transaction().await.map_err(|e| e.to_string())?;
        match res {
            Res::Users => delete_user(&tx, id).await?,
            Res::Groups => delete_group(&tx, id).await?,
            Res::Roles => delete_role(&tx, id).await?,
            Res::Layers => delete_layer(&tx, id).await?,
            Res::Appearances => delete_appearance(&tx, id).await?,
            Res::DataSources => {
                delete_datasource(&tx, id, kind.unwrap_or(DsKind::ImageWms)).await?
            }
        }
        tx.commit().await.map_err(|e| e.to_string())?;
        Ok(())
    }
    .await;
    match result {
        Ok(()) => empty(StatusCode::NO_CONTENT),
        Err(_) => empty(StatusCode::NOT_FOUND),
    }
}

// ---------------------------------------------------------------------------
// GET /users/{id}/userGroups and /groups/{id}/users
// ---------------------------------------------------------------------------

pub async fn handle_user_groups(
    state: State<Arc<AppState>>,
    headers: HeaderMap,
    id_str: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str) {
        Ok(i) => i,
        Err(r) => return r,
    };
    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    // getGroupsOfUser: findById is a self-invocation (no READ check on the user)
    let rows = match client
        .query(
            "SELECT usergroup_id FROM user_usergroup WHERE user_id = $1",
            &[&id],
        )
        .await
    {
        Ok(r) => r,
        Err(_) => return server_error(),
    };
    let exists = client
        .query_opt("SELECT id FROM users WHERE id=$1", &[&id])
        .await;
    match exists {
        Ok(Some(_)) => {}
        _ => return empty(StatusCode::NOT_FOUND),
    }
    let mut sess = Session::default();
    let mut out = Vec::new();
    for r in rows {
        let gid: i32 = r.get(0);
        match load_group(&client, gid, &mut sess).await {
            Ok(Some(g)) => {
                if eval_group(&auth, &g, Perm::Read) {
                    out.push(group_json(&g));
                }
            }
            _ => return server_error(),
        }
    }
    json_response(StatusCode::OK, &jarr(out))
}

pub async fn handle_group_users(
    state: State<Arc<AppState>>,
    headers: HeaderMap,
    id_str: String,
) -> Response {
    let auth = match gate(&state, &headers).await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str) {
        Ok(i) => i,
        Err(r) => return r,
    };
    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error(),
    };
    let mut sess = Session::default();
    let g = match load_group(&client, id, &mut sess).await {
        Ok(Some(g)) => g,
        Ok(None) => return empty(StatusCode::NOT_FOUND),
        Err(_) => return server_error(),
    };
    let mut out = Vec::new();
    if let Some(members) = &g.members {
        for m in members {
            if eval_user(&auth, m, Perm::Read) {
                out.push(user_json(m));
            }
        }
    }
    json_response(StatusCode::OK, &jarr(out))
}

