/// Spring MVC matches a single trailing slash; normalise it.
async fn trailing_slash(mut req: Request, next: Next) -> Response {
    let path = req.uri().path().to_string();
    if path.len() > 1 && path.ends_with('/') {
        let trimmed = path.trim_end_matches('/');
        let trimmed = if trimmed.is_empty() { "/" } else { trimmed };
        let mut parts = req.uri().clone().into_parts();
        let new_pq = match parts.path_and_query.as_ref() {
            Some(pq) => match pq.query() {
                Some(q) => format!("{}?{}", trimmed, q),
                None => trimmed.to_string(),
            },
            None => trimmed.to_string(),
        };
        eprintln!("trailing_slash: {:?} -> {:?}", path, new_pq);
        if let Ok(pq) = new_pq.parse::<axum::http::uri::PathAndQuery>() {
            parts.path_and_query = Some(pq);
            match axum::http::Uri::from_parts(parts) {
                Ok(uri) => {
                    *req.uri_mut() = uri;
                    eprintln!("rewritten to {:?}", req.uri());
                }
                Err(e) => eprintln!("uri parts error: {}", e),
            }
        }
    }
    next.run(req).await
}

