use crate::handlers::*;
use axum::extract::{RawQuery, State};
use axum::routing::{get, MethodRouter};
use axum::Router;
use std::sync::Arc;

type ARc = Arc<AppState>;

fn both(app: Router, path: &str, mr: MethodRouter<ARc>) -> Router {
    // Spring MVC also matches a single trailing slash
    let with_slash = format!("{}/", path);
    app.route(path, mr.clone()).route(&with_slash, mr)
}

pub fn build_router(state: Arc<AppState>) -> Router {
    let mut app = Router::new();

    for (base, res) in [
        ("/rest/users", Res::Users),
        ("/rest/groups", Res::Groups),
        ("/rest/roles", Res::Roles),
        ("/rest/layers", Res::Layers),
        ("/rest/layerdatasources", Res::DataSources),
        ("/rest/layerappearances", Res::Appearances),
    ] {
        app = both(
            app,
            base,
            get(
                move |st: State<ARc>, h: axum::http::HeaderMap, RawQuery(q): RawQuery| async move {
                    handle_list_or_filter(st, res, false, h, q).await
                },
            )
            .post(move |st: State<ARc>, h: axum::http::HeaderMap, b: String| async move {
                handle_post(st, res, h, b).await
            }),
        );

        let filter_path = format!("{}/filter", base);
        app = both(
            app,
            &filter_path,
            get(
                move |st: State<ARc>, h: axum::http::HeaderMap, RawQuery(q): RawQuery| async move {
                    handle_list_or_filter(st, res, true, h, q).await
                },
            ),
        );

        let id_path = format!("{}/{{id}}", base);
        app = both(
            app,
            &id_path,
            get(
                move |st: State<ARc>,
                      h: axum::http::HeaderMap,
                      p: axum::extract::Path<String>| async move {
                    handle_get_one(st, res, h, p.0).await
                },
            )
            .put(
                move |st: State<ARc>,
                      h: axum::http::HeaderMap,
                      p: axum::extract::Path<String>,
                      b: String| async move {
                    handle_put(st, res, h, p.0, b).await
                },
            )
            .delete(
                move |st: State<ARc>,
                      h: axum::http::HeaderMap,
                      p: axum::extract::Path<String>| async move {
                    handle_delete(st, res, h, p.0).await
                },
            ),
        );
    }

    app = both(
        app,
        "/rest/users/{id}/userGroups",
        get(|st: State<ARc>,
            h: axum::http::HeaderMap,
            p: axum::extract::Path<String>| async move {
            handle_user_groups(st, h, p.0).await
        }),
    );
    app = both(
        app,
        "/rest/groups/{id}/users",
        get(|st: State<ARc>,
            h: axum::http::HeaderMap,
            p: axum::extract::Path<String>| async move {
            handle_group_users(st, h, p.0).await
        }),
    );

    app.with_state(state)
}

