pub async fn handle_group_users(
    state: State<Arc<AppState>>,
    headers: HeaderMap,
    id_str: String,
) -> Response {
    let auth = match gate(&state, &headers, "GET").await {
        Ok(a) => a,
        Err(r) => return r,
    };
    let id = match parse_id(&id_str, "GET") {
        Ok(i) => i,
        Err(r) => return r,
    };
    let client = match state.pool.get().await {
        Ok(c) => c,
        Err(_) => return server_error("GET"),
    };
    let mut sess = Session::default();
    let g = match load_group(&client, id, &mut sess).await {
        Ok(Some(g)) => g,
        _ => return empty(StatusCode::NOT_FOUND),
    };
    let mut out = Vec::new();
    if let Some(members) = &g.members {
        for m in members {
            if eval_user(&auth, m, Perm::Read) {
                out.push(user_json(m));
            }
        }
    }
    json_response(StatusCode::OK, &jarr(out))
}

/// Unmapped paths: /rest/** goes through the REST security chain first
/// (ROLE_USER for the six resources, ROLE_ADMIN for anything else), then 404.
pub async fn handle_fallback(
    state: State<Arc<AppState>>,
    headers: HeaderMap,
    method: axum::http::Method,
    uri: axum::http::Uri,
) -> Response {
    let m = method.as_str();
    let path = uri.path();
    if path.starts_with("/rest") {
        const USER_PREFIXES: [&str; 6] = [
            "/rest/users",
            "/rest/groups",
            "/rest/roles",
            "/rest/layers",
            "/rest/layerdatasources",
            "/rest/layerappearances",
        ];
        let auth = match gate(&state, &headers, m).await {
            Ok(a) => a,
            Err(r) => return r,
        };
        let user_prefix = USER_PREFIXES.iter().any(|p| path.starts_with(p));
        if !user_prefix && !auth.is_admin {
            return forbidden(m);
        }
    }
    container_error(StatusCode::NOT_FOUND, "Not Found", m, vec![])
}

