/// cascade SAVE_UPDATE handling for TileGrid.tileGridExtent (mutates in place
/// so created ids appear in the response echo, like Hibernate does)
async fn apply_extent_cascade(
    c: &deadpool_postgres::Client,
    pool: &DbPool,
    sess: &Session,
    ext: &mut Option<Box<Extent>>,
) -> WResult<Option<i32>> {
    match ext.as_mut() {
        None => Ok(None),
        Some(e) => {
            if let Some(id) = e.id {
                if sess.contains(SKind::Extent, id) {
                    return Err(format!(
                        "A different object with the same identifier value was already associated with the session : [Extent#{}]",
                        id
                    ));
                }
                wipe_extent(c, e).await?;
                Ok(Some(id))
            } else {
                insert_extent(c, pool, e).await?;
                Ok(e.id)
            }
        }
    }
}

