async fn insert_tilegrid(
    c: &deadpool_postgres::Client,
    pool: &DbPool,
    sess: &Session,
    t: &mut TileGrid,
) -> WResult<()> {
    let id = alloc(pool).await?;
    t.id = Some(id);
    let extent_id = apply_extent_cascade(c, pool, sess, &mut t.extent).await?;
    let tm = now();
    let (ox, oy) = match t.origin {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    c.execute(
        "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
        &[&id, &tm, &tm, &ox, &oy, &t.tile_size, &t.type_, &extent_id],
    )
    .await
    .map_err(|e| e.to_string())?;
    if t.is_wmts {
        c.execute("INSERT INTO wmtstilegrids (id) VALUES ($1)", &[&id])
            .await
            .map_err(|e| e.to_string())?;
        if let Some(ms) = &t.matrix_ids {
            for m in ms {
                c.execute(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1,$2)",
                    &[&id, &Some(m.clone())],
                )
                .await
                .map_err(|e| e.to_string())?;
            }
        }
    }
    if let Some(rs) = &t.resolutions {
        for (i, r) in rs.iter().enumerate() {
            c.execute(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, &Some(*r), &(i as i32)],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

async fn wipe_tilegrid(
    c: &deadpool_postgres::Client,
    pool: &DbPool,
    sess: &Session,
    t: &mut TileGrid,
) -> WResult<()> {
    let id = t.id.unwrap();
    // the row must exist; a re-attached instance is updated with its own
    // (mostly null) field values, wiping the row
    let row = c
        .query_opt(
            "SELECT (SELECT count(*) FROM wmtstilegrids w WHERE w.id = t.id) > 0 FROM tilegrids t WHERE t.id=$1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
    let row_is_wmts = match row {
        None => {
            return Err(format!(
                "No row with the given identifier exists: [TileGrid#{}]",
                id
            ))
        }
        Some(r) => r.get::<_, bool>(0),
    };
    if t.is_wmts && !row_is_wmts {
        // subclass row missing -> unexpected row count on flush
        return Err(format!(
            "Batch update returned unexpected row count: [wmtstilegrids {}]",
            id
        ));
    }
    let extent_id = apply_extent_cascade(c, pool, sess, &mut t.extent).await?;
    let (ox, oy) = match t.origin {
        Some((x, y)) => (Some(x), Some(y)),
        None => (None, None),
    };
    c.execute(
        "UPDATE tilegrids SET tilegridorigin_x=$2, tilegridorigin_y=$3, tilesize=$4, type=$5,
                tilegridextent_id=$6, modified=$7 WHERE id=$1",
        &[&id, &ox, &oy, &t.tile_size, &t.type_, &extent_id, &now()],
    )
    .await
    .map_err(|e| e.to_string())?;
    c.execute("DELETE FROM tilegrid_resolution WHERE tilegrid_id=$1", &[&id])
        .await
        .map_err(|e| e.to_string())?;
    if let Some(rs) = &t.resolutions {
        for (i, r) in rs.iter().enumerate() {
            c.execute(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, &Some(*r), &(i as i32)],
            )
            .await
            .map_err(|e| e.to_string())?;
        }
    }
    if t.is_wmts {
        c.execute(
            "DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id=$1",
            &[&id],
        )
        .await
        .map_err(|e| e.to_string())?;
        if let Some(ms) = &t.matrix_ids {
            for m in ms {
                c.execute(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1,$2)",
                    &[&id, &Some(m.clone())],
                )
                .await
                .map_err(|e| e.to_string())?;
            }
        }
    }
    Ok(())
}

async fn apply_tilegrid_cascade(
    c: &deadpool_postgres::Client,
    pool: &DbPool,
    sess: &Session,
    tg: &mut Option<Box<TileGrid>>,
) -> WResult<Option<i32>> {
    match tg.as_mut() {
        None => Ok(None),
        Some(t) => {
            if let Some(id) = t.id {
                let sk = if t.is_wmts {
                    SKind::WmtsTileGrid
                } else {
                    SKind::TileGrid
                };
                if sess.contains(sk, id) {
                    return Err(format!(
                        "A different object with the same identifier value was already associated with the session : [TileGrid#{}]",
                        id
                    ));
                }
                wipe_tilegrid(c, pool, sess, t).await?;
                Ok(Some(id))
            } else {
                insert_tilegrid(c, pool, sess, t).await?;
                Ok(t.id)
            }
        }
    }
}

