    // tileGrid conflict (same id as currently loaded) -> 404
    assert_eq!(send("PUT", "/rest/layerdatasources/12", Some(ADMIN), Some("{\"id\":12,\"tileGrid\":{\"id\":11}}")).await.status, 404);
    // tileGrid null clears FK
    assert_eq!(send("PUT", "/rest/layerdatasources/12", Some(ADMIN), Some("{\"id\":12,\"tileGrid\":null}")).await.status, 200);
    assert!(query_rows("SELECT tilegrid_id FROM tilewmslayerdatasources WHERE id=12").await == vec!["NULL".to_string()]);
    // new tileGrid via cascade (constructor default tileSize=256)
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("PUT", "/rest/layerdatasources/12", Some(ADMIN), Some(
        "{\"id\":12,\"tileGrid\":{\"type\":\"TileGrid\",\"tileGridResolutions\":[4.0,2.0]}}")).await;
    assert_eq!(r.status, 200);
    let tgid = r.json()["tileGrid"]["id"].as_i64().unwrap();
    assert_eq!(tgid, before + 1);
    assert_eq!(r.json()["tileGrid"]["tileSize"], 256);
    let rows = query_rows(&format!("SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id={} ORDER BY idx", tgid)).await;
    assert_eq!(rows, vec!["4".to_string(), "2".to_string()]);

    // WMTS urls replace
    let r = send("PUT", "/rest/layerdatasources/1003", Some(ADMIN), Some(
        "{\"id\":1003,\"urls\":[\"http://a\",\"http://b\",\"http://c\"]}")).await;
    assert_eq!(r.status, 200);
    let rows = query_rows("SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id=1003 ORDER BY 1").await;
    assert_eq!(rows, vec!["http://a".to_string(), "http://b".to_string(), "http://c".to_string()]);

    // WMTS new tileGrid with nested extent cascade; ids echo in the response
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("PUT", "/rest/layerdatasources/1003", Some(ADMIN), Some(
        "{\"id\":1003,\"tileGrid\":{\"type\":\"WMTS\",\"tileSize\":256,\"matrixIds\":[\"a\",\"b\"],\"tileGridResolutions\":[1.0,2.5],\"tileGridExtent\":{\"lowerLeft\":{\"x\":1,\"y\":2},\"upperRight\":{\"x\":3,\"y\":4}}}}")).await;
    assert_eq!(r.status, 200);
    let tg = &r.json()["tileGrid"];
    assert_eq!(tg["id"].as_i64().unwrap(), before + 1);
    assert_eq!(tg["tileGridExtent"]["id"].as_i64().unwrap(), before + 2);
    assert_eq!(tg["matrixIds"], serde_json::json!(["a", "b"]));

    // XYZ updates
    let r = send("PUT", "/rest/layerdatasources/1004", Some(ADMIN), Some(
        "{\"id\":1004,\"center\":{\"x\":9,\"y\":8},\"tileSize\":512,\"extent\":{\"id\":1011}}")).await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["center"], serde_json::json!({"x": 9.0, "y": 8.0}));
    let rows = query_rows("SELECT center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources WHERE id=1004").await;
    assert_eq!(rows, vec!["9|8|512|1011".to_string()]);
    // transient extent (no id) -> 404
    assert_eq!(send("PUT", "/rest/layerdatasources/1004", Some(ADMIN), Some(
        "{\"id\":1004,\"extent\":{\"lowerLeft\":{\"x\":0,\"y\":0}}}")).await.status, 404);

    // deletes: unreferenced ok, referenced -> 404
    assert_eq!(send("DELETE", "/rest/layerdatasources/1001", Some(ADMIN), None).await.status, 204);
    assert!(query_rows("SELECT id FROM imagewmslayerdatasources WHERE id=1001").await.is_empty());
    assert!(query_rows("SELECT id FROM layerdatasources WHERE id=1001").await.is_empty());
    assert_eq!(send("DELETE", "/rest/layerdatasources/13", Some(ADMIN), None).await.status, 404); // layer 16? (deleted in t09 maybe) or 13 referenced
    // non-admin lacks DELETE -> 404
    assert_eq!(send("DELETE", "/rest/layerdatasources/1002", Some(USER), None).await.status, 404);

    // restore tilegrid for ds 12 so other tests see consistent data
    let _ = send("PUT", "/rest/layerdatasources/12", Some(ADMIN), Some("{\"id\":12,\"tileGrid\":{\"id\":11}}")).await;
}

#[tokio::test]
async fn t11_fallbacks_and_methods() {
    let _g = lock();
    seed().await;

    // unknown /rest path: admin -> 404, plain user -> 403 on non-slice paths
    assert_eq!(send("GET", "/rest/unknown", Some(ADMIN), None).await.status, 404);
    assert_eq!(send("GET", "/rest/unknown", Some(USER), None).await.status, 403);
    assert_eq!(send("GET", "/rest/unknown", None, None).await.status, 401);
    // unknown deeper path under a slice prefix -> 404 (ROLE_USER suffices)
    assert_eq!(send("GET", "/rest/users/4/nope", Some(USER), None).await.status, 404);
}
