// Integration tests that run the router in-process (tower oneshot) against
// DATABASE_URL. They seed a demo-data set equivalent to the original's
// ContentInitializer and verify the behaviour ported from shogun-core.

use axum::body::Body;
use axum::http::{header, Request, StatusCode};
use http_body_util::BodyExt;
use shogun_rust::app::build_router;
use shogun_rust::db::create_pool;
use shogun_rust::handlers::AppState;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, MutexGuard, OnceLock};
use tokio_postgres::types::Type;
use tower::util::ServiceExt;

static SEEDED: AtomicBool = AtomicBool::new(false);
static LOCK: Mutex<()> = Mutex::new(());

fn lock() -> MutexGuard<'static, ()> {
    LOCK.lock().unwrap_or_else(|e| e.into_inner())
}

fn env() -> Arc<AppState> {
    static ENV: OnceLock<Arc<AppState>> = OnceLock::new();
    ENV.get_or_init(|| {
        let url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set for tests");
        let pool = create_pool(&url).expect("pool");
        Arc::new(AppState { pool })
    })
    .clone()
}

fn router() -> axum::Router {
    build_router(env())
}

async fn sql(query: &str) {
    let c = env().pool.get().await.unwrap();
    c.execute(query, &[])
        .await
        .unwrap_or_else(|e| panic!("SQL failed: {}\nquery: {}", e, query));
}

fn cell(row: &tokio_postgres::Row, i: usize) -> String {
    let t = row.columns()[i].type();
    fn fmt<T: std::fmt::Display>(v: Option<T>) -> String {
        match v {
            Some(x) => x.to_string(),
            None => "NULL".to_string(),
        }
    }
    match *t {
        Type::TEXT | Type::VARCHAR | Type::NAME | Type::BPCHAR | Type::UNKNOWN => {
            fmt(row.get::<_, Option<String>>(i))
        }
        Type::INT4 => fmt(row.get::<_, Option<i32>>(i)),
        Type::INT8 => fmt(row.get::<_, Option<i64>>(i)),
        Type::BOOL => fmt(row.get::<_, Option<bool>>(i)),
        Type::FLOAT8 => fmt(row.get::<_, Option<f64>>(i)),
        Type::DATE => fmt(row.get::<_, Option<chrono::NaiveDate>>(i)),
        Type::TIMESTAMP => fmt(row.get::<_, Option<chrono::NaiveDateTime>>(i)),
        _ => panic!("unsupported column type {} in test query", t),
    }
}

async fn query_rows(query: &str) -> Vec<String> {
    let c = env().pool.get().await.unwrap();
    let rows = c.query(query, &[]).await.expect("query");
    let mut out = Vec::new();
    for r in &rows {
        let mut line = Vec::new();
        for i in 0..r.len() {
            line.push(cell(r, i));
        }
        out.push(line.join("|"));
    }
    out.sort();
    out
}

async fn scalar_i64(query: &str) -> i64 {
    let c = env().pool.get().await.unwrap();
    let row = c.query_one(query, &[]).await.expect("scalar query");
    row.get(0)
}

fn basic(user: &str, pass: &str) -> String {
    use base64::Engine;
    format!(
        "Basic {}",
        base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", user, pass))
    )
}

pub struct Resp {
    pub status: StatusCode,
    pub body: String,
    pub www_auth: Option<String>,
    pub content_type: Option<String>,
}

impl Resp {
    pub fn json(&self) -> serde_json::Value {
        serde_json::from_str(&self.body).unwrap_or_else(|e| {
            panic!("not json ({}): {:?} body={}", e, self.status, self.body)
        })
    }
}

async fn send(method: &str, uri: &str, auth: Option<(&str, &str)>, body: Option<&str>) -> Resp {
    let mut builder = Request::builder().method(method).uri(uri);
    if let Some((u, p)) = auth {
        builder = builder.header(header::AUTHORIZATION, basic(u, p));
    }
    if body.is_some() {
        builder = builder.header(header::CONTENT_TYPE, "application/json");
    }
    let req = builder.body(Body::from(body.unwrap_or("").to_string())).unwrap();
    let resp = router().oneshot(req).await.unwrap();
    let status = resp.status();
    let www_auth = resp
        .headers()
        .get("www-authenticate")
        .map(|v| v.to_str().unwrap().to_string());
    let content_type = resp
        .headers()
        .get(header::CONTENT_TYPE)
        .map(|v| v.to_str().unwrap().to_string());
    let bytes = resp.into_body().collect().await.unwrap().to_bytes();
    Resp {
        status,
        body: String::from_utf8_lossy(&bytes).to_string(),
        www_auth,
        content_type,
    }
}

