#[tokio::test]
async fn t01_auth() {
    let _g = lock();
    seed().await;

    let r = send("GET", "/rest/users", None, None).await;
    assert_eq!(r.status, 401);
    assert_eq!(r.www_auth.as_deref(), Some("Basic realm=\"SHOGun Realm\""));

    assert_eq!(send("GET", "/rest/users", Some(("admin", "wrong")), None).await.status, 401);
    assert_eq!(send("GET", "/rest/users", Some(("nobody", "x")), None).await.status, 401);
    assert_eq!(send("GET", "/rest/users", Some(("inactive", "shogun")), None).await.status, 401);
    assert_eq!(send("GET", "/rest/users", Some(("roleless", "shogun")), None).await.status, 401);
    for p in ["/rest/users", "/rest/roles", "/rest/layers"] {
        assert_eq!(
            send("GET", p, Some(("foo", "shogun")), None).await.status,
            403,
            "{}",
            p
        );
    }
    assert_eq!(send("GET", "/rest/roles", Some(ADMIN), None).await.status, 200);
    assert_eq!(send("GET", "/rest/roles", Some(USER), None).await.status, 200);

    let req = Request::builder()
        .uri("/rest/roles")
        .header(header::AUTHORIZATION, "Basic !!!not-base64!!!")
        .body(Body::empty())
        .unwrap();
    let resp = router().oneshot(req).await.unwrap();
    assert_eq!(resp.status(), 401);
}

#[tokio::test]
async fn t02_lists() {
    let _g = lock();
    seed().await;

    let r = send("GET", "/rest/users", Some(ADMIN), None).await;
    assert_eq!(r.status, 200);
    assert_eq!(r.content_type.as_deref(), Some("application/json;charset=utf-8"));
    let v = r.json();
    let admin = v.as_array().unwrap().iter().find(|u| u["id"] == 3).unwrap();
    assert_eq!(admin["accountName"], "admin");
    assert_eq!(admin["firstName"], "Admins first name");
    assert_eq!(admin["active"], true);
    assert!(admin.get("password").is_none(), "password is write-only");
    assert!(admin.get("created").is_none());
    assert_eq!(admin["roles"][0]["name"], "ROLE_ADMIN");
    assert_eq!(admin["userGroups"], serde_json::json!([5]));
    assert_eq!(admin["email"], serde_json::Value::Null);

    // non-admin sees only itself
    let v = send("GET", "/rest/users", Some(USER), None).await.json();
    assert_eq!(v.as_array().unwrap().len(), 1);
    assert_eq!(v[0]["id"], 4);

    // groups: member only
    let v = send("GET", "/rest/groups", Some(USER), None).await.json();
    assert_eq!(v.as_array().unwrap().len(), 1);
    let g = &v[0];
    assert_eq!(g["id"], 6);
    assert_eq!(g["owner"]["accountName"], "admin");
    assert_eq!(g["owner"]["userGroups"], serde_json::json!([5]));
    assert!(g["members"].as_array().unwrap().iter().any(|m| m["id"] == 4));
    assert_eq!(g["roles"][0]["name"], "ROLE_USER");

    // roles readable by everyone
    let v = send("GET", "/rest/roles", Some(USER), None).await.json();
    assert_eq!(v.as_array().unwrap().len(), 3);

    // layers: user has READ on 15 (user perm) and 16 (group perm)
    let v = send("GET", "/rest/layers", Some(USER), None).await.json();
    let ids: Vec<i64> = v.as_array().unwrap().iter().map(|l| l["id"].as_i64().unwrap()).collect();
    assert_eq!(ids, vec![15, 16]);

    let v = send("GET", "/rest/layers", Some(ADMIN), None).await.json();
    assert_eq!(v.as_array().unwrap().len(), 2);
    let l = v.as_array().unwrap().iter().find(|l| l["id"] == 15).unwrap();
    assert_eq!(l["name"], "OSM-WMS");
    assert_eq!(l["source"]["type"], "TileWMS");
    assert_eq!(l["source"]["tileGrid"]["tileSize"], 256);
    assert_eq!(l["source"]["requestWithTiled"], true);
    assert_eq!(l["appearance"]["opacity"], 1.0);
    assert_eq!(l["appearance"]["properties"], serde_json::json!({}));

    // datasources readable by everyone
    let v = send("GET", "/rest/layerdatasources", Some(USER), None).await.json();
    assert_eq!(v.as_array().unwrap().len(), 10);

    // java double formatting (scientific notation like Double.toString)
    let raw = send("GET", "/rest/layers/15", Some(ADMIN), None).await.body;
    assert!(raw.contains("-2.002637639E7"), "body: {}", raw);
    assert!(raw.contains("156543.03390625"));
}

#[tokio::test]
async fn t03_subtype_shapes() {
    let _g = lock();
    seed().await;

    let v = send("GET", "/rest/layerdatasources/1001", Some(ADMIN), None).await.json();
    assert_eq!(
        v,
