            "id": 1001, "name": "imgwms-name", "type": "ImageWMS", "url": "http://img/",
            "format": "image/png", "width": 512, "height": 256, "version": "1.3.0",
            "layerNames": "a,b", "layerStyles": "s1", "requestableByPath": true,
            "customRequestPath": "/custom"
        })
    );

    let v = send("GET", "/rest/layerdatasources/1002", Some(ADMIN), None).await.json();
    assert_eq!(
        v,
        serde_json::json!({
            "id": 1002, "name": "wfs-name", "type": "WFS", "url": "http://wfs/",
            "format": "application/json", "version": "2.0.0", "typeName": "ns:feat",
            "typeNames": "ns:f1,ns:f2"
        })
    );

    let v = send("GET", "/rest/layerdatasources/1003", Some(ADMIN), None).await.json();
    assert_eq!(v["wmtsLayer"], "wlayer");
    assert_eq!(v["tileGrid"]["matrixIds"], serde_json::json!(["0", "1"]));
    assert_eq!(v["tileGrid"]["tileGridExtent"]["lowerLeft"]["x"], 0.0);
    assert_eq!(v["urls"].as_array().unwrap().len(), 2);

    let v = send("GET", "/rest/layerdatasources/1004", Some(ADMIN), None).await.json();
