#[tokio::test]
async fn t06_crud_roles() {
    let _g = lock();
    seed().await;

    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("POST", "/rest/roles", Some(ADMIN), Some("{\"name\":\"T_ROLE\",\"description\":\"d\"}")).await;
    assert_eq!(r.status, 201);
    let v = r.json();
    let id = v["id"].as_i64().unwrap();
    assert_eq!(id, before + 1);
    assert_eq!(v["name"], "T_ROLE");
    assert_eq!(scalar_i64("SELECT next_val FROM hibernate_sequences").await, id);

    // denied / bad requests, no id consumption
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    assert_eq!(send("POST", "/rest/roles", Some(USER), Some("{\"name\":\"X\"}")).await.status, 400);
    assert_eq!(
        send("POST", "/rest/roles", Some(ADMIN), Some(&format!("{{\"id\":{},\"name\":\"Y\"}}", id + 100)))
            .await
            .status,
        400
    );
    assert_eq!(send("POST", "/rest/roles", Some(ADMIN), Some("{\"name\":\"Y\",\"zz\":1}")).await.status, 400);
    assert_eq!(send("POST", "/rest/roles", Some(ADMIN), Some("{")).await.status, 400);
    assert_eq!(send("POST", "/rest/roles", Some(ADMIN), Some("")).await.status, 400);
    assert_eq!(send("POST", "/rest/roles", Some(ADMIN), Some("[1,2]")).await.status, 400);
    assert_eq!(scalar_i64("SELECT next_val FROM hibernate_sequences").await, before);

    // PUT partial merge
    let r = send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some(&format!("{{\"id\":{},\"description\":\"upd\"}}", id)))
        .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["name"], "T_ROLE");
    assert_eq!(r.json()["description"], "upd");
    let rows = query_rows(&format!("SELECT name, description FROM roles WHERE id={}", id)).await;
    assert_eq!(rows, vec!["T_ROLE|upd".to_string()]);

    assert_eq!(
        send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some(&format!("{{\"id\":{},\"name\":\"x\"}}", id + 1)))
            .await
            .status,
        400
    );
    assert_eq!(send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some("{\"name\":\"x\"}")).await.status, 400);
    assert_eq!(send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some(&format!("{{\"id\":{},\"zz\":1}}", id)))
        .await
        .status, 404);
    assert_eq!(send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some("{")).await.status, 404);
    assert_eq!(send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN), Some("")).await.status, 404);
    assert_eq!(send("PUT", "/rest/roles/999999", Some(ADMIN), Some("{\"id\":999999}")).await.status, 404);
    assert_eq!(
        send("PUT", &format!("/rest/roles/{}", id), Some(USER), Some(&format!("{{\"id\":{},\"description\":\"h\"}}", id)))
            .await
            .status,
        404
    );
    // ignored properties are accepted
    assert_eq!(
        send("PUT", &format!("/rest/roles/{}", id), Some(ADMIN),
             Some(&format!("{{\"id\":{},\"created\":\"2001-01-01T00:00:00.000Z\",\"userPermissions\":{{}}}}", id)))
            .await
            .status,
        200
    );

    // DELETE
    assert_eq!(send("DELETE", &format!("/rest/roles/{}", id), Some(USER), None).await.status, 404);
    let r = send("DELETE", &format!("/rest/roles/{}", id), Some(ADMIN), None).await;
    assert_eq!(r.status, 204);
    assert_eq!(r.body, "");
    assert_eq!(send("DELETE", &format!("/rest/roles/{}", id), Some(ADMIN), None).await.status, 404);
    // deleting a referenced role fails (FK) -> 404
    assert_eq!(send("DELETE", "/rest/roles/2", Some(ADMIN), None).await.status, 404);
}

#[tokio::test]
async fn t07_crud_users() {
    let _g = lock();
    seed().await;

    let r = send("POST", "/rest/users", Some(ADMIN), Some(
        "{\"firstName\":\"New\",\"lastName\":\"User\",\"email\":\"nu@example.com\",\"accountName\":\"newuser_t07\",\"password\":\"secret\",\"active\":true,\"roles\":[{\"id\":2}],\"userGroups\":[6]}"))
        .await;
    assert_eq!(r.status, 201);
    let v = r.json();
    let uid = v["id"].as_i64().unwrap() as i32;
    assert_eq!(v["roles"][0]["id"], 2);
    assert_eq!(v["roles"][0]["name"], serde_json::Value::Null);
    assert_eq!(v["userGroups"], serde_json::json!([6]));
    let rows = query_rows(&format!(
        "SELECT u.accountname, u.password, u.active, p.email FROM users u JOIN persons p ON p.id=u.id WHERE u.id={}",
        uid
    )).await;
    assert_eq!(rows, vec!["newuser_t07|secret|true|nu@example.com".to_string()]);
    let rows = query_rows(&format!("SELECT role_id FROM users_roles WHERE user_id={}", uid)).await;
    assert_eq!(rows, vec!["2".to_string()]);
    let rows = query_rows(&format!("SELECT usergroup_id FROM user_usergroup WHERE user_id={}", uid)).await;
    assert_eq!(rows, vec!["6".to_string()]);

    // roles dedup by equals (same-ms parsed roles with null fields are equal)
    let r = send("POST", "/rest/users", Some(ADMIN), Some("{\"accountName\":\"dedup_t07\",\"roles\":[{\"id\":1},{\"id\":2}]}"))
        .await;
    assert_eq!(r.status, 201);
    let did = r.json()["id"].as_i64().unwrap();
    let rows = query_rows(&format!("SELECT role_id FROM users_roles WHERE user_id={}", did)).await;
    assert_eq!(rows.len(), 1, "roles should dedup: {:?}", rows);
    assert_eq!(rows[0], "1");

    // transient role (no id) -> 400 but consumes an id
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    assert_eq!(
        send("POST", "/rest/users", Some(ADMIN), Some("{\"accountName\":\"tr_t07\",\"roles\":[{\"name\":\"NEW\"}]}"))
            .await
            .status,
        400
    );
    assert_eq!(scalar_i64("SELECT next_val FROM hibernate_sequences").await, before + 1);
    // nonexistent userGroup -> parse-time failure, no id consumption
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    assert_eq!(
        send("POST", "/rest/users", Some(ADMIN), Some("{\"accountName\":\"bg_t07\",\"userGroups\":[999999]}"))
            .await
            .status,
        400
    );
    assert_eq!(scalar_i64("SELECT next_val FROM hibernate_sequences").await, before);
    // duplicate account name -> 400 (unique constraint), id consumed
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    assert_eq!(
        send("POST", "/rest/users", Some(ADMIN), Some("{\"accountName\":\"admin\"}")).await.status,
        400
    );
    assert_eq!(scalar_i64("SELECT next_val FROM hibernate_sequences").await, before + 1);
    // non-admin cannot create
    assert_eq!(
        send("POST", "/rest/users", Some(USER), Some("{\"accountName\":\"x_t07\"}")).await.status,
        400
    );

    // PUT: password/dates/roles/groups
    let r = send("PUT", &format!("/rest/users/{}", uid), Some(ADMIN), Some(&format!(
        "{{\"id\":{},\"password\":\"newpw\",\"language\":\"de\",\"birthday\":\"1990-01-31\",\"roles\":[{{\"id\":1}}],\"userGroups\":[5,6]}}",
        uid
    )))
    .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["birthday"], "1990-01-31");
    assert_eq!(r.json()["language"], "de");
    let rows = query_rows(&format!("SELECT password FROM users WHERE id={}", uid)).await;
    assert_eq!(rows, vec!["newpw".to_string()]);
    let rows = query_rows(&format!("SELECT birthday, language FROM persons WHERE id={}", uid)).await;
    assert_eq!(rows, vec!["1990-01-31|de".to_string()]);
    let rows = query_rows(&format!("SELECT usergroup_id FROM user_usergroup WHERE user_id={} ORDER BY 1", uid)).await;
    assert_eq!(rows, vec!["5".to_string(), "6".to_string()]);
    // null clears collection
    let r = send("PUT", &format!("/rest/users/{}", uid), Some(ADMIN), Some(&format!("{{\"id\":{},\"roles\":null}}", uid)))
        .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["roles"], serde_json::Value::Null);
    let rows = query_rows(&format!("SELECT role_id FROM users_roles WHERE user_id={}", uid)).await;
    assert!(rows.is_empty());
    // nonexistent group on PUT -> 404
    assert_eq!(
        send("PUT", &format!("/rest/users/{}", uid), Some(ADMIN), Some(&format!("{{\"id\":{},\"userGroups\":[999999]}}", uid)))
            .await
            .status,
        404
    );
    // self-update without UPDATE permission -> 404
    assert_eq!(
        send("PUT", "/rest/users/4", Some(USER), Some("{\"id\":4,\"firstName\":\"h\"}")).await.status,
        404
    );

    // DELETE cleans persons + users + join tables
    let r = send("DELETE", &format!("/rest/users/{}", uid), Some(ADMIN), None).await;
    assert_eq!(r.status, 204);
    assert!(query_rows(&format!("SELECT id FROM users WHERE id={}", uid)).await.is_empty());
    assert!(query_rows(&format!("SELECT id FROM persons WHERE id={}", uid)).await.is_empty());
    assert!(query_rows(&format!("SELECT * FROM user_usergroup WHERE user_id={}", uid)).await.is_empty());
    // deleting a user referenced by userpermissions -> 404 (FK)
    assert_eq!(send("DELETE", "/rest/users/4", Some(ADMIN), None).await.status, 404);
    // cleanup
    let _ = send("DELETE", &format!("/rest/users/{}", did), Some(ADMIN), None).await;
}

#[tokio::test]
async fn t08_crud_groups() {
    let _g = lock();
    seed().await;

    let r = send("POST", "/rest/groups", Some(ADMIN), Some(
        "{\"name\":\"G1_t08\",\"owner\":{\"id\":3},\"members\":[{\"id\":4}],\"roles\":[{\"id\":2}]}"))
        .await;
    assert_eq!(r.status, 201);
    let v = r.json();
    let gid = v["id"].as_i64().unwrap() as i32;
    assert_eq!(v["owner"]["id"], 3);
    assert_eq!(v["owner"]["accountName"], serde_json::Value::Null);
    let rows = query_rows(&format!("SELECT owner_id FROM usergroups WHERE id={}", gid)).await;
    assert_eq!(rows, vec!["3".to_string()]);
    let rows = query_rows(&format!("SELECT user_id FROM user_usergroup WHERE usergroup_id={}", gid)).await;
    assert_eq!(rows, vec!["4".to_string()]);
    let rows = query_rows(&format!("SELECT role_id FROM usergroups_roles WHERE usergroup_id={}", gid)).await;
    assert_eq!(rows, vec!["2".to_string()]);

    // two parsed members with null fields are equal -> dedup keeps the first
    let r = send("POST", "/rest/groups", Some(ADMIN), Some("{\"name\":\"G3_t08\",\"members\":[{\"id\":3},{\"id\":4}]}"))
        .await;
    assert_eq!(r.status, 201);
    let gid3 = r.json()["id"].as_i64().unwrap() as i32;
    assert_eq!(r.json()["members"].as_array().unwrap().len(), 1);
    assert_eq!(r.json()["members"][0]["id"], 3);
    let rows = query_rows(&format!("SELECT user_id FROM user_usergroup WHERE usergroup_id={}", gid3)).await;
    assert_eq!(rows, vec!["3".to_string()]);

    // transient member -> 400
    assert_eq!(
        send("POST", "/rest/groups", Some(ADMIN), Some("{\"name\":\"G2_t08\",\"members\":[{\"accountName\":\"z\"}]}"))
            .await
            .status,
        400
    );
    // non-admin cannot create
    assert_eq!(
        send("POST", "/rest/groups", Some(USER), Some("{\"name\":\"G4_t08\"}")).await.status,
        400
    );

    // PUT members replace; owner same id is fine (no cascade)
    let r = send("PUT", &format!("/rest/groups/{}", gid), Some(ADMIN), Some(&format!(
        "{{\"id\":{},\"members\":[{{\"id\":3}},{{\"id\":4}}],\"owner\":{{\"id\":3}}}}",
        gid
    )))
    .await;
    assert_eq!(r.status, 200);
    let rows = query_rows(&format!("SELECT user_id FROM user_usergroup WHERE usergroup_id={} ORDER BY 1", gid)).await;
    assert_eq!(rows.len(), 1, "parsed members dedup: {:?}", rows);

    // DELETE
    assert_eq!(send("DELETE", &format!("/rest/groups/{}", gid), Some(USER), None).await.status, 404);
    assert_eq!(send("DELETE", &format!("/rest/groups/{}", gid), Some(ADMIN), None).await.status, 204);
    assert!(query_rows(&format!("SELECT id FROM usergroups WHERE id={}", gid)).await.is_empty());
    assert!(query_rows(&format!("SELECT * FROM user_usergroup WHERE usergroup_id={}", gid)).await.is_empty());
    assert!(query_rows(&format!("SELECT * FROM usergroups_roles WHERE usergroup_id={}", gid)).await.is_empty());
    // group 6 is referenced by grouppermissions -> FK -> 404
    assert_eq!(send("DELETE", "/rest/groups/6", Some(ADMIN), None).await.status, 404);
    let _ = send("DELETE", &format!("/rest/groups/{}", gid3), Some(ADMIN), None).await;
}

#[tokio::test]
async fn t09_layers_and_appearances() {
    let _g = lock();
    seed().await;

    // POST datasource is always refused (abstract class)
    assert_eq!(
        send("POST", "/rest/layerdatasources", Some(ADMIN), Some("{\"name\":\"ds\",\"type\":\"TileWMS\"}"))
            .await
            .status,
        400
    );
    // layer with source object -> refused; with source null -> ok
    assert_eq!(
        send("POST", "/rest/layers", Some(ADMIN), Some("{\"name\":\"L_s\",\"source\":{\"type\":\"TileWMS\"}}"))
            .await
            .status,
        400
    );
    let r = send("POST", "/rest/layers", Some(ADMIN), Some("{\"name\":\"L_null\",\"source\":null}")).await;
    assert_eq!(r.status, 201);
    let l_null = r.json()["id"].as_i64().unwrap();
    assert_eq!(r.json()["source"], serde_json::Value::Null);

    // cascade creation: layer id N, appearance id N+1
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("POST", "/rest/layers", Some(ADMIN), Some(
        "{\"name\":\"L_cas\",\"description\":\"d\",\"appearance\":{\"name\":\"appa\",\"opacity\":0.5,\"visible\":true,\"properties\":{\"k\":\"v\",\"n\":\"42\"}}}"))
        .await;
    assert_eq!(r.status, 201);
    let v = r.json();
    assert_eq!(v["id"].as_i64().unwrap(), before + 1);
    assert_eq!(v["appearance"]["id"].as_i64().unwrap(), before + 2);
    assert_eq!(v["appearance"]["properties"]["n"], "42");
    let lid = v["id"].as_i64().unwrap() as i32;
    let aid = v["appearance"]["id"].as_i64().unwrap() as i32;
    let rows = query_rows(&format!("SELECT appearance_id FROM layers WHERE id={}", lid)).await;
    assert_eq!(rows, vec![aid.to_string()]);
    let rows = query_rows(&format!(
        "SELECT property, value FROM layerappearances_properties WHERE appearance_id={} ORDER BY property",
        aid
    ))
    .await;
    assert_eq!(rows, vec!["k|v".to_string(), "n|42".to_string()]);
    // on reload, PropertyValueConverter typing kicks in: "42" -> number 42
    let v = send("GET", &format!("/rest/layerappearances/{}", aid), Some(ADMIN), None).await.json();
    assert_eq!(v["properties"], serde_json::json!({"k": "v", "n": 42}));

    // appearance POST with boolean/number props
    let r = send("POST", "/rest/layerappearances", Some(ADMIN), Some(
        "{\"name\":\"ap_t09\",\"hoverable\":true,\"clickable\":false,\"maxResolution\":100.5,\"properties\":{\"t\":true,\"f\":1.25}}"))
        .await;
    assert_eq!(r.status, 201);
    let apid = r.json()["id"].as_i64().unwrap() as i32;
    let v = send("GET", &format!("/rest/layerappearances/{}", apid), Some(ADMIN), None).await.json();
    assert_eq!(v["properties"], serde_json::json!({"t": true, "f": 1.25}));
    // null property values are echoed but not persisted
    let r = send("POST", "/rest/layerappearances", Some(ADMIN), Some("{\"name\":\"ap_null\",\"properties\":{\"x\":null}}"))
        .await;
    assert_eq!(r.status, 201);
    let npid = r.json()["id"].as_i64().unwrap() as i32;
    assert_eq!(r.json()["properties"], serde_json::json!({"x": null}));
    assert!(query_rows(&format!("SELECT * FROM layerappearances_properties WHERE appearance_id={}", npid))
        .await
        .is_empty());

    // PUT properties replace (not merge)
    let r = send("PUT", &format!("/rest/layerappearances/{}", apid), Some(ADMIN), Some(&format!(
        "{{\"id\":{},\"properties\":{{\"z\":\"9\"}}}}",
        apid
    )))
    .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["name"], "ap_t09");
    let rows = query_rows(&format!(
        "SELECT property, value FROM layerappearances_properties WHERE appearance_id={}",
        apid
    ))
    .await;
    assert_eq!(rows, vec!["z|9".to_string()]);

    // PUT layer with new nested appearance -> created via cascade
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("PUT", &format!("/rest/layers/{}", lid), Some(ADMIN), Some(&format!(
        "{{\"id\":{},\"appearance\":{{\"name\":\"fresh\",\"opacity\":0.25}}}}",
        lid
    )))
    .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["appearance"]["id"].as_i64().unwrap(), before + 1);
    assert_eq!(r.json()["appearance"]["name"], "fresh");

    // re-attaching another existing appearance wipes it
    let r = send("PUT", &format!("/rest/layers/{}", lid), Some(ADMIN), Some(&format!(
        "{{\"id\":{},\"appearance\":{{\"id\":{}}}}}",
        lid, apid
    )))
    .await;
    assert_eq!(r.status, 200);
    let rows = query_rows(&format!("SELECT name, opacity, visible FROM layerappearances WHERE id={}", apid)).await;
    assert_eq!(rows, vec!["ap_t09|NULL|NULL".to_string()]);
    // re-attach with the CURRENT appearance id -> NonUniqueObject -> 404
    assert_eq!(
        send("PUT", &format!("/rest/layers/{}", lid), Some(ADMIN), Some(&format!(
            "{{\"id\":{},\"appearance\":{{\"id\":{}}}}}",
            lid, apid
        )))
        .await
        .status,
        404
    );

    // layer PUT with source object -> 404 (abstract), source null -> ok
    assert_eq!(
        send("PUT", &format!("/rest/layers/{}", lid), Some(ADMIN), Some(&format!("{{\"id\":{},\"source\":{{\"id\":12}}}}", lid)))
            .await
            .status,
        404
    );
    assert_eq!(
        send("PUT", &format!("/rest/layers/{}", lid), Some(ADMIN), Some(&format!("{{\"id\":{},\"source\":null}}", lid)))
            .await
            .status,
        200
    );

    // permissions: user has UPDATE on layer 15
    assert_eq!(
        send("PUT", "/rest/layers/15", Some(USER), Some("{\"id\":15,\"description\":\"by-user\"}"))
            .await
            .status,
        200
    );
    // but no DELETE
    assert_eq!(send("DELETE", "/rest/layers/15", Some(USER), None).await.status, 404);
    // group has READ+DELETE on 16, but the layer is in map 28 and the user
    // lacks UPDATE on the map (LayerService.delete saves each map) -> 404
    assert_eq!(send("DELETE", "/rest/layers/16", Some(USER), None).await.status, 404);
    assert_eq!(query_rows("SELECT id FROM layers WHERE id=16").await, vec!["16".to_string()]);
    // ADMIN entity permission (appearance 14, user 4) -> PUT allowed
    assert_eq!(
        send("PUT", "/rest/layerappearances/14", Some(USER), Some("{\"id\":14,\"name\":\"adm\"}"))
            .await
            .status,
        200
    );
    // deleting a referenced appearance -> 404
    assert_eq!(send("DELETE", "/rest/layerappearances/14", Some(ADMIN), None).await.status, 404);

    // admin can delete a layer inside a map; maps_layers rows are removed
    assert_eq!(send("DELETE", "/rest/layers/16", Some(ADMIN), None).await.status, 204);
    assert!(query_rows("SELECT * FROM maps_layers WHERE layer_id=16").await.is_empty());
    assert!(query_rows("SELECT id FROM layers WHERE id=16").await.is_empty());
    // appearance survives the layer delete
    assert_eq!(query_rows("SELECT id FROM layerappearances WHERE id=14").await, vec!["14".to_string()]);

    // cleanup
    let _ = send("DELETE", &format!("/rest/layers/{}", lid), Some(ADMIN), None).await;
    let _ = send("DELETE", &format!("/rest/layers/{}", l_null), Some(ADMIN), None).await;
    let _ = send("DELETE", &format!("/rest/layerappearances/{}", aid), Some(ADMIN), None).await;
    let _ = send("DELETE", &format!("/rest/layerappearances/{}", apid), Some(ADMIN), None).await;
    let _ = send("DELETE", &format!("/rest/layerappearances/{}", npid), Some(ADMIN), None).await;
}

#[tokio::test]
async fn t10_datasource_updates() {
    let _g = lock();
    seed().await;

    // basic field update on the dedicated TileWMS source
    let r = send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some(
        "{\"id\":1101,\"url\":\"http://new/\",\"layerNames\":\"NL\"}"))
        .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["url"], "http://new/");
    assert_eq!(r.json()["width"], 256);
    let rows = query_rows("SELECT url FROM layerdatasources WHERE id=1101").await;
    assert_eq!(rows, vec!["http://new/".to_string()]);
    let rows = query_rows("SELECT layernames FROM imagewmslayerdatasources WHERE id=1101").await;
    assert_eq!(rows, vec!["NL".to_string()]);

    // unknown field for this subtype -> 404
    assert_eq!(
        send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some("{\"id\":1101,\"typeName\":\"x\"}"))
            .await
            .status,
        404
    );
    // string -> int coercion
    assert_eq!(
        send("PUT", "/rest/layerdatasources/1102", Some(ADMIN), Some("{\"id\":1102,\"width\":\"300\"}"))
            .await
            .status,
        200
    );
    let rows = query_rows("SELECT width FROM imagewmslayerdatasources WHERE id=1102").await;
    assert_eq!(rows, vec!["300".to_string()]);

    // tileGrid conflict (same id as currently loaded) -> 404
    assert_eq!(
        send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some("{\"id\":1101,\"tileGrid\":{\"id\":1111}}"))
            .await
            .status,
        404
    );
    // tileGrid null clears FK
    assert_eq!(
        send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some("{\"id\":1101,\"tileGrid\":null}"))
            .await
            .status,
        200
    );
    assert_eq!(
        query_rows("SELECT tilegrid_id FROM tilewmslayerdatasources WHERE id=1101").await,
        vec!["NULL".to_string()]
    );
    // new tileGrid via cascade (constructor default tileSize=256)
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some(
        "{\"id\":1101,\"tileGrid\":{\"type\":\"TileGrid\",\"tileGridResolutions\":[4.0,2.0]}}"))
        .await;
    assert_eq!(r.status, 200);
    let tgid = r.json()["tileGrid"]["id"].as_i64().unwrap();
    assert_eq!(tgid, before + 1);
    assert_eq!(r.json()["tileGrid"]["tileSize"], 256);
    let rows = query_rows(&format!(
        "SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id={} ORDER BY idx",
        tgid
    ))
    .await;
    assert_eq!(rows, vec!["4".to_string(), "2".to_string()]);

    // re-attaching the WMTS grid 1112 as a plain TileGrid wipes only the base
    // row (subclass data stays), matching Hibernate's re-attach behaviour
    let r = send("PUT", "/rest/layerdatasources/1101", Some(ADMIN), Some(
        "{\"id\":1101,\"tileGrid\":{\"id\":1112}}"))
        .await;
    assert_eq!(r.status, 200);
    let rows = query_rows("SELECT type, tilesize FROM tilegrids WHERE id=1112").await;
    assert_eq!(rows, vec!["NULL|256".to_string()]);
    let rows = query_rows("SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id=1112").await;
    assert_eq!(rows, vec!["m0".to_string()]);

    // WMTS urls replace
    let r = send("PUT", "/rest/layerdatasources/1103", Some(ADMIN), Some(
        "{\"id\":1103,\"urls\":[\"http://a\",\"http://b\",\"http://c\"]}"))
        .await;
    assert_eq!(r.status, 200);
    let rows = query_rows("SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id=1103").await;
    assert_eq!(
        rows,
        vec!["http://a".to_string(), "http://b".to_string(), "http://c".to_string()]
    );

    // WMTS new tileGrid with nested extent cascade; ids echo in the response
    let before = scalar_i64("SELECT next_val FROM hibernate_sequences").await;
    let r = send("PUT", "/rest/layerdatasources/1103", Some(ADMIN), Some(
        "{\"id\":1103,\"tileGrid\":{\"type\":\"WMTS\",\"tileSize\":256,\"matrixIds\":[\"a\",\"b\"],\"tileGridResolutions\":[1.0,2.5],\"tileGridExtent\":{\"lowerLeft\":{\"x\":1,\"y\":2},\"upperRight\":{\"x\":3,\"y\":4}}}}"))
        .await;
    assert_eq!(r.status, 200);
    let tg = &r.json()["tileGrid"];
    assert_eq!(tg["id"].as_i64().unwrap(), before + 1);
    assert_eq!(tg["tileGridExtent"]["id"].as_i64().unwrap(), before + 2);
    assert_eq!(tg["matrixIds"], serde_json::json!(["a", "b"]));
    assert_eq!(tg["tileGridResolutions"], serde_json::json!([1.0, 2.5]));
    let rows = query_rows("SELECT tilegrid_id FROM wmtslayerdatasources WHERE id=1103").await;
    assert_eq!(rows, vec![(before + 1).to_string()]);

    // XYZ updates
    let r = send("PUT", "/rest/layerdatasources/1104", Some(ADMIN), Some(
        "{\"id\":1104,\"center\":{\"x\":9,\"y\":8},\"tileSize\":512,\"extent\":{\"id\":1011}}"))
        .await;
    assert_eq!(r.status, 200);
    assert_eq!(r.json()["center"], serde_json::json!({"x": 9.0, "y": 8.0}));
    let rows = query_rows("SELECT center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources WHERE id=1104").await;
    assert_eq!(rows, vec!["9|8|512|1011".to_string()]);
    // transient extent (no id) -> 404
    assert_eq!(
        send("PUT", "/rest/layerdatasources/1104", Some(ADMIN), Some(
            "{\"id\":1104,\"extent\":{\"lowerLeft\":{\"x\":0,\"y\":0}}}"))
            .await
            .status,
        404
    );

    // deletes: unreferenced ok, referenced -> 404
    assert_eq!(send("DELETE", "/rest/layerdatasources/1102", Some(ADMIN), None).await.status, 204);
    assert!(query_rows("SELECT id FROM imagewmslayerdatasources WHERE id=1102").await.is_empty());
    assert!(query_rows("SELECT id FROM layerdatasources WHERE id=1102").await.is_empty());
    assert_eq!(send("DELETE", "/rest/layerdatasources/12", Some(ADMIN), None).await.status, 404);
    // non-admin lacks DELETE -> 404
    assert_eq!(send("DELETE", "/rest/layerdatasources/1002", Some(USER), None).await.status, 404);

    // WMTS delete cleans urls
    assert_eq!(send("DELETE", "/rest/layerdatasources/1103", Some(ADMIN), None).await.status, 204);
    assert!(query_rows("SELECT * FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id=1103")
        .await
        .is_empty());
    // XYZ delete cleans resolutions
    assert_eq!(send("DELETE", "/rest/layerdatasources/1104", Some(ADMIN), None).await.status, 204);
    assert!(query_rows("SELECT id FROM xyzlayerdatasources WHERE id=1104").await.is_empty());
}

#[tokio::test]
async fn t11_fallbacks_and_methods() {
    let _g = lock();
    seed().await;

    assert_eq!(send("GET", "/rest/unknown", Some(ADMIN), None).await.status, 404);
    assert_eq!(send("GET", "/rest/unknown", Some(USER), None).await.status, 403);
    assert_eq!(send("GET", "/rest/unknown", None, None).await.status, 401);
    assert_eq!(send("GET", "/rest/users/4/nope", Some(USER), None).await.status, 404);
    // 401 for PUT/DELETE has an empty body (Jetty quirk), GET/POST an HTML page
    let r = send("PUT", "/rest/unknown", None, Some("{}")).await;
    assert_eq!(r.status, 401);
    assert_eq!(r.body, "");
    let r = send("GET", "/rest/unknown", None, None).await;
    assert!(!r.body.is_empty());
}
