}""", """static SEEDED: AtomicBool = AtomicBool::new(false);
static LOCK: Mutex<()> = Mutex::new(());

fn lock() -> MutexGuard<'static, ()> {
    LOCK.lock().unwrap_or_else(|e| e.into_inner())
}

/// One shared runtime for all tests: tokio-postgres spawns its connection
/// driver tasks on the runtime that created them, so a per-test runtime would
/// kill pooled connections when the test ends.
fn rt() -> &'static tokio::runtime::Runtime {
    static RT: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    RT.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .worker_threads(4)
            .build()
            .unwrap()
    })
}""")

# 2. convert #[tokio::test] async fn tXX() { ... } to #[test] fn tXX() { rt().block_on(async { ... }) }
def convert(m):
    name = m.group(1)
    body = m.group(2)
    # dedent body by 4
    lines = body.split('\n')
    out = []
    for l in lines:
        if l.startswith('    '):
            out.append(l[4:])
        elif l.strip() == '':
            out.append('')
        else:
            out.append(l)
    body2 = '\n'.join('    ' + l if l.strip() else l for l in out)
    return f"#[test]\nfn {name}() {{\n    rt().block_on(async {{\n{body2}\n    }});\n}}"

pattern = re.compile(r"#\[tokio::test\]\nasync fn (t\w+)\(\) \{\n(.*?)\n\}\n", re.S)
s = pattern.sub(lambda m: convert(m) + "\n", s)

open('tests/api.rs','w').write(s)
print("converted:", len(pattern.findall(open('tests/api.rs').read())) )
