/// PropertyValueConverter.convertToEntityAttribute.
/// Returns Err when the conversion throws (e.g. Long overflow), which makes
/// the original's entity load fail (404 for single reads, 500 for lists).
pub fn property_value_from_db(s: &str) -> Result<crate::jval::JVal, String> {
    use crate::jval::JVal;
    if s.eq_ignore_ascii_case("true") {
        return Ok(JVal::Bool(true));
    }
    if s.eq_ignore_ascii_case("false") {
        return Ok(JVal::Bool(false));
    }
    if is_parsable_number(s) {
        let body = s.strip_prefix('-').unwrap_or(s);
        if !body.is_empty() && body.chars().all(|ch| ch.is_ascii_digit()) {
            // NumberUtils.isDigits -> Long.parseLong (throws on overflow)
            match s.parse::<i64>() {
                Ok(v) => return Ok(JVal::Int(v, s.to_string())),
                Err(_) => {
                    return Err(format!(
                        "Error attempting to apply AttributeConverter: For input string: \"{}\"",
                        s
                    ))
                }
            }
        }
        match s.parse::<f64>() {
            Ok(v) => return Ok(JVal::Float(v, s.to_string())),
            Err(_) => {
                return Err(format!(
                    "Error attempting to apply AttributeConverter: For input string: \"{}\"",
                    s
                ))
            }
        }
    }
    Ok(JVal::Str(s.to_string()))
}

