/// PropertyValueConverter.convertToEntityAttribute
pub fn property_value_from_db(s: &str) -> crate::jval::JVal {
    use crate::jval::JVal;
    if s.eq_ignore_ascii_case("true") {
        return JVal::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return JVal::Bool(false);
    }
    if is_parsable_number(s) {
        let body = s.strip_prefix('-').unwrap_or(s);
